def clean_author_name(author_str):
    if not author_str:
        return "Unidentified"
    try:
        if author_str.startswith("[") and author_str.endswith("]"):
            parsed = json.loads(author_str.replace("'", '"'))
            if isinstance(parsed, list):
                return ", ".join([str(a).strip() for a in parsed if str(a).strip()])
    except Exception:
        pass
    cleaned = (
        author_str.replace("[", "")
        .replace("]", "")
        .replace("'", "")
        .replace('"', "")
    )
    return cleaned.strip()

def is_likely_institution(name):
    if not name:
        return True
    lower_name = name.lower()
    inst_keywords = [
        "university", "univ.", "college", "institute", "inst.",
        "department", "dept.", "laboratory", "lab", "hospital",
        "center", "centre", "faculty", "milano", "bicocca",
        "polytechnic", "academy", "school", "corporation", "inc",
        "llc", "ltd", "foundation", "fund", "council", "cnr",
        "inps", "iss", "università",
    ]
    for kw in inst_keywords:
        pattern = r'\b' + re.escape(kw.rstrip('.')) + r'\b'
        if re.search(pattern, lower_name):
            return True
    return False

def fetch_core_text_by_doi(doi):
    if not doi or doi == "None":
        return None
    
    clean_doi = doi.replace("https://doi.org/", "").strip()
    url = f"https://api.core.ac.uk/v3/search/works?q=doi:{clean_doi}"
    headers = {"User-Agent": "Pi-Index-Engine/1.0"}
    
    try:
        res = requests.get(url, headers=headers, timeout=10)
        if res.status_code == 200:
            data = res.json()
            results = data.get("results", [])
            if results:
                paper_data = results[0]
                text = paper_data.get("fullText") or paper_data.get("abstract")
                if text and len(text.strip()) > 200:
                    return text
    except Exception:
        pass
        
    return None

def build_pdf_from_text(text, title="CORE Open Access Text"):
    if not integrations_FITZ_AVAILABLE:
        return None
    try:
        doc = integrations_fitz.open()
        rect = integrations_fitz.Rect(50, 50, 550, 800)
        remaining = f"Title: {title}\n\n{text}"
        max_pages = 200

        for _ in range(max_pages):
            page = doc.new_page()
            leftover = page.insert_textbox(rect, remaining, fontsize=10, fontname="helv")
            if leftover >= 0:
                break

            fitted_chars = estimate_characters_per_page(remaining, rect, fontsize=10)
            if fitted_chars <= 0:
                break
            remaining = remaining[fitted_chars:]

        pdf_bytes = doc.write()
        doc.close()
        return pdf_bytes
    except Exception:
        return None

def estimate_characters_per_page(text, rect, fontsize):
    try:
        chars_per_line = max(1, int(rect.width / (fontsize * 0.5)))
        lines_per_page = max(1, int(rect.height / (fontsize * 1.2)))
        return chars_per_line * lines_per_page
    except Exception:
        return len(text)


def normalize_doi(raw):
    """Strip URL prefixes so a DOI is always a bare identifier."""
    if not raw:
        return ""
    return (str(raw).replace("https://doi.org/", "")
            .replace("http://doi.org/", "")
            .replace("doi.org/", "").strip())


def collect_pdf_candidates(work):
    """Every plausible full-text URL for an OpenAlex work, best first.

    Retrieval previously used a single URL — `best_oa_location.pdf_url` or the
    generic `oa_url`. That field is frequently a landing page rather than a
    PDF, and when it was absent or unusable the paper simply failed with no
    fallback, which is why auto-discovered papers so often could not be
    retrieved. OpenAlex usually lists several locations (publisher, repository,
    preprint server); trying them in order of directness recovers most of them.
    """
    candidates, seen = [], set()

    def add(url):
        if url and url not in seen:
            seen.add(url)
            candidates.append(url)

    # Direct PDF links first — these need no further resolution.
    for loc in ([work.get("best_oa_location"), work.get("primary_location")]
                + list(work.get("locations") or [])):
        if isinstance(loc, dict):
            add(loc.get("pdf_url"))

    # Then landing pages, which download_pdf can often resolve.
    for loc in ([work.get("best_oa_location"), work.get("primary_location")]
                + list(work.get("locations") or [])):
        if isinstance(loc, dict):
            add(loc.get("landing_page_url"))

    add((work.get("open_access") or {}).get("oa_url"))
    return candidates


def search_open_access_works(topic_query, limit=100):
    """Back-compatible wrapper: results only, errors swallowed.

    Kept because the cron and idle paths only want a list and have nowhere to
    put a reason. Anything user-facing should call search_scholarly_works and
    show the reason.
    """
    results, _err = search_scholarly_works(topic_query, limit=limit)
    return results


def search_scholarly_works(topic_query, limit=100):
    """Find open-access papers. Returns ``(results, error)``.

    Two providers, tried in order, because one upstream is a single point of
    failure for a feature the user experiences as "search is broken". OpenAlex
    is preferred — it reports open-access status and usually a direct PDF —
    and Crossref backs it up: no PDF links, but a DOI is enough for the
    pipeline to retrieve the paper itself.

    The ERROR IS RETURNED RATHER THAN LOGGED AND DISCARDED. Previously every
    failure — a 403 from the provider, a DNS failure on a locked-down host, a
    timeout, a genuinely empty topic — collapsed into an empty list, and the
    interface said "No open-access papers found for X. Try a broader topic."
    for all of them. That sentence sends someone to rephrase their query when
    the actual problem is that the server cannot reach the internet.
    """
    results, error = _search_openalex(topic_query, limit)
    if results:
        return results, ""

    fallback, fb_error = _search_crossref(topic_query, limit)
    if fallback:
        return fallback, ""

    # Neither worked. Prefer the first provider's reason; it is the one whose
    # absence actually explains the outcome.
    return [], (error or fb_error or "")


def _search_openalex(topic_query, limit):
    params = {
        "search": topic_query,
        "filter": "is_oa:true,has_doi:true",
        "per_page": min(int(limit), 50),
        "sort": "relevance_score:desc",
    }
    try:
        res = requests.get("https://api.openalex.org/works", params=params,
                           headers={"User-Agent": "ScholarPi-PiIndex/2.2 (mailto:research@pi-index.org)"},
                           timeout=12)
    except requests.RequestException as e:
        return [], f"OpenAlex could not be reached ({type(e).__name__})."
    if res.status_code != 200:
        # The body carries OpenAlex's own explanation of a rejected query,
        # which is far more useful than the status code alone.
        detail = ""
        try:
            detail = (res.json().get("message") or "")[:160]
        except Exception:                                        # noqa: BLE001
            detail = (res.text or "")[:160]
        return [], f"OpenAlex returned HTTP {res.status_code}. {detail}".strip()

    try:
        items = res.json().get("results", [])
    except ValueError:
        return [], "OpenAlex returned a response that could not be parsed."

    extracted = []
    for item in items:
        doi = normalize_doi(item.get("doi", ""))
        candidates = collect_pdf_candidates(item)
        if not doi and not candidates:
            continue
        authors = [a.get("author", {}).get("display_name", "")
                   for a in (item.get("authorships") or [])]
        extracted.append({
            "title": item.get("title") or "Untitled Paper",
            "doi": doi,
            # Kept for backward compatibility with existing callers.
            "pdf_url": candidates[0] if candidates else "",
            "pdf_candidates": candidates[:5],
            "authors": ", ".join(a for a in authors if a) or "Unidentified",
            "year": item.get("publication_year"),
            "oa_status": (item.get("open_access") or {}).get("oa_status"),
            "source": "OpenAlex",
        })
    if not extracted:
        return [], ""          # a real empty result, not a failure
    return extracted, ""


def _search_crossref(topic_query, limit):
    """Crossref fallback. No PDF URLs, but a DOI the pipeline can resolve."""
    params = {
        "query.bibliographic": topic_query,
        "rows": min(int(limit), 30),
        "filter": "has-full-text:true,type:journal-article",
        "select": "DOI,title,author,issued",
    }
    try:
        res = requests.get("https://api.crossref.org/works", params=params,
                           headers={"User-Agent": "ScholarPi-PiIndex/2.2 (mailto:research@pi-index.org)"},
                           timeout=12)
    except requests.RequestException as e:
        return [], f"Crossref could not be reached either ({type(e).__name__})."
    if res.status_code != 200:
        return [], f"Crossref returned HTTP {res.status_code}."

    try:
        items = (res.json().get("message") or {}).get("items", [])
    except ValueError:
        return [], "Crossref returned a response that could not be parsed."

    out = []
    for it in items:
        doi = normalize_doi(it.get("DOI", ""))
        if not doi:
            continue
        title = (it.get("title") or ["Untitled Paper"])
        names = []
        for a in (it.get("author") or []):
            n = " ".join(x for x in [a.get("given"), a.get("family")] if x).strip()
            if n:
                names.append(n)
        year = None
        try:
            year = (it.get("issued") or {}).get("date-parts", [[None]])[0][0]
        except Exception:                                        # noqa: BLE001
            year = None
        out.append({
            "title": (title[0] if isinstance(title, list) and title else "Untitled Paper"),
            "doi": doi,
            "pdf_url": "",
            "pdf_candidates": [],
            "authors": ", ".join(names) or "Unidentified",
            "year": year,
            "oa_status": "unknown",
            "source": "Crossref",
        })
    return out, ""


def fetch_doi_metadata(doi):
    clean_doi = (
        doi.replace("https://doi.org/", "").replace("doi.org/", "").strip()
    )
    unpaywall_url = (
        f"https://api.unpaywall.org/v2/{clean_doi}?email=research@pi-index.org"
    )
    try:
        response = requests.get(unpaywall_url, timeout=10)
        if response.status_code == 200:
            res = response.json()
            title = res.get("title", "Unknown Title")
            authors_list = res.get("z_authors", [])
            authors = (
                ", ".join([a.get("family", "") for a in authors_list])
                if authors_list
                else "Unknown Author"
            )
            pdf_url = (
                res.get("best_oa_location", {}).get("url_for_pdf", None)
                if res.get("best_oa_location")
                else None
            )
            return {"title": title, "authors": authors, "pdf_url": pdf_url}
        return None
    except Exception:
        return None

def fetch_semantic_scholar_pdf(title_or_doi):
    if not title_or_doi:
        return None
    try:
        clean_query = title_or_doi.replace("https://doi.org/", "").strip()
        url = f"https://api.semanticscholar.org/graph/v1/paper/search?query={requests.utils.quote(clean_query)}&limit=1&fields=openAccessPdf,externalIds"
        res = requests.get(url, timeout=10)
        if res.status_code == 200:
            data = res.json().get("data", [])
            if data:
                oa_pdf = data[0].get("openAccessPdf")
                if oa_pdf and oa_pdf.get("url"):
                    return oa_pdf["url"]
    except Exception:
        pass
    return None

# Manuscript URLs come from visitors (Discover, a pasted link) and from third-party metadata, and the server fetches
# them. So a fetch goes only to http(s) on public addresses, every redirect is checked the same way, and the body is
# read in pieces up to a cap, rather than whole into memory. Before this, any URL was fetched, redirects followed,
# which let a visitor reach the deployment's private network and hand it endless bodies.
MAX_FETCH_BYTES = int(float(os.getenv("MAX_FETCH_MB", str(max(MAX_UPLOAD_MB, 50)))) * 1024 * 1024)


def public_url(url: str) -> bool:
    """True when `url` is http(s) and every address its host resolves to is a public one."""
    try:
        parts = urllib.parse.urlsplit(url)
    except ValueError:
        return False
    if parts.scheme not in ("http", "https") or not parts.hostname:
        return False
    try:
        port = parts.port or (443 if parts.scheme == "https" else 80)
        infos = socket.getaddrinfo(parts.hostname, port, proto=socket.IPPROTO_TCP)
    except (OSError, ValueError, UnicodeError):
        return False
    if not infos:
        return False
    for info in infos:
        try:
            addr = ipaddress.ip_address(info[4][0].split("%", 1)[0])
        except ValueError:
            return False
        if getattr(addr, "ipv4_mapped", None):
            addr = addr.ipv4_mapped
        if not addr.is_global or addr.is_multicast:
            return False
    return True


def fetch_public(session, url: str, headers: dict = None, timeout: float = 15, max_bytes: int = None,
                 redirects: int = 5):
    """GET a public URL, checking every hop; (response, body) or (None, None). The body stops at `max_bytes`."""
    max_bytes = max_bytes or MAX_FETCH_BYTES
    for _ in range(redirects + 1):
        if not public_url(url):
            logging.info("Fetch refused, not a public http(s) address: %s", url[:200])
            return None, None
        res = session.get(url, headers=headers, timeout=timeout, allow_redirects=False, stream=True)
        if res.is_redirect or res.status_code in (301, 302, 303, 307, 308):
            nxt = res.headers.get("Location", "")
            res.close()
            if not nxt:
                return None, None
            url = urllib.parse.urljoin(url, nxt)
            continue
        declared = res.headers.get("Content-Length", "")
        if declared.isdigit() and int(declared) > max_bytes:
            res.close()
            return None, None
        body = bytearray()
        for chunk in res.iter_content(chunk_size=65536):
            body.extend(chunk)
            if len(body) > max_bytes:
                res.close()
                return None, None
        return res, bytes(body)
    return None, None


def download_pdf(pdf_url):
    if not pdf_url:
        return None

    if "arxiv.org/abs/" in pdf_url:
        pdf_url = pdf_url.replace("/abs/", "/pdf/") + ".pdf"
    elif (
        "ncbi.nlm.nih.gov/pmc/articles/PMC" in pdf_url
        and not pdf_url.endswith(".pdf")
    ):
        parts = pdf_url.split("PMC")
        if len(parts) > 1:
            pmc_id = parts[1].split("/")[0]
            pdf_url = f"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC{pmc_id}/pdf/"

    headers = {
        "User-Agent": (
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML,"
            " like Gecko) Chrome/122.0.0.0 Safari/537.36"
        ),
        "Accept": (
            "text/html,application/xhtml+xml,application/pdf;q=0.9,image/avif,image/webp,*/*;q=0.8"
        ),
        "Accept-Language": "en-US,en;q=0.5",
        "Referer": "https://scholar.google.com/",
        "Connection": "keep-alive",
    }

    def is_pdf(res, content):
        content_type = res.headers.get("Content-Type", "").lower()
        return res.status_code == 200 and (b"%PDF" in content[:10] or "application/pdf" in content_type)

    try:
        res, content = fetch_public(requests.Session(), pdf_url, headers=headers, timeout=15)
        if res is not None and is_pdf(res, content):
            return content
        if res is None:
            # refused (not public, too large) or a dead end; a browser-like client would get no further
            return None
    except Exception:
        pass

    if CLOUDSCRAPER_AVAILABLE:
        try:
            scraper = cloudscraper.create_scraper(
                browser={"browser": "chrome", "platform": "windows", "desktop": True}
            )
            res, content = fetch_public(scraper, pdf_url, timeout=20)
            if res is not None and is_pdf(res, content):
                return content
        except Exception:
            pass

    return None


