# Must happen BEFORE numpy/torch are imported below — these libraries read
# these env vars once, at import time, to size their internal thread pools.
# On a memory-constrained host (e.g. a 512MB container), the default thread
# count (based on the host's *reported* CPU count, which is often
# misleading in shared/containerized environments) allocates far more
# thread-local memory than a small instance can spare. Capping at 1 is a
# meaningful, low-risk memory reduction for this app's actual workload
# (small MLP/LSTM forward passes, not large batch training).
os.environ.setdefault("OMP_NUM_THREADS", "1")
os.environ.setdefault("MKL_NUM_THREADS", "1")
os.environ.setdefault("OPENBLAS_NUM_THREADS", "1")
os.environ.setdefault("NUMEXPR_NUM_THREADS", "1")



# ---------------------------------------------------------------------------
# PyTorch is loaded on demand, not at import time.
# ---------------------------------------------------------------------------
# Importing torch costs roughly 300-400MB of resident memory before a single
# request is served. That was being paid unconditionally by every worker, on
# every deployment, to support ONE optional feature: the LSTM forecast, which
# is off by default (USE_LSTM_FORECAST) and whose statistical fallback is pure
# NumPy. Everything else in this module — scoring, extraction, the provider
# panel, the ledger — never touches torch at all.
#
# On a 512MB host that import is most of the budget, so the worker was being
# OOM-killed part-way through requests. A killed worker drops the connection
# without a response, which the browser reports as "could not reach the
# service" — a network-shaped symptom for what is actually a memory problem,
# which is why it looked like an intermittent host fault rather than a
# configuration one.
#
# Deferring the import means a deployment that never enables the LSTM never
# pays for it, and one that does enable it pays only on the first forecast.
_TORCH = None
_TORCH_FAILED = False


def load_torch():
    """Import torch on first use. Returns None if unavailable.

    Callers must treat None as "use the statistical path", never as an error:
    a deployment that deliberately omits torch to fit in memory is a supported
    configuration, not a broken one.
    """
    global _TORCH, _TORCH_FAILED
    if _TORCH is not None or _TORCH_FAILED:
        return _TORCH
    try:
        import torch
        import torch.nn as nn
        import torch.optim as optim
        from torch.utils.data import Dataset, DataLoader
        torch.set_num_threads(1)  # some backends ignore the env vars set above
        _TORCH = {"torch": torch, "nn": nn, "optim": optim,
                  "Dataset": Dataset, "DataLoader": DataLoader}
    except Exception as e:
        _TORCH_FAILED = True
        logging.info("PyTorch unavailable; forecasting will use the statistical path: %s", e)
        return None
    return _TORCH



# NOTE: the `openrouter` SDK was imported here and never used. OpenRouter is
# reached through the OpenAI-compatible client like every other provider, so
# the package was installed on every deploy to support nothing. Removed from
# both this module and requirements.txt.



def measure_structural_signals(paper_text: str) -> dict:
    """The four deterministic measurements SciLM (siM) is built on.

    Kept separate from the scoring step because these are the auditable part:
    identical text always produces identical signals, and nothing learned is
    allowed to change them. Only their relative WEIGHTING is learned.
    """
    if not paper_text or not paper_text.strip():
        return {"mdar": 0.0, "density": 0.0, "repro": 0.0, "rrid": 0.0}
    mdar, rrid_count = measure_mdar_adherence(paper_text)
    repro, _ = measure_reproducibility_markers(paper_text)
    density = measure_empirical_density(paper_text)
    return {
        "mdar": float(mdar),
        "density": float(density),
        "repro": float(repro),
        "rrid": min(1.0, rrid_count / 5.0),
    }


def compute_structural_quality(paper_text: str) -> float:
    """Composite structural quality under the current learned weighting."""
    signals = measure_structural_signals(paper_text)
    if not any(signals.values()):
        return 0.0
    try:
        return predict(signals)
    except Exception as e:
        # A learning failure must never take down scoring. Fall back to the
        # authored weights, which is exactly what the model started from.
        logging.warning("SciLM (siM) learned weighting unavailable, using defaults: %s", e)
        return round(min(1.0, max(0.0,
            (signals["mdar"] * 0.35) + (signals["density"] * 0.30)
            + (signals["repro"] * 0.25) + (signals["rrid"] * 0.10))), 6)

def assess_with_structural_analyzer(paper_text, canary=""):
    scilem_numeric_score = compute_structural_quality(paper_text) * 100.0

    lines = [l.strip() for l in paper_text.split("\n") if l.strip()]
    cand_title = lines[0] if lines else "SciLM (siM) Neural Extraction"
    cand_author = "Independent Research Scholar"
    for line in lines[1:10]:
        if any(kw in line.lower() for kw in ["by", "author", "university", "department", "@"]):
            cand_author = line
            break

    mdar_signal, rrid_signal = measure_mdar_adherence(paper_text)
    repro_signal, repro_flags = measure_reproducibility_markers(paper_text)
    density_signal = measure_empirical_density(paper_text)
    detected_markers = [k.replace("_", " ") for k, v in repro_flags.items() if v]

    opinion = (
        f"SciLM (siM) Structural Analysis: composite structural quality = "
        f"{scilem_numeric_score:.1f}/100, computed deterministically from the checks below. "
        f"Deterministic MDAR/RRID adherence measured at {mdar_signal * 100:.1f}% ({rrid_signal} valid RRID token(s)). "
        f"Empirical density signal (statistics, sample sizes, quantitative results) measured at {density_signal * 100:.1f}%. "
        f"Open-science reproducibility markers detected: "
        f"{', '.join(detected_markers) if detected_markers else 'none found in extracted text'} "
        f"(composite reproducibility signal {repro_signal * 100:.1f}%)."
    )

    return "scilem", {
        "title": cand_title[:120],
        "authors": _truncate_author_list(clean_author_name(cand_author), 80),
        "opinion": opinion,
        "references": [],
        "api_failed": False,
        "is_heuristic_fallback": True,
        "scilem_score": scilem_numeric_score,
    }

def content_fingerprint(text: str) -> str:
    """A hash that identifies the WORK rather than the file it arrived in.

    eval_hash is sha256 of the uploaded bytes. That is the right key for "have
    I seen this exact file", and the wrong one for "have I seen this paper" —
    re-exporting a PDF, downloading it from a different host, or opening and
    saving it in a viewer changes the bytes without changing a word of the
    scholarship.

    Normalisation is deliberately aggressive, because everything it discards is
    something that varies between two copies of one paper while carrying no
    scholarly content:

      * case, which viewers and OCR settings alter;
      * all whitespace, since line breaks land differently at different page
        sizes and column widths;
      * every non-alphanumeric character, which absorbs ligature handling,
        smart quotes, hyphenation at line ends and bullet glyphs.

    What survives is the letters and digits of the manuscript in order. Two
    files agreeing on that are the same paper. The residual risk runs one way
    only: heavy normalisation can make two *different* papers collide, so this
    is not used alone to overwrite anything — it selects an existing record to
    merge into, and a real revision with changed text simply will not match.

    An empty or unreadable extraction returns "" and merges nothing. A scanned
    PDF with no text layer must not be treated as identical to every other
    scanned PDF with no text layer.
    """
    # NFKD first, so typographic ligatures decompose to their letters. A PDF
    # that preserves "ﬀ" as one glyph and one that emits "ff" are the same two
    # letters, but stripping non-ASCII without decomposing first would delete
    # the glyph entirely and silently change the hash.
    normalised = unicodedata.normalize("NFKD", (text or "").lower())
    normalised = re.sub(r"[^a-z0-9]+", "", normalised)
    if len(normalised) < 500:
        # Too little text to identify anything. Better to assess twice than to
        # merge two unrelated manuscripts on the strength of a title page.
        return ""
    return hashlib.sha256(normalised.encode("utf-8")).hexdigest()


def update_structural_analyzer(raw_text, evidence_report, target_quality=None,
                               independent_sources=0, eval_hash="", title=""):
    """Learn from this assessment: nudge the signal weighting toward the panel.

    Called once per assessed manuscript. The panel's verdict is the target and
    SciLM (siM)'s own composite is the prediction; the gap between them is the
    learning signal. Gated on genuine corroboration inside
    scilem_learning.observe — an uncorroborated verdict teaches imitation of
    one model rather than assessment of research, so it is refused there.
    """
    signals = measure_structural_signals(raw_text)
    if target_quality is None:
        # No panel verdict is the strongest case for tutoring, not a reason to
        # skip it: there is nothing else to learn from at all.
        try:
            if sim_engine_tutor_phase_active():
                t = sim_engine_tutor_from_llm(signals, title or "", (raw_text or "")[:4000])
                if t.get("tutored"):
                    return ("No panel rating was available. SciLM (siM) recorded a tutoring "
                            "observation instead while it is still below its consensus threshold.")
        except Exception as e:                                   # noqa: BLE001
            logging.warning("SciLM (siM) tutoring step failed: %s", e)
        return "No panel rating was available, so nothing was learned from this assessment."
    try:
        # The panel rates 0-100; the structural model works in 0-1.
        target = max(0.0, min(1.0, float(target_quality) / 100.0))
        report = observe(
            signals, target, source="consensus",
            independent_sources=independent_sources, eval_hash=eval_hash,
        )
    except Exception as e:
        logging.warning("SciLM (siM) learning step failed: %s", e)
        return "SciLM (siM) could not update its calibration from this assessment."

    # Bootstrap path. A new deployment has almost no corroborated consensus, so
    # the branch above refuses nearly every early assessment and SciLM sits at
    # its default weighting indefinitely. During the tutoring phase only, a
    # model is asked the same question the four signals proxy for — how
    # completely is this manuscript reported — and its answer is learned at
    # reduced weight, from a separately-counted source.
    #
    # The tutor never suppresses the consensus step; it runs alongside it. And
    # tutored observations do not count toward the threshold that ends
    # tutoring, so the phase cannot extend itself by talking to itself.
    tutor_note = ""
    try:
        if sim_engine_tutor_phase_active():
            t = sim_engine_tutor_from_llm(signals, title or "", (raw_text or "")[:4000])
            if t.get("tutored"):
                tutor_note = (" A tutoring observation was also recorded while SciLM is still "
                              "below its consensus threshold.")
    except Exception as e:                                       # noqa: BLE001
        logging.warning("SciLM (siM) tutoring step failed: %s", e)

    if not report.get("learned"):
        return (f"SciLM (siM) did not learn from this assessment: "
                f"{report.get('reason', 'update rejected.')}{tutor_note}")
    return (
        f"SciLM (siM) calibration updated from panel consensus: predicted "
        f"{report['predicted'] * 100:.1f}, panel {report['target'] * 100:.1f} "
        f"(error {abs(report['error']) * 100:.1f} points). "
        f"{report['observations']} observation(s) learned to date.{tutor_note}"
    )


def clear_structural_analyzer_state():
    """Reset the learned weighting to its authored defaults."""
    stale = os.path.join(BASE_DIR, "scilem_weights.pt")
    removed_note = ""
    if os.path.exists(stale):
        try:
            os.remove(stale)
            removed_note = " Removed a stale weights file from a previous implementation."
        except OSError as e:
            removed_note = f" Could not remove the stale weights file: {e}"
    try:
        reset()
    except Exception as e:
        return f"Could not reset SciLM (siM)'s learned state: {e}"
    return ("SciLM (siM) reset to its authored default weighting; all learned calibration and "
            "observation history has been discarded." + removed_note)

# The two torch-dependent classes are defined inside factories so that
# subclassing nn.Module / Dataset — which requires torch to be imported —
# happens only when a forecast actually asks for the neural path.
@lru_cache(maxsize=1)
def _build_torch_classes():
    t = load_torch()
    if not t:
        return None
    nn = t["nn"]
    torch = t["torch"]

    class PiBlockchainDataset(t["Dataset"]):
        def __init__(self, data_matrix, lookback):
            self.data = data_matrix
            self.lookback = lookback

        def __len__(self):
            return len(self.data) - self.lookback

        def __getitem__(self, idx):
            x = self.data[idx: idx + self.lookback]
            y = self.data[idx + self.lookback]
            return torch.tensor(x, dtype=torch.float32), torch.tensor(y, dtype=torch.float32)

    class PiBrainLSTM(nn.Module):
        def __init__(self, input_size=8, hidden_layer_size=32, output_size=8):
            super().__init__()
            self.lstm = nn.LSTM(input_size, hidden_layer_size, batch_first=True)
            self.linear = nn.Sequential(
                nn.Linear(hidden_layer_size, 16),
                nn.ReLU(),
                nn.Linear(16, output_size),
            )

        def forward(self, x):
            lstm_out, _ = self.lstm(x)
            predictions = self.linear(lstm_out[:, -1, :])
            return torch.softmax(predictions, dim=-1) * 8.0

    return {"dataset": PiBlockchainDataset, "model": PiBrainLSTM}


def PidyneBlockchainDataset(data_matrix, lookback):
    """Factory kept at the original call signature so forecast.py is unchanged."""
    classes = _build_torch_classes()
    if not classes:
        raise RuntimeError("PyTorch is not available on this deployment.")
    return classes["dataset"](data_matrix, lookback)


def PidyneLSTM(*args, **kwargs):
    classes = _build_torch_classes()
    if not classes:
        raise RuntimeError("PyTorch is not available on this deployment.")
    return classes["model"](*args, **kwargs)

def _truncate_author_list(authors: str, limit: int = 80) -> str:
    """Shorten an author list on a NAME boundary.

    A hard slice cut mid-name and left a dangling separator — the leaderboard
    showed "... Russ Bates, Augustin Zidek," which reads as a data error rather
    than an abbreviation, and gives no signal that more authors exist. Cutting
    at the last complete name and marking the remainder with "et al." says
    exactly what happened.
    """
    text = (authors or "").strip()
    if len(text) <= limit:
        return text
    names = [n.strip() for n in text.split(",") if n.strip()]
    kept, used = [], 0
    for name in names:
        # +2 for the ", " separator; reserve 8 for the " et al." suffix.
        cost = len(name) + (2 if kept else 0)
        if used + cost > limit - 8:
            break
        kept.append(name)
        used += cost
    if not kept:
        return text[:limit - 1].rstrip(" ,;") + "\u2026"
    return ", ".join(kept) + (" et al." if len(kept) < len(names) else "")


def request_model_assessment(provider_name, model_name, api_key, base_url, prompt):
    """Call one model and parse its JSON verdict."""
    if not api_key or not str(api_key).strip():
        return provider_name, {
            "title": "N/A", "authors": "N/A",
            "opinion": "This model is not configured on this deployment.",
            "references": [], "api_failed": True, "failure_category": "not_configured",
        }

    is_openrouter = "openrouter" in base_url.lower()
    try:
        headers = {}
        extra_body = {}
        if is_openrouter:
            # FIX: Filter out None values to prevent httpx TypeErrors
            if OPENROUTER_SITE_URL:
                headers["HTTP-Referer"] = str(OPENROUTER_SITE_URL)
            if OPENROUTER_SITE_NAME:
                headers["X-Title"] = str(OPENROUTER_SITE_NAME)
                headers["X-OpenRouter-Title"] = str(OPENROUTER_SITE_NAME)
            
            # FIX: Only send data_collection if it matches the strict string enum
            provider_prefs = {
                "allow_fallbacks": True,
                "require_parameters": False,
            }
            if OPENROUTER_DATA_COLLECTION in ("allow", "deny"):
                provider_prefs["data_collection"] = OPENROUTER_DATA_COLLECTION
                
            extra_body = {"provider": provider_prefs}

        # 45s with max_retries=1 meant a single dead endpoint cost up to 90
        # seconds to rule out — multiplied by every route in every juror's
        # chain, which is where "the assessment takes forever" came from. A
        # model that has not started responding in 20s is not going to save the
        # run, and the chain has several more routes to try; retrying the same
        # dead endpoint is the least valuable way to spend the budget.
        client = OpenAI(api_key=api_key.strip(), base_url=base_url,
                        default_headers=headers or None,
                        timeout=PROVIDER_TIMEOUT_SECONDS, max_retries=0)

        request_args = {
            "model": model_name,
            "messages": [{"role": "user", "content": prompt}],
            "temperature": 0.1,
        }
        if extra_body:
            request_args["extra_body"] = extra_body

        try:
            response = client.chat.completions.create(
                response_format={"type": "json_object"}, **request_args)
        except Exception as e:
            # Retry without structured-output mode on anything that plausibly
            # relates to it. The previous pattern was too narrow: OpenRouter
            # reports this refusal in several wordings ("no endpoints found
            # that support...", "unsupported parameter", "invalid_request"),
            # none of which matched, so the fallback never fired and the juror
            # was dropped over a parameter it did not need.
            if not re.search(
                r"response_format|json_object|not support|unsupported|no endpoints|"
                r"invalid[_ ]request|structured output|schema",
                str(e), re.IGNORECASE,
            ):
                raise
            logging.info("Retrying %s without response_format: %s", model_name, str(e)[:160])
            logging.info("%s/%s rejected response_format; retrying without it.",
                         provider_name, model_name)
            response = client.chat.completions.create(**request_args)

        content = (response.choices[0].message.content or "").strip()
        data = parse_model_json(content)
        if data is None:
            raise ValueError("model returned no parseable JSON object")
        data["api_failed"] = False
        return provider_name, data

    except Exception as e:
        raw = str(e)
        classified = classify_provider_error(raw)
        logging.warning("Provider call failed for %s/%s [%s]: %s",
                        provider_name, model_name, classified["category"], raw[:300])
        return provider_name, {
            "title": "N/A", "authors": "N/A",
            "opinion": classified["public"],
            "references": [], "api_failed": True,
            "failure_category": classified["category"], "_raw_error": raw,
        }

def parse_model_json(content: str):
    if not content:
        return None

    candidates = [content]
    fenced = re.search(r"```(?:json)?\s*(.+?)```", content, re.DOTALL | re.IGNORECASE)
    if fenced:
        candidates.insert(0, fenced.group(1).strip())
    first, last = content.find("{"), content.rfind("}")
    if first != -1 and last > first:
        candidates.append(content[first:last + 1])

    for candidate in candidates:
        text = candidate.strip()
        for attempt in (text, re.sub(r",\s*([}\]])", r"\1", text)):
            try:
                parsed = json.loads(attempt)
                if isinstance(parsed, dict):
                    return parsed
            except (json.JSONDecodeError, ValueError):
                continue
    return None

# Section headings, in the order a manuscript conventionally uses them.
# Matched case-insensitively at a line start, optionally numbered ("3. Methods",
# "IV. RESULTS"), which is how they actually appear in extracted PDF text.
_EXCERPT_SECTIONS = {
    "abstract": [r"abstract", r"summary"],
    "methods": [r"methods?", r"materials and methods", r"methodology",
                r"experimental (?:section|procedures?|setup)", r"study design"],
    "results": [r"results?", r"findings", r"results and discussion"],
    "discussion": [r"discussion", r"limitations?", r"conclusions?", r"concluding remarks"],
    "references": [r"references", r"bibliography", r"works cited", r"literature cited"],
}

# Character budget per section. Methods and results get the most because that
# is where the criteria the panel is asked about actually live — a reviewer
# cannot judge methodological rigour from a title page.
_SECTION_BUDGET = {
    "front": 2000, "abstract": 2000, "methods": 6000,
    "results": 5000, "discussion": 3000, "references": 2500,
}


def _find_sections(paper_text: str) -> dict:
    """Byte offsets of each recognised section heading."""
    found = {}
    for name, patterns in _EXCERPT_SECTIONS.items():
        for pat in patterns:
            m = re.search(
                rf"^\s*(?:\d+[.)]?\s*|[IVXLC]+[.)]\s*)?{pat}\s*:?\s*$",
                paper_text, re.IGNORECASE | re.MULTILINE)
            if m:
                # Keep the earliest match for a section, except references,
                # where the LAST occurrence is the real bibliography (earlier
                # ones are in-text mentions of the word).
                if name == "references":
                    for m2 in re.finditer(
                            rf"^\s*(?:\d+[.)]?\s*)?{pat}\s*:?\s*$",
                            paper_text, re.IGNORECASE | re.MULTILINE):
                        m = m2
                if name not in found or m.start() < found[name]:
                    found[name] = m.start()
                break
    return found


def build_assessment_excerpt(paper_text: str) -> str:
    """Assemble a section-aware excerpt for the model panel.

    This replaces sending the first 3,000 characters plus the reference list.
    That selection meant the panel never saw the methods, the results, or the
    discussion — it was being asked to judge methodological rigour and
    empirical density from a title page and a bibliography, and then its
    verdict was weighted into criteria those sections define. The models were
    not performing badly; they were being shown the wrong part of the paper.

    Sections are located by heading and sampled within a per-section budget,
    so a long methods section is represented rather than truncated away by a
    front-loaded character cap. When no headings can be found — a scanned PDF,
    an unconventional layout — this degrades to a head-and-tail sample, which
    is no worse than the previous behaviour.
    """
    if not paper_text:
        return ""

    marks = _find_sections(paper_text)
    ordered = sorted(marks.items(), key=lambda kv: kv[1])

    parts = [("FRONT MATTER", paper_text[:_SECTION_BUDGET["front"]])]

    if not ordered:
        # No recognisable structure: head and tail, and say so, so the panel
        # can report that a criterion was not judgeable rather than guessing.
        parts.append(("BODY (no section headings detected; sampled)",
                      paper_text[_SECTION_BUDGET["front"]:_SECTION_BUDGET["front"] + 8000]))
        parts.append(("END OF DOCUMENT", paper_text[-4000:]))
    else:
        bounds = [start for _, start in ordered] + [len(paper_text)]
        for i, (name, start) in enumerate(ordered):
            budget = _SECTION_BUDGET.get(name, 2500)
            end = min(bounds[i + 1], start + budget)
            body = paper_text[start:end].strip()
            # Keep any section that has content beyond its own heading line.
            # A flat character minimum also discarded genuinely short sections —
            # a five-entry reference list is 34 characters and was being thrown
            # away, taking the panel's only view of the bibliography with it.
            content = "\n".join(body.split("\n")[1:]).strip()
            if content:
                parts.append((name.upper(), body))
        if "references" not in marks:
            parts.append(("END OF DOCUMENT (no reference section found)", paper_text[-3000:]))

    return "\n\n".join(f"--- {label} ---\n{body}" for label, body in parts if body.strip())


def build_assessment_prompt(paper_text, canary=""):
    excerpt = build_assessment_excerpt(paper_text)

    guard = build_security_directive(canary) if canary else ""

    return guard + f"""You are one of several independent expert reviewers assessing a manuscript.
Other reviewers are assessing it separately; your judgement will be compared against theirs, so
report what you actually observe rather than what you expect a reviewer to say.

Respond with JSON only. No prose outside the JSON object.

EXTRACTION RULES — accuracy here matters more than completeness:
- "title": the manuscript's own title. NOT the journal name, a running header, a DOI line, a
  copyright notice, or a preprint banner. If you cannot identify it confidently, return "".
- "authors": the human author names only, comma-separated, in order. Exclude affiliations,
  departments, universities, email addresses, superscript markers and corresponding-author notes.
  If none are identifiable, return "".

ASSESSMENT RULES:
- Judge only what the text actually contains. Do not credit work that is not evidenced.
- Be specific: cite what the manuscript says, not general praise or criticism.
- If a criterion cannot be judged from the excerpts provided, say so for that criterion.

Required JSON keys:
1. "title": string
2. "authors": string
3. "opinion": 120-250 words of substantive assessment. State the central claim, then the strongest
   and weakest aspects, referencing concrete evidence from the text.
4. "criteria": object with keys C1..C8. Each value is an object:
   {{"score": <0-100 integer>, "evidence": "<one specific sentence citing the manuscript>"}}
   C1 Semantic Originality, C2 Methodological Rigor, C3 Interdisciplinary Synergy,
   C4 Societal Impact, C5 Open Science, C6 Literature Integration, C7 Empirical Density,
   C8 Future Actionability.
5. "key_claims": array of up to 3 short strings — the manuscript's main claims as stated.
6. "concerns": array of up to 3 short strings — specific, actionable methodological concerns.
7. "references": array of up to 10 objects {{"citation": "[1]", "authors": "...", "year": "2024"}}

The manuscript is provided below as labelled excerpts. Each section is truncated to a budget, so
absence of detail may reflect truncation rather than the manuscript omitting it — where that is
possible, say the criterion could not be judged rather than scoring it low.

{excerpt}
"""

def assess_with_route_chain(juror: str, paper_text: str, canary: str = ""):
    prompt = build_assessment_prompt(paper_text, canary)
    routes = build_routes(juror)
    if not routes:
        return juror, {
            "title": "N/A", "authors": "N/A",
            "opinion": "This model is not configured on this deployment.",
            "references": [], "api_failed": True,
            "failure_category": "not_configured",
        }

    attempts = []
    classified = None
    dead_providers = set()        # a bad key or empty account: that provider's other routes are skipped
    for route in routes:
        if route["provider"] in dead_providers:
            continue
        # Cheapest check first: a provider the run has already found
        # unreachable costs microseconds to skip and a full connection timeout
        # to rediscover.
        down, left = is_provider_unreachable(route["provider"])
        if down:
            attempts.append({
                "model": route["model"], "provider": route["provider"],
                "category": "provider_down", "seconds_remaining": round(left, 1),
            })
            continue

        cooling, remaining = is_route_cooling(route["model"], route["provider"])
        if cooling:
            attempts.append({
                "model": route["model"], "provider": route["provider"],
                "category": "cooling", "seconds_remaining": round(remaining, 1),
            })
            continue

        provider, data = request_model_assessment(
            juror, route["model"], route["key"], route["base"], prompt)
        if not data.get("api_failed"):
            record_success(route["model"], route["provider"])
            data["route"] = {"model": route["model"], "provider": route["provider"]}
            data["route_attempts"] = attempts
            return juror, data

        raw = data.get("_raw_error") or data.get("opinion", "")
        classified = classify_provider_error(raw)
        attempts.append({
            "model": route["model"], "provider": route["provider"],
            "category": classified["category"],
        })

        if classified["category"] == "rate_limit":
            record_rate_limit(route["model"], route["provider"], parse_retry_after(raw))
        elif classified["category"] in ("credit", "auth"):
            record_rate_limit(route["model"], route["provider"], 600)
        elif classified["category"] == "network":
            # Not this model's problem — the host could not reach the provider
            # at all, so every other route to it will fail the same way.
            record_provider_unreachable(route["provider"])

        logging.warning("Juror %s route %s (%s) failed [%s]: %s",
                        juror, route["model"], route["provider"],
                        classified["category"], classified["internal"][:200])
        if classified["category"] in PROVIDER_ENDING:
            dead_providers.add(route["provider"])
        if ends_chain(classified):
            break

    if classified is None:
        cooling_only = attempts and all(a["category"] == "cooling" for a in attempts)
        classified = {
            "public": ("Every route for this model is temporarily rate-limited and was skipped."
                       if cooling_only else "No route was reachable."),
            "category": "cooling" if cooling_only else "unknown",
        }
    last = classified
    return juror, {
        "title": "N/A", "authors": "N/A",
        "opinion": last["public"],
        "references": [], "api_failed": True,
        "failure_category": last["category"],
        "route_attempts": attempts,
    }


def assess_with_llama(paper_text, canary=""):
    return assess_with_route_chain("llama", paper_text, canary)

def assess_with_mistral(paper_text, canary=""):
    return assess_with_route_chain("mistral", paper_text, canary)

def assess_with_qwen(paper_text, canary=""):
    return assess_with_route_chain("qwen", paper_text, canary)

def assess_with_gemini(paper_text, canary=""):
    return assess_with_route_chain("gemini", paper_text, canary)

def assess_with_deepseek(paper_text, canary=""):
    return assess_with_route_chain("deepseek", paper_text, canary)

def collect_independent_model_assessments(paper_text, canary=""):
    """Ask every configured juror, under a WALL-CLOCK BUDGET.

    Without the budget this call has no bound. Each route allows 45s with one
    retry, `build_routes` can return several routes per juror, and six jurors
    run three at a time — so on a host that cannot reach the providers at all,
    the arithmetic reaches ten minutes or more. The stream emits
    "Analyzing X..." immediately before this and nothing until it returns, so
    the entire wait is a single frozen line with no error and no way to tell a
    slow run from a hung one. That is the "assessment is stuck" report.

    The budget converts an unbounded wait into a bounded one. Jurors that have
    not answered by the deadline are recorded as failures with a category of
    their own, and the assessment proceeds on whoever did answer — which is
    exactly what already happens when a provider is down, including the
    "no external juror was reachable" warning on the result.
    """
    results = {}
    llm_funcs = {
        "llama": assess_with_llama,
        "mistral": assess_with_mistral,
        "qwen": assess_with_qwen,
        "gemini": assess_with_gemini,
        "deepseek": assess_with_deepseek,
        "scilem": assess_with_structural_analyzer
    }

    # NOT a `with` block. ThreadPoolExecutor.__exit__ calls shutdown(wait=True),
    # which would sit and wait for exactly the stragglers the budget exists to
    # abandon — the timeout would be measured and then ignored.
    executor = concurrent.futures.ThreadPoolExecutor(max_workers=3)
    try:
        futures = {executor.submit(func, paper_text, canary): name
                   for name, func in llm_funcs.items()}
        deadline = time.time() + max(10.0, float(PANEL_BUDGET_SECONDS))
        try:
            for future in concurrent.futures.as_completed(
                    futures, timeout=max(1.0, deadline - time.time())):
                try:
                    provider, data = future.result()
                    results[provider] = data
                except Exception as e:                           # noqa: BLE001
                    name = futures.get(future, "unknown")
                    logging.warning("Juror %s raised: %s", name, e)
                    results[name] = {
                        "title": "N/A", "authors": "N/A",
                        "opinion": f"This juror failed: {type(e).__name__}.",
                        "references": [], "api_failed": True,
                        "failure_category": "exception",
                    }
        except concurrent.futures.TimeoutError:
            for future, name in futures.items():
                if name in results:
                    continue
                future.cancel()
                results[name] = {
                    "title": "N/A", "authors": "N/A",
                    "opinion": (f"This juror did not answer within the "
                                f"{int(PANEL_BUDGET_SECONDS)}s panel budget and was "
                                f"abandoned so the assessment could finish."),
                    "references": [], "api_failed": True,
                    "failure_category": "budget_exhausted",
                }
            logging.warning("Panel budget of %ss exhausted; %d of %d jurors answered.",
                            PANEL_BUDGET_SECONDS, len(results) - 
                            sum(1 for v in results.values()
                                if v.get("failure_category") == "budget_exhausted"),
                            len(llm_funcs))
    finally:
        # Threads already in a blocking socket read cannot be killed, but they
        # are daemon-like from our point of view: nothing waits on them, and
        # their results are discarded when they eventually land.
        executor.shutdown(wait=False, cancel_futures=True)
    return results

def merge_assessments_into_report(consensus_results):
    successful_llms = [
        k for k, v in consensus_results.items()
        if not k.startswith("_") and isinstance(v, dict) and not v.get("api_failed", False)
    ]
    if not successful_llms:
        return "Synthesized Evidence Report (Unified Consensus)\n\nExternal APIs offline. Local SciLM (siM) neural analysis active."
    
    report_md = "Synthesized Evidence Report (Unified Consensus)\n\n"
    for provider in successful_llms:
        data = consensus_results[provider]
        report_md += f"### {provider.upper()} Assessment\n"
        report_md += f"- **Title Extracted:** {data.get('title', 'N/A')}\n"
        report_md += f"- **Authors:** {data.get('authors', 'N/A')}\n"
        report_md += f"- **Criteria Assessment:** {data.get('opinion', 'N/A')}\n\n"
    return report_md

MODEL_REGISTRY = {
    "llama": {"label": "Llama 3.3 70B", "role": "Panel Juror", "kind": "external"},
    "mistral": {"label": "Mistral Large", "role": "Panel Juror", "kind": "external"},
    "qwen": {"label": "Qwen 2.5 72B", "role": "Panel Juror", "kind": "external"},
    "gemini": {"label": "Gemini Flash", "role": "Panel Juror", "kind": "external"},
    "deepseek": {"label": "DeepSeek (independent lineage)", "role": "Panel Juror", "kind": "external"},
    "scilem": {"label": "SciLM (siM) Local Neural Engine", "role": "Deterministic Structural Analyst", "kind": "local"},
}

def measure_title_agreement(consensus_results) -> float:
    titles = [
        str(v.get("title", "")).strip().lower()
        for k, v in consensus_results.items()
        if k in MODEL_REGISTRY and not v.get("api_failed", False)
        and v.get("title") and "n/a" not in str(v.get("title", "")).lower()
    ]
    if len(titles) < 2:
        return 0.0
    ratios = []
    for i in range(len(titles)):
        for j in range(i + 1, len(titles)):
            ratios.append(difflib.SequenceMatcher(None, titles[i], titles[j]).ratio())
    return sum(ratios) / len(ratios) if ratios else 0.0

def _panel_median_rating(consensus_results) -> float:
    """The external panel's own verdict, for when no judge model was reachable.

    Median rather than mean: with three to five jurors, one model returning a
    wild number should not drag the score, and the median is the standard
    robust summary for exactly that. Only jurors marked `external` in
    MODEL_REGISTRY are counted — SciLM is ours, and letting it into this
    average would reintroduce, by a quieter route, the self-adjudication the
    judge filter exists to prevent.

    Falls back to SciLM only when no external juror answered at all. At that
    point there is no panel to merge, the assessment openly rests on the local
    engine, and the evidence report says so.
    """
    ratings = []
    for key, meta in MODEL_REGISTRY.items():
        if meta.get("kind") != "external":
            continue
        entry = consensus_results.get(key) or {}
        if entry.get("api_failed", False):
            continue
        for field in ("ai_rating", "rating", "score", "overall_score"):
            if entry.get(field) is None:
                continue
            try:
                value = float(entry[field])
            except (TypeError, ValueError):
                continue
            if 0.0 <= value <= 100.0:
                ratings.append(value)
                break

    if ratings:
        ratings.sort()
        mid = len(ratings) // 2
        return round(ratings[mid] if len(ratings) % 2
                     else (ratings[mid - 1] + ratings[mid]) / 2.0, 2)

    logging.warning(
        "No external juror returned a usable rating; falling back to the local SciLM (siM) "
        "score. The assessment rests on the local engine alone and is reported as such.")
    try:
        return float((consensus_results.get("scilem") or {}).get("scilem_score", 75.0))
    except (TypeError, ValueError):
        return 75.0


def grade_adjudication_quality(consensus_results) -> dict:
    participating, failed = [], []
    for key, meta in MODEL_REGISTRY.items():
        entry = consensus_results.get(key)
        if entry is None:
            continue
        record = {
            "key": key,
            "label": meta["label"],
            "role": meta["role"],
            "kind": meta["kind"],
            "status": "failed" if entry.get("api_failed", False) else "active",
            "detail": str(entry.get("opinion", ""))[:400],
            "route": entry.get("route"),
        }
        (failed if entry.get("api_failed", False) else participating).append(record)

    external_active = [m for m in participating if m["kind"] == "external"]
    n_external = len(external_active)
    agreement = measure_title_agreement(consensus_results)

    # Corroboration is a claim about INDEPENDENCE, not about headcount. Every
    # juror chain now ends in a shared Groq Llama fallback, so a deployment
    # with only that key configured can have five jurors all answer from the
    # same model on the same provider. Counting those as five independent
    # opinions would be the single most misleading thing this function could
    # do — it would report "Strong" corroboration for what is one model voting
    # five times, and correlated agreement is not evidence.
    #
    # The tier is therefore driven by the number of DISTINCT routes actually
    # used. Jurors that predate route recording, or that somehow reported no
    # route, fall back to the headcount rather than being silently dropped.
    routed = [m for m in external_active if isinstance(m.get("route"), dict)]
    distinct_routes = {(m["route"].get("provider"), m["route"].get("model")) for m in routed}
    n_independent = len(distinct_routes) + (len(external_active) - len(routed))
    n_independent = max(1, min(n_independent, n_external)) if n_external else 0
    collapsed = n_external - n_independent

    if n_independent >= 3:
        tier, confidence = "Strong", 0.90 + min(0.08, 0.02 * (n_external - 3))
        rationale = (
            f"{n_external} independent external LLMs plus the local SciLM (siM) engine each assessed this "
            f"manuscript separately, and the PiDN engine adjudicated their combined evidence. "
            f"The jurors come from different providers and model families, so their errors are "
            f"partly independent and agreement carries real information. Note the limit of this: "
            f"these models share overlapping training corpora and architectures, so agreement "
            f"rules out idiosyncratic error but not systematic error common to all of them. "
            f"Corroboration for this assessment is STRONG."
        )
    elif n_independent == 2:
        tier, confidence = "Strong", 0.82
        rationale = (
            "Two external LLMs cross-checked this manuscript alongside the local structural "
            "analyser. Cross-provider corroboration was achieved, though a third juror from a "
            "different model lineage would strengthen it — jurors trained on similar corpora can "
            "agree on a shared error."
        )
    elif n_independent == 1:
        tier, confidence = "Partial", 0.65
        rationale = (
            "Only one external LLM was reachable for this assessment. The verdict is usable but was "
            "not corroborated across independent providers, so single-model bias cannot be ruled out. "
            "Corroboration is PARTIAL."
        )
    else:
        tier, confidence = "Single-source", 0.40
        rationale = (
            "No external LLM was reachable. The verdict rests on the local SciLM (siM) neural engine and "
            "deterministic MDAR/RRID/reproducibility heuristics alone. These are reproducible and "
            "unbiased, but they cannot perform qualitative reasoning about novelty or argumentation. "
            "Corroboration is SINGLE-SOURCE — treat the interpretive criteria as indicative only."
        )

    # Say plainly when jurors collapsed onto one model. A reader comparing two
    # assessments needs to know that one of them is four labels over one model.
    if collapsed > 0:
        rationale += (
            f" {collapsed + 1} of the {n_external} external jurors were served by the same "
            f"model on the same provider after their own routes were unavailable, so they are "
            f"counted as {n_independent} independent {'source' if n_independent == 1 else 'sources'}, "
            f"not {n_external}. Their agreement with each other carries no corroborative weight."
        )

    if n_independent >= 2:
        if agreement >= 0.75:
            rationale += f" Inter-model agreement on document identification was strong ({agreement * 100:.0f}%)."
        elif agreement > 0:
            rationale += (
                f" Note: inter-model agreement on document identification was only {agreement * 100:.0f}%, "
                f"indicating the jurors diverged on how to read the manuscript's front matter."
            )
            if agreement < 0.4:
                tier, confidence = "Partial", min(confidence, 0.60)

    return {
        "tier": tier,
        "confidence": round(confidence, 2),
        "rationale": rationale,
        "participating_models": participating,
        "failed_models": failed,
        "external_juror_count": n_external,
        "independent_source_count": n_independent,
        "distinct_routes": sorted(f"{p}:{m}" for p, m in distinct_routes if p or m),
        "total_juror_count": len(participating),
        "inter_model_agreement": round(agreement, 3),
        "multi_llm": n_independent >= 2,
    }

def summarize_panel_criteria(consensus_results) -> str:
    labels = {
        "C1": "Semantic Originality", "C2": "Methodological Rigor",
        "C3": "Interdisciplinary Synergy", "C4": "Societal Impact",
        "C5": "Open Science", "C6": "Literature Integration",
        "C7": "Empirical Density", "C8": "Future Actionability",
    }
    collected = {key: [] for key in labels}
    evidence = {key: [] for key in labels}
    for provider, data in (consensus_results or {}).items():
        if provider.startswith("_") or not isinstance(data, dict) or data.get("api_failed"):
            continue
        block = data.get("criteria")
        if not isinstance(block, dict):
            continue
        for key in labels:
            entry = block.get(key)
            if isinstance(entry, dict):
                try:
                    collected[key].append(float(entry.get("score")))
                except (TypeError, ValueError):
                    pass
                note = str(entry.get("evidence", "")).strip()
                if note:
                    evidence[key].append(f"{provider.upper()}: {note}")
            else:
                try:
                    collected[key].append(float(entry))
                except (TypeError, ValueError):
                    pass

    if not any(collected.values()):
        return ""

    rows = ["\n#### Panel Criteria Assessment\n",
            "| Criterion | Jurors | Mean | Range | Agreement |",
            "| --- | --- | --- | --- | --- |"]
    for key, label in labels.items():
        values = collected[key]
        if not values:
            rows.append(f"| {key} {label} | 0 | — | — | not assessed |")
            continue
        mean = sum(values) / len(values)
        spread = max(values) - min(values)
        agreement = ("strong" if spread <= 10 else
                     "moderate" if spread <= 25 else "weak — jurors diverged")
        rows.append(
            f"| {key} {label} | {len(values)} | {mean:.0f} | "
            f"{min(values):.0f}–{max(values):.0f} | {agreement} |")

    detail = []
    for key, notes in evidence.items():
        if notes:
            detail.append(f"- **{key} {labels[key]}** — {notes[0][:240]}")
    if detail:
        rows.append("\n**Supporting evidence cited by jurors**\n")
        rows.extend(detail[:8])
    return "\n".join(rows) + "\n"

def collect_panel_lists(consensus_results, field: str, heading: str) -> str:
    seen, items = set(), []
    for provider, data in (consensus_results or {}).items():
        if provider.startswith("_") or not isinstance(data, dict) or data.get("api_failed"):
            continue
        for entry in (data.get(field) or [])[:3]:
            text = str(entry).strip()
            key = text.lower()[:60]
            if text and key not in seen:
                seen.add(key)
                items.append(f"- {text[:220]}")
    if not items:
        return ""
    return f"\n#### {heading}\n\n" + "\n".join(items[:8]) + "\n"

def adjudicate_panel_verdict(consensus_results, text=None):
    prompt = "You are the PiDN Assessment Engine. Review these independent model assessments:\n\n"
    active_count = 0
    for provider, data in consensus_results.items():
        if provider.startswith("_"):
            continue
        if not data.get("api_failed", False):
            active_count += 1
            prompt += f"### {provider.upper()} Assessment:\n"
            prompt += f"- Extracted Title: {data.get('title', 'N/A')}\n"
            prompt += f"- Extracted Authors: {data.get('authors', 'N/A')}\n"
            prompt += f"- Criteria Assessment: {data.get('opinion', 'N/A')}\n\n"

    prompt += """
Generate a comprehensive, structured Markdown Evidence Report and provide an overall AI Rating (0.0 to 100.0).
Respond strictly in JSON with keys:
1. "evidence_report": string containing the markdown report with sections for Executive Summary, 8 Criteria Audit, and Methodological Quality.
2. "ai_rating": float between 0.0 and 100.0.
"""
    # The judge now walks a provider chain exactly as the jurors do, instead of
    # making one hardcoded call and giving up. A rate limit on one provider
    # demotes the judge to the next, rather than collapsing the whole
    # adjudication step to the local deterministic fallback.
    #
    # SciLM (siM) is never the judge. When no external route answers, the
    # adjudication falls through to a deterministic merge of what the jurors
    # already said — not to ScholarPi's own engine writing the verdict on the
    # panel it sat in. The previous label claimed the local engine had judged,
    # which was both the wrong model for the job and an assertion the report
    # then carried into the ledger.
    judge_routes = [r for r in build_routes("judge") if not is_scilm_route(r)]
    model_name = "Deterministic panel merge (no external judge reached)"
    judge_platform = "None (deterministic fallback)"
    judge_attempts = []
    data = None

    if judge_routes and active_count > 0:
        judge_dead = set()
        for route in judge_routes:
            if route["provider"] in judge_dead:
                continue
            down, left = is_provider_unreachable(route["provider"])
            if down:
                judge_attempts.append({"model": route["model"], "provider": route["provider"],
                                       "category": "provider_down",
                                       "seconds_remaining": round(left, 1)})
                continue

            cooling, remaining = is_route_cooling(route["model"], route["provider"])
            if cooling:
                judge_attempts.append({"model": route["model"], "provider": route["provider"],
                                       "category": "cooling",
                                       "seconds_remaining": round(remaining, 1)})
                continue

            _, attempt = request_model_assessment(
                "pidyne", route["model"], route["key"], route["base"], prompt)

            if not attempt.get("api_failed", True):
                record_success(route["model"], route["provider"])
                data = attempt
                model_name = route["model"]
                judge_platform = route["provider"]
                break

            raw = attempt.get("_raw_error") or attempt.get("opinion", "")
            classified = classify_provider_error(raw)
            judge_attempts.append({"model": route["model"], "provider": route["provider"],
                                   "category": classified["category"]})
            if classified["category"] == "rate_limit":
                record_rate_limit(route["model"], route["provider"], parse_retry_after(raw))
            elif classified["category"] in ("credit", "auth"):
                record_rate_limit(route["model"], route["provider"], 600)
            elif classified["category"] == "network":
                record_provider_unreachable(route["provider"])
            logging.warning("Judge route %s (%s) failed [%s]: %s",
                            route["model"], route["provider"],
                            classified["category"], classified["internal"][:200])
            if classified["category"] in PROVIDER_ENDING:
                judge_dead.add(route["provider"])
            if ends_chain(classified):
                break

    judge_provider = f"{judge_platform} (Model: {model_name})"

    quality = grade_adjudication_quality(consensus_results)
    judge_succeeded = data is not None

    consensus_results["_judge_metadata"] = {
        "judge_provider": judge_provider,
        "judge_platform": judge_platform,
        "model_name": model_name,
        "judge_succeeded": judge_succeeded,
        # What the judge tried before landing here. Without this, a fallback to
        # the local engine looked identical whether one provider was rate
        # limited or none were configured at all.
        "judge_attempts": judge_attempts,
        "judge_routes_available": len(judge_routes),
        "final_judge_label": (
            f"{model_name} via {judge_platform}" if judge_succeeded
            else "No external judge reached — deterministic merge of the panel's verdicts"
        ),
        # Recorded explicitly so the guarantee is visible in the stored record
        # and not merely implied by the absence of a name.
        "scilm_excluded_as_judge": True,
        "timestamp": datetime.now().isoformat(),
        **quality,
    }

    juror_line = ", ".join(
        f"{m['label']}" for m in quality["participating_models"]
    ) or "none"

    criteria_table = summarize_panel_criteria(consensus_results)
    claims_block = collect_panel_lists(consensus_results, "key_claims", "Claims identified")
    concerns_block = collect_panel_lists(consensus_results, "concerns", "Concerns raised")
    header_prefix = (
        "### Final Verdict & Evidence Synthesis\n\n"
        f"| Field | Value |\n| --- | --- |\n"
        f"| Final Judge | `{consensus_results['_judge_metadata']['final_judge_label']}` |\n"
        f"| Jury Panel | {juror_line} |\n"
        f"| Independent External Jurors | {quality['external_juror_count']} |\n"
        f"| Corroboration | **{quality['tier']}** (confidence {quality['confidence']:.2f}) |\n"
        f"| Inter-Model Agreement | {quality['inter_model_agreement'] * 100:.0f}% |\n\n"
        f"> {quality['rationale']}\n\n"
        + criteria_table + claims_block + concerns_block +
        "\n---\n\n"
    )

    if not data:
        fallback_rep = merge_assessments_into_report(consensus_results)
        evidence_report = header_prefix + (
            "**Note:** No external judge model was reachable. This verdict is a deterministic "
            "merge of what the jurors independently reported — it was not adjudicated by "
            "SciLM (siM), which sits on the panel and is never permitted to judge it.\n\n"
        ) + fallback_rep
        # The fallback rating comes from the PANEL, not from SciLM.
        #
        # This line used to read the score straight off consensus_results
        # ["scilem"], which meant that whenever no external judge answered,
        # ScholarPi's own engine silently set the final rating on its own. That
        # is SciLM judging in substance whatever the label above said — and the
        # provider filter that keeps it out of the judge chain did nothing
        # about it, because this path never consults the chain at all.
        #
        # The median of the external jurors' ratings is used instead: it is an
        # actual adjudication of the panel (robust to one juror being far out),
        # and it is composed only of models that are independent of us. SciLM
        # is the last resort and only when literally no external juror
        # responded, in which case there is no panel to merge and the report
        # already says the assessment rests on the local engine.
        rating = _panel_median_rating(consensus_results)
    else:
        raw_rep = data.get("evidence_report", "Synthesized Evidence Report generated successfully.")
        if "Synthesized Evidence Report" in raw_rep[:50] or raw_rep.startswith("###"):
            evidence_report = header_prefix + raw_rep
        else:
            evidence_report = header_prefix + f"Synthesized Evidence Report (Unified Consensus)\n\n{raw_rep}"
        try:
            rating = float(data.get("ai_rating", 75.0))
        except Exception:
            rating = 75.0
            
    return evidence_report, rating


def measure_mdar_adherence(text: str) -> Tuple[float, int]:
    text_lower = text.lower()
    blinded = 1.0 if re.search(r'\b(blinded|double-blind|single-blind|masking)\b', text_lower) else 0.0
    randomized = 1.0 if re.search(r'\b(randomized|randomly assigned|random sequence)\b', text_lower) else 0.0
    power_calc = 1.0 if re.search(r'\b(power analysis|sample size calculation|statistical power)\b', text_lower) else 0.0
    
    rrid_matches = re.findall(r'\brrid\s*:?\s*[a-zA-Z0-9_:-]+\b', text_lower)
    rrid_count = len(set(rrid_matches)) 
    rrid_score = min(1.0, rrid_count / 3.0) 
    mdar_adherence = (blinded + randomized + power_calc + rrid_score) / 4.0
    
    return mdar_adherence, rrid_count

def measure_reproducibility_markers(text: str) -> Tuple[float, Dict]:
    text_lower = text.lower()
    signals = {
        "code_or_data_repository": bool(re.search(
            r'\b(github\.com|gitlab\.com|bitbucket\.org|zenodo\.org|osf\.io|huggingface\.co)\b', text_lower)),
        "data_availability_statement": bool(re.search(
            r'\bdata availability\b|\bdata are available\b|\bdataset(?:s)? (?:is|are) available\b|\bcode availability\b',
            text_lower)),
        "open_license": bool(re.search(
            r'\b(mit license|apache license|gpl license|creative commons|cc[- ]by)\b', text_lower)),
        "containerized_execution": bool(re.search(
            r'\b(docker|singularity|containeri[sz]ed|reproducible environment|conda environment)\b', text_lower)),
        "supplementary_materials": bool(re.search(
            r'\bsupplementary (material|data|information|table|figure)\b', text_lower)),
        "preregistration": bool(re.search(
            r'\bpre-?registered\b|\bpre-?registration\b|\bosf\.io/registrations\b', text_lower)),
    }
    hits = sum(1 for v in signals.values() if v)
    total = len(signals)
    score = 0.30 + (hits / total) * 0.70
    return min(1.0, max(0.0, score)), signals

def measure_empirical_density(text: str) -> float:
    text_lower = text.lower()
    stat_terms = len(re.findall(
        r'\b(p\s*[<>=]\s*0?\.\d+|confidence interval|standard deviation|standard error|'
        r'anova|regression|t-test|chi-square|correlation coefficient|effect size|'
        r'p-value)\b', text_lower))
    sample_size_mentions = len(re.findall(r'\bn\s*=\s*\d+', text_lower))
    numeric_results = len(re.findall(r'\b\d+(?:\.\d+)?\s*%|\b\d+(?:\.\d+)?\s*(?:ms|kg|mm|cm|km|hz|db)\b', text_lower))

    raw_signal = (stat_terms * 2) + (sample_size_mentions * 1.5) + numeric_results
    normalized = min(1.0, raw_signal / 40.0)
    return normalized

def truncate_to_token_budget(text, max_tokens):
    if len(text) <= max_tokens:
        return text
    front_matter = text[: int(max_tokens * 0.4)]
    back_matter = text[-int(max_tokens * 0.6) :]
    return front_matter + "\n...[TRUNCATED FOR TOKEN LIMITS]...\n" + back_matter

def _distinct_juror_values(consensus_results, field):
    """Candidate values for a field, one vote per DISTINCT model route.

    Deduplicating by route is the whole point. Every juror chain now ends in a
    shared Groq Llama fallback, so four jurors can be four labels over one
    model — and four identical strings from one model is not four jurors
    agreeing on a title, it is the same extraction counted four times. Counting
    it as corroboration would inflate confidence in exactly the cases where
    the panel had collapsed.
    """
    seen_routes = set()
    candidates = []
    for key, entry in (consensus_results or {}).items():
        if key.startswith("_") or not isinstance(entry, dict):
            continue
        if entry.get("api_failed"):
            continue
        route = entry.get("route") or {}
        route_id = (route.get("provider"), route.get("model")) if route else ("?", key)
        if route_id in seen_routes:
            continue

        val = entry.get(field, "")
        if field == "references":
            if not isinstance(val, list) or not val:
                continue
        else:
            val = str(val or "").strip()
            if not val or "n/a" in val.lower() or val.lower() in ("unconfigured key", "none"):
                continue

        seen_routes.add(route_id)
        candidates.append({"juror": key, "route": route_id, "value": val})
    return candidates


def _medoid(values):
    """The member most similar to all the others.

    Previously the LONGEST member of the winning cluster was chosen, on the
    assumption that longer meant more complete. For author strings that is
    precisely backwards: the longest variant is usually the one that swallowed
    an affiliation or a date, so "most verbose" selected for the most polluted
    extraction. The medoid picks the variant the jurors actually agree on.
    """
    if len(values) == 1:
        return values[0]
    best, best_score = values[0], -1.0
    for candidate in values:
        score = sum(difflib.SequenceMatcher(None, candidate.lower(), other.lower()).ratio()
                    for other in values if other is not candidate)
        if score > best_score:
            best, best_score = candidate, score
    return best


def select_consensus_value(consensus_results, field):
    """Agree a single value for a scalar field across independent jurors."""
    entries = _distinct_juror_values(consensus_results, field)
    candidates = [e["value"] for e in entries]

    if not candidates:
        return ("Untitled Manuscript" if field == "title" else "Unidentified"), 0.0
    if len(candidates) == 1:
        # One independent source is not consensus. Support is reported as a
        # fraction of the panel that could have answered, so a lone extraction
        # never claims agreement it does not have.
        return candidates[0], round(1.0 / max(1, len(consensus_results)), 4)

    clusters = []
    for val in candidates:
        placed = False
        for cluster in clusters:
            if difflib.SequenceMatcher(None, val.lower(), cluster[0].lower()).ratio() >= 0.80:
                cluster.append(val)
                placed = True
                break
        if not placed:
            clusters.append([val])

    winner = max(clusters, key=len)
    return _medoid(winner), round(len(winner) / len(candidates), 4)


def _normalise_citation(ref):
    """A comparison key for one reference.

    Jurors format citations inconsistently — numbering, punctuation, author
    order — so raw strings almost never match. Comparing on a normalised
    author+year+title signature is what makes cross-juror agreement detectable
    at all.
    """
    if isinstance(ref, dict):
        parts = [str(ref.get("authors", "")), str(ref.get("year", "")),
                 str(ref.get("title", "")), str(ref.get("citation", ""))]
    else:
        parts = [str(ref)]
    text = " ".join(p for p in parts if p and p.lower() not in ("none", "n/a"))
    text = re.sub(r"[^a-z0-9 ]+", " ", text.lower())
    return re.sub(r"\s+", " ", text).strip()


def select_consensus_references(consensus_results, min_sources=2):
    """References corroborated by more than one independent juror.

    This is the field where consensus matters most. A fabricated reference is
    the highest-cost extraction error the framework can make — it is the exact
    failure the reference audit exists to catch — and a single model
    hallucinating a plausible citation is the normal way it happens. A citation
    that two independently-routed models both report is very unlikely to be an
    invention of either.

    Uncorroborated references are not discarded silently; they are returned
    separately and flagged, because "only one juror saw this" is information
    the reader needs rather than a reason to hide the entry.
    """
    entries = _distinct_juror_values(consensus_results, "references")
    total_sources = len(entries)
    if not entries:
        return {"references": [], "corroborated": 0, "single_source": [],
                "sources": 0, "agreement": 0.0}

    buckets = {}
    for entry in entries:
        seen_here = set()
        for ref in entry["value"][:30]:
            key = _normalise_citation(ref)
            if len(key) < 8 or key in seen_here:
                continue
            seen_here.add(key)
            bucket = buckets.setdefault(key, {"ref": ref, "jurors": set()})
            bucket["jurors"].add(entry["juror"])
            # Prefer the richest structured form seen for this citation.
            if isinstance(ref, dict) and len(str(ref)) > len(str(bucket["ref"])):
                bucket["ref"] = ref

    corroborated, single = [], []
    threshold = min(min_sources, total_sources) if total_sources > 1 else 1
    for bucket in buckets.values():
        record = dict(bucket["ref"]) if isinstance(bucket["ref"], dict) else {"citation": str(bucket["ref"])}
        record["sources"] = len(bucket["jurors"])
        record["corroborated"] = len(bucket["jurors"]) >= threshold and total_sources > 1
        (corroborated if record["corroborated"] else single).append(record)

    corroborated.sort(key=lambda r: -r["sources"])
    agreement = round(len(corroborated) / max(1, len(buckets)), 4)
    return {
        "references": corroborated + single,
        "corroborated": len(corroborated),
        "single_source": single,
        "sources": total_sources,
        "agreement": agreement,
        "note": (
            f"{len(corroborated)} of {len(buckets)} distinct references were reported by at least "
            f"{threshold} independently-routed jurors."
            if total_sources > 1 else
            "Only one juror was reachable, so no reference could be cross-checked. Treat the "
            "reference list as unverified."
        ),
    }

def run_evaluation_pipeline(text, model, text_limit, file_hash="unknown", canary=""):
    text = truncate_to_token_budget(text, text_limit)
    consensus_results = collect_independent_model_assessments(text, canary)

    evidence_report, pidyne_ai_rating = adjudicate_panel_verdict(consensus_results, text)

    canary_result = detect_canary_in_panel_output(consensus_results, canary) if canary else \
        {"detected": False, "models": [], "confidence": "none"}

    for _k, _entry in consensus_results.items():
        if isinstance(_entry, dict):
            _entry.pop("_raw_error", None)

    if canary:
        evidence_report = redact_canary(evidence_report, canary)
        for key, entry in consensus_results.items():
            if key.startswith("_") or not isinstance(entry, dict):
                continue
            if isinstance(entry.get("opinion"), str):
                entry["opinion"] = redact_provider_text(redact_canary(entry["opinion"], canary))
            entry.pop("_raw_error", None)

    _quality_meta = (consensus_results.get("_judge_metadata") or {})
    update_structural_analyzer(
        text, evidence_report, pidyne_ai_rating,
        independent_sources=int(_quality_meta.get("independent_source_count") or 0),
        title=select_consensus_value(consensus_results, "title")[0] or "",
    )

    best_title, title_support = select_consensus_value(consensus_results, "title")
    best_author, author_support = select_consensus_value(consensus_results, "authors")
    # Authors pass through the same cleaner used on PDF bylines, so an
    # affiliation or date that one juror folded into its author string is
    # stripped before it reaches the ledger and the attribution key.
    best_author = _truncate_author_list(clean_author_list(best_author) or best_author, 120)
    reference_consensus = select_consensus_references(consensus_results)

    scilem_score = consensus_results.get("scilem", {}).get("scilem_score", pidyne_ai_rating)

    quality = (consensus_results.get("_judge_metadata") or {})
    agreement = float(quality.get("inter_model_agreement") or 0.0)
    jurors = int(quality.get("total_juror_count") or 0)
    confidence = round(min(0.99, (agreement * 0.5) + (min(jurors, 5) / 5.0 * 0.35)
                           + (title_support * 0.15)), 4)

    return {
        "Extracted_Title": best_title,
        "Extracted_Author": best_author,
        "Overall_Confidence": confidence,
        "_title_support": title_support,
        "_author_support": author_support,
        "_reference_consensus": reference_consensus,
        "_consensus_raw": consensus_results,
        "_evidence_report": evidence_report,
        "_pidyne_rating": pidyne_ai_rating,
        "_scilem_score": scilem_score,
        "_canary_result": canary_result,
    }

def compute_rubric_fingerprint():
    return hashlib.sha256(b"Pi-Index-Formula-State-v2.0").hexdigest()

def build_signal_vector(*, panel_rating, corroboration, mdar_adherence, rrid_count,
                        reproducibility, empirical_density, topology_detail,
                        reference_audit, text, text_complete=True):
    topo = topology_detail or {}
    return {
        "panel_rating": (panel_rating or 0.0) / 100.0,
        "corroboration": corroboration,
        "mdar_adherence": mdar_adherence,
        "rrid_density": min(1.0, (rrid_count or 0) / 5.0),
        "reproducibility": reproducibility,
        "empirical_density": empirical_density,
        "topic_diversity": topo.get("score", 0.35),
        "domain_span": 1.0 if topo.get("spans_domains") else 0.0,
        "citation_engagement": measure_citation_engagement(text, reference_audit),
        "reference_integrity": measure_citation_resolvability(reference_audit),
        "openness_licence": measure_open_licensing(text),
        "persistent_identifiers": measure_persistent_identifier_use(text),
        "text_completeness": 1.0 if text_complete else 0.0,
    }

def score_criteria_from_legacy_args(**kwargs):
    signals = kwargs.get("signals")
    if signals is None:
        signals = build_signal_vector(
            panel_rating=kwargs.get("ai_rating", 75.0),
            corroboration=kwargs.get("corroboration", 0.5),
            mdar_adherence=kwargs.get("sciscore_adherence", 0.8),
            rrid_count=kwargs.get("rrid_count", 0),
            reproducibility=kwargs.get("reproducibility_score", 0.0),
            empirical_density=kwargs.get("empirical_density") or 0.0,
            topology_detail=kwargs.get("topology_detail")
            or {"score": kwargs.get("topological_entropy", 0.5)},
            reference_audit=kwargs.get("reference_audit"),
            text=kwargs.get("text", ""),
        )
    return apply_scoring_rubric(signals)

brain_CRITERIA_ORDER = [
    "C1_Semantic_Originality",
    "C2_Methodological_Rigor_SciScore",
    "C3_Interdisciplinary_Entropy",
    "C4_Societal_Impact",
    "C5_Open_Science_Repro",
    "C6_Literature_Integration",
    "C7_Empirical_Density",
    "C8_Future_Actionability_FAIR",
]

WEIGHT_INERTIA = 0.86

def derive_next_epoch_weights(scores_dict, previous_weights=None, corpus_scores=None):
    raw = []
    for key in brain_CRITERIA_ORDER:
        val = scores_dict.get(key, 50.0)
        try:
            val = float(val)
        except (TypeError, ValueError):
            val = 50.0
        val = max(0.0, min(100.0, val))

        informativeness = 1.0 - (abs(val - 50.0) / 50.0)
        raw.append(0.25 + (informativeness * 0.75))

    if corpus_scores:
        try:
            variances = []
            for idx in range(len(brain_CRITERIA_ORDER)):
                column = [float(row[idx]) for row in corpus_scores
                          if row and len(row) > idx and row[idx] is not None]
                if len(column) >= 3:
                    mean = sum(column) / len(column)
                    variance = sum((v - mean) ** 2 for v in column) / len(column)
                    variances.append(variance ** 0.5)
                else:
                    variances.append(None)
            if all(v is not None for v in variances) and max(variances) > 1e-6:
                peak = max(variances)
                raw = [0.25 + (v / peak) * 0.75 for v in variances]
        except (TypeError, ValueError, IndexError):
            pass

    total = sum(raw)
    observed = [(v / total) * 8.0 for v in raw] if total > 0 else [1.0] * 8

    if previous_weights and len(previous_weights) == 8:
        prev = []
        for p in previous_weights:
            try:
                prev.append(float(p))
            except (TypeError, ValueError):
                prev.append(1.0)
        blended = [
            (WEIGHT_INERTIA * p) + ((1.0 - WEIGHT_INERTIA) * o)
            for p, o in zip(prev, observed)
        ]
    else:
        blended = observed

    w_min = 0.05
    w_max = 8.0 - (7 * w_min)
    for _ in range(12):
        blended = [max(w_min, min(w_max, w)) for w in blended]
        total = sum(blended)
        if total <= 0:
            return [1.0] * 8
        blended = [w * (8.0 / total) for w in blended]
        if all(w_min - 1e-9 <= w <= w_max + 1e-9 for w in blended):
            break
    return [round(w, 8) for w in blended]

_CREDIT_PATTERNS = {
    "Conceptualization": r"\b(conceptuali[sz]ation|study design|research question|hypothes[ei]s)\b",
    "Methodology": r"\b(methodolog|experimental design|protocol|procedure)\b",
    "Software": r"\b(github\.com|gitlab\.com|source code|implementation|we implemented|codebase)\b",
    "Validation": r"\b(validat|cross-validation|replicat|verified|robustness check)\b",
    "Formal Analysis": r"\b(statistical analys|regression|anova|significance test|formal analysis)\b",
    "Investigation": r"\b(we (conducted|performed|carried out)|experiment(s)? (were|was)|fieldwork)\b",
    "Data Curation": r"\b(dataset|data availability|data collection|curat|repositor)\b",
    "Writing": r"\b(this (paper|manuscript|article)|we (present|report|describe))\b",
    "Funding Acquisition": r"\b(funded by|grant no|financial support|acknowledge.{0,40}funding)\b",
}

def infer_credit_taxonomy_roles(text: str):
    if not text:
        return ["Unspecified"]
    lowered = text.lower()
    roles = [role for role, pattern in _CREDIT_PATTERNS.items()
             if re.search(pattern, lowered, re.IGNORECASE)]
    return roles or ["Unspecified"]

def _EMPTY_INTEGRITY():
    return {"compromised": False, "severity": "none", "techniques": [], "findings": [],
            "warnings": [], "hidden_text_detected": False, "scanned": False,
            "canary": {"detected": False, "models": [], "confidence": "none"}}

def _EMPTY_REFERENCE_AUDIT():
    return {"checked": 0, "verified": 0, "fabricated": 0, "unverified": 0, "total_found": 0,
            "fabricated_dois": [], "unverified_dois": [], "hallucination_ratio": 0.0,
            "verdict": "not_assessed", "warnings": [], "penalty_applied": False}

def _EMPTY_AUTHORSHIP():
    return {"assessed": False, "flag": "not_assessed", "confidence": "none",
            "indicators": [], "note": "", "affects_score": False}

def _EMPTY_TOPOLOGY():
    return {"score": 0.50, "basis": "unavailable", "topic_count": 0, "domains": [],
            "fields": [], "subfields": [], "spans_domains": False}

def process_single_pdf(
    file_bytes,
    filename,
    scope,
    user_id,
    book_address="None",
    email="None",
    provided_doi="None",
    force_proceed=False,
):
    active_weights = [1.0] * 8
    warnings_list = []

    if file_bytes is None or len(file_bytes) == 0:
        empty_scores = {k: 0.0 for k in [
            "C1_Semantic_Originality", "C2_Methodological_Rigor_SciScore", 
            "C3_Interdisciplinary_Entropy", "C4_Societal_Impact", 
            "C5_Open_Science_Repro", "C6_Literature_Integration", 
            "C7_Empirical_Density", "C8_Future_Actionability_FAIR"
        ]}
        warnings_list.append("Binary payload is empty or download/extraction failed.")
        return ("Download/Extraction Failed", "Independent Research Scholar", 0.0, 0.0,
                {}, [],
                ["Unclassified"], ["Unclassified"], empty_scores, "Failed", 0.0,
                "None", "None", active_weights, 0.0, 0, 0.0, False, warnings_list, {}, "", "N/A",
                _EMPTY_INTEGRITY(), _EMPTY_REFERENCE_AUDIT(), _EMPTY_AUTHORSHIP(), _EMPTY_TOPOLOGY(), {}, {})

    file_hash = hashlib.sha256(file_bytes).hexdigest()

    def _cached_record(conn, eval_hash, note):
        """Return the stored assessment tuple for `eval_hash`, or None.

        Used by both duplicate paths — same file, and same paper in a different
        file — so a resubmission is answered identically however it was
        recognised. Only a record that reached the ledger qualifies; a run that
        died before minting is not something to hand back.
        """
        row = conn.execute(
            """SELECT title, author_name, final_score, logic_score, c1, c2, c3, c4, c5, c6, c7, c8,
                      piq_minted, tx_hash, zk_proof, mdar_adherence_score, rrid_valid_count,
                      reproducibility_score, consensus_data, evidence_report, scilem_score,
                      warnings_json, integrity_report, reference_audit, authorship_signal,
                      topology_detail, classification, criteria_breakdown, fields, subfields,
                      author_metrics, emission_record
               FROM papers_assessment WHERE eval_hash = ?""",
            (eval_hash,),
        ).fetchone()
        if not row:
            return None
        tx_prev = row[13]
        if not ((isinstance(tx_prev, str) and tx_prev.startswith("0x") and len(tx_prev) == 66)
                or tx_prev == "Simulated_Ledger_Record"):
            return None

        (e_title, e_author, e_score, e_logic, e_c1, e_c2, e_c3, e_c4, e_c5, e_c6, e_c7, e_c8,
         e_piq, e_tx, e_zk, e_mdar, e_rrid, e_repro, e_consensus, e_report, e_scilem,
         e_warnings, e_integrity, e_refaudit, e_authorship, e_topology,
         e_classification, e_breakdown, e_fields, e_subfields, e_authormetrics,
         e_emission) = row

        def _load(raw, fallback):
            try:
                parsed = json.loads(raw) if raw else None
                return parsed if parsed else fallback
            except Exception:
                return fallback

        cached_warnings = _load(e_warnings, [])
        if not isinstance(cached_warnings, list):
            cached_warnings = []
        cached_warnings = list(cached_warnings) + [note]
        e_scores_dict = {
            "C1_Semantic_Originality": e_c1, "C2_Methodological_Rigor_SciScore": e_c2,
            "C3_Interdisciplinary_Entropy": e_c3, "C4_Societal_Impact": e_c4,
            "C5_Open_Science_Repro": e_c5, "C6_Literature_Integration": e_c6,
            "C7_Empirical_Density": e_c7, "C8_Future_Actionability_FAIR": e_c8,
        }
        # NOTE the eval_hash returned here is the ORIGINAL record's, not the
        # newly uploaded file's. That is the entire point of merging: reviews,
        # publication state, reads and the ledger entry all key on this hash,
        # so the resubmission has to resolve to the record that already carries
        # them rather than opening an empty parallel one.
        return (
            e_title, e_author, e_score, e_logic,
            _load(e_classification, {}), _load(e_breakdown, []),
            _load(e_fields, ["Unclassified"]), _load(e_subfields, ["Unclassified"]),
            e_scores_dict, eval_hash,
            e_piq, e_tx, e_zk, active_weights, e_mdar, e_rrid, e_repro, True,
            cached_warnings,
            _load(e_consensus, {}), e_report or "", e_scilem,
            _load(e_integrity, _EMPTY_INTEGRITY()),
            _load(e_refaudit, _EMPTY_REFERENCE_AUDIT()),
            _load(e_authorship, _EMPTY_AUTHORSHIP()),
            _load(e_topology, _EMPTY_TOPOLOGY()),
            _load(e_authormetrics, {}),
            _load(e_emission, {}),
        )

    conn = get_db_connection()
    try:
        cursor = conn.cursor()

        if not force_proceed:
            cached = _cached_record(
                conn, file_hash,
                "CACHED RECORD: This manuscript was already assessed previously; the stored, "
                "already-minted record is being returned instead of re-processing. No new "
                "processing fee was charged.")
            if cached:
                return cached

        try:
            doc = fitz.open(stream=file_bytes, filetype="pdf")
            pdf_meta_author = doc.metadata.get("author", "").strip()
            text_blocks = [page.get_text("text", sort=True) for page in doc]
            full_text = "\n".join(text_blocks)
        except Exception as e:
            warnings_list.append(f"PyMuPDF parsing note: {e}")
            full_text = ""

        # --- Same paper, different file ---------------------------------
        # The byte check above only catches a re-upload of the identical file.
        # This catches the far more common case: the same manuscript arriving
        # as a different PDF. It runs here, after extraction but before the
        # assessment panel, so a duplicate costs one text hash rather than a
        # full round of model calls, a second ledger entry and a second review
        # cycle for work that has already been through both.
        paper_fingerprint = content_fingerprint(full_text)
        if paper_fingerprint and not force_proceed:
            # real_doi(), not provided_doi. The parameter defaults to the
            # STRING "None", which is not empty, so passing it raw asked the
            # database for "another paper whose DOI is also 'None'" — and every
            # DOI-less upload in the corpus answers to that.
            twin = find_existing_paper(content_hash=paper_fingerprint,
                                       doi=real_doi(provided_doi), exclude_hash=file_hash)
            if twin:
                how = ("identical text" if twin["matched_on"] == "content_hash"
                       else "the same DOI")
                cached = _cached_record(
                    conn, twin["eval_hash"],
                    f"MERGED SUBMISSION: this file differs from one already assessed, but shares "
                    f"{how} with it, so it is the same work. The existing record was returned "
                    f"instead of creating a second one — its reviews, publication state and "
                    f"ledger entry all still apply, and no new processing fee was charged.")
                if cached:
                    # A DOI match on a record assessed before fingerprints
                    # existed: store the fingerprint now, so the next copy is
                    # recognised even if it arrives without a DOI.
                    if twin["matched_on"] == "doi":
                        set_content_hash(twin["eval_hash"], paper_fingerprint)
                    logging.info("Merged resubmission %s into existing paper %s (matched on %s).",
                                 file_hash[:12], twin["eval_hash"][:12], twin["matched_on"])
                    return cached

        mdar_score, rrid_count = measure_mdar_adherence(full_text)
        reproducibility_score, _repro_flags = measure_reproducibility_markers(full_text)
        empirical_density = measure_empirical_density(full_text)

        enrichment = run_bounded([
            ("topology", lambda: fetch_topic_diversity_for_doi(provided_doi)),
            ("references", lambda: audit_citation_integrity(full_text, budget_seconds=8.0)),
        ], budget_seconds=12.0, max_workers=2)

        topology_detail = enrichment.get("topology") or _EMPTY_TOPOLOGY()
        reference_audit = enrichment.get("references") or _EMPTY_REFERENCE_AUDIT()

        if "topology" not in enrichment:
            warnings_list.append(
                "TOPIC LOOKUP UNAVAILABLE: OpenAlex did not respond within the time budget, so "
                "interdisciplinarity fell back to a neutral prior rather than measured evidence."
            )
        if "references" not in enrichment:
            warnings_list.append(
                "REFERENCE AUDIT SKIPPED: the citation registries did not respond within the time "
                "budget. No references were counted as fabricated and no penalty was applied."
            )

        if topology_detail.get("basis") == "legacy-concepts":
            warnings_list.append(
                "TOPIC TAXONOMY: OpenAlex has not yet reprocessed this work under its current topic "
                "hierarchy, so interdisciplinarity was measured from the legacy concept taxonomy. "
                "C3 and C4 are correspondingly less precise."
            )
        elif topology_detail.get("basis") == "unavailable" and provided_doi not in ("None", "", None):
            warnings_list.append(
                "TOPIC LOOKUP FAILED: this work could not be resolved in OpenAlex, so "
                "interdisciplinarity fell back to a neutral prior rather than measured evidence."
            )
        warnings_list.extend(reference_audit.get("warnings", []))

        integrity = guarded(lambda: run_static_integrity_scan(file_bytes, full_text),
                            fallback=_EMPTY_INTEGRITY(), label="integrity scan")

        authorship = guarded(lambda: assess_authorship_consistency(full_text),
                             fallback=_EMPTY_AUTHORSHIP(), label="authorship signal")

        canary = issue_integrity_canary(file_hash)

        raw_data = run_evaluation_pipeline(full_text, PRIMARY_MODEL, MAX_TEXT_TOKENS, file_hash, canary)

        pidyne_ai_rating = raw_data.get("_pidyne_rating", 75.0)
        scilem_score = raw_data.get("_scilem_score", pidyne_ai_rating)
        consensus_raw = raw_data.get("_consensus_raw", {})
        evidence_report = raw_data.get("_evidence_report", "")

        judge_meta_early = consensus_raw.get("_judge_metadata", {})

        corroboration_detail = measure_panel_corroboration(judge_meta_early, evidence_report)
        corroboration = corroboration_detail["index"]

        classification = classify_manuscript_fields(full_text, topology_detail.get("_topics"))
        topology_detail.pop("_topics", None)

        external_active = any(
            not v.get("api_failed", False) 
            for k, v in consensus_raw.items() 
            if k != "scilem" and k != "_judge_metadata"
        )
        
        registry_meta = guarded(lambda: fetch_registry_metadata(provided_doi),
                                fallback={}, label="registry metadata") or {}
        layout_meta = guarded(lambda: extract_from_pdf_layout(file_bytes),
                              fallback={}, label="pdf layout") or {}
        bibliographic = reconcile_bibliographic_record(
            registry=registry_meta,
            layout=layout_meta,
            model_title=raw_data.get("Extracted_Title", ""),
            model_authors=raw_data.get("Extracted_Author", ""),
            filename=filename,
        )
        title = bibliographic["title"]
        extracted_author = bibliographic["authors"]
        if extracted_author in ("", "Unidentified") and pdf_meta_author:
            cleaned_meta = clean_author_list(pdf_meta_author)
            if cleaned_meta:
                extracted_author = cleaned_meta
                bibliographic["authors"] = cleaned_meta
                bibliographic["authors_basis"] = "pdf-metadata"
                bibliographic["authors_confidence"] = 0.4

        if bibliographic["title_confidence"] < 0.5:
            warnings_list.append(
                f"LOW-CONFIDENCE TITLE: the title was inferred from "
                f"{bibliographic['title_basis'].replace('-', ' ')} and may be wrong. Supplying a DOI "
                f"lets the publisher-deposited record be used instead."
            )
        if bibliographic["authors_confidence"] < 0.5:
            warnings_list.append(
                f"LOW-CONFIDENCE AUTHORS: the author list was inferred from "
                f"{bibliographic['authors_basis'].replace('-', ' ')}. piQ attribution depends on this, "
                f"so verify it before relying on the leaderboard entry."
            )

        reference_entries = guarded(lambda: parse_reference_entries(full_text),
                                    fallback=[], label="reference parsing") or []
        reference_summary = summarize_references(reference_entries)
        reference_audit["parsed_entries"] = len(reference_entries)
        reference_audit["summary"] = reference_summary
        reference_audit["entries"] = reference_entries[:40]
        reference_audit["bibliographic"] = {
            "title_basis": bibliographic["title_basis"],
            "title_confidence": bibliographic["title_confidence"],
            "authors_basis": bibliographic["authors_basis"],
            "authors_confidence": bibliographic["authors_confidence"],
            "journal": bibliographic.get("journal", ""),
            "year": bibliographic.get("year"),
            "title_alternatives": bibliographic.get("title_alternatives", [])[:3],
        }
        if registry_meta.get("reference_count") and reference_summary["total"]:
            declared = registry_meta["reference_count"]
            found = reference_summary["total"]
            if found < declared * 0.5:
                warnings_list.append(
                    f"REFERENCE EXTRACTION INCOMPLETE: the publisher record lists {declared} "
                    f"references but only {found} could be parsed from the PDF. Literature "
                    f"engagement may be understated."
                )
        
        signal_vector = build_signal_vector(
            panel_rating=pidyne_ai_rating,
            corroboration=corroboration,
            mdar_adherence=mdar_score,
            rrid_count=rrid_count,
            reproducibility=reproducibility_score,
            empirical_density=empirical_density,
            topology_detail=topology_detail,
            reference_audit=reference_audit,
            text=full_text,
            text_complete=bool(full_text.strip()),
        )
        author_metrics = guarded(lambda: fetch_author_metrics(extracted_author),
                                 fallback={}, label="author bibliometrics")
        work_authors = guarded(lambda: fetch_work_authors(real_doi(provided_doi)), fallback=None,
                               label="the work's authors")

        scores_dict = apply_scoring_rubric(signal_vector)
        criteria_breakdown = explain_all_criteria(signal_vector)

        if reference_audit.get("penalty_applied"):
            scores_dict["C2_Methodological_Rigor_SciScore"] = 0.0
            for entry in criteria_breakdown:
                if entry["id"] == "C2_Methodological_Rigor_SciScore":
                    entry["score"] = 0.0
                    entry["override"] = "Zeroed: fabricated references detected."

        cursor.execute(
            """SELECT block_height, w1, w2, w3, w4, w5, w6, w7, w8
               FROM blockchain_por_weights ORDER BY block_height DESC LIMIT 1"""
        )
        weight_row = cursor.fetchone()
        scoring_epoch = weight_row[0] if weight_row else 0
        epoch_weights = list(weight_row[1:9]) if weight_row else None

        final_score = compute_composite_score(scores_dict, epoch_weights)
        unweighted_score = compute_composite_score(scores_dict)

        premise_gap = 1.0 - (pidyne_ai_rating / 100.0)
        corroboration_gap = 1.0 - corroboration
        adversarial_penalty = math.exp(-(1.5 * premise_gap + 0.6 * corroboration_gap))
        logic_integrity = min(100.0, max(0.0, pidyne_ai_rating * adversarial_penalty))

        integrity = apply_panel_integrity_verdict(integrity, consensus_raw, canary)

        if integrity.get("compromised"):
            logic_integrity = 0.0
            integrity["status"] = "quarantined"
            integrity["review_required"] = True
            integrity["appeal"] = (
                "This finding withholds piQ and flags the submission for human review. It is not "
                "a determination of misconduct and has not been published as one. If you believe "
                "it is mistaken, the assessment can be re-run after review."
            )
        warnings_list.extend(integrity.get("warnings", []))

        cursor.execute("SELECT COUNT(*) FROM papers_assessment")
        corpus_row = cursor.fetchone()
        corpus_size = corpus_row[0] if corpus_row else 0

        author_key = (author_metrics or {}).get("openalex_id") or ""
        author_paper_count = 0
        try:
            if author_key:
                cursor.execute(
                    """SELECT COUNT(*) FROM papers_assessment
                       WHERE author_openalex_id = ? AND eval_hash != ?""",
                    (author_key, file_hash),
                )
            else:
                cursor.execute(
                    """SELECT COUNT(*) FROM papers_assessment
                       WHERE LOWER(TRIM(author_name)) = LOWER(TRIM(?)) AND eval_hash != ?""",
                    (extracted_author or "", file_hash),
                )
            row = cursor.fetchone()
            author_paper_count = row[0] if row else 0
        except Exception:
            author_paper_count = 0

        attribution = guarded(
            lambda: verify_authorship(
                submitter_orcid=user_id if "-" in str(user_id) else "",
                submitter_wallet=book_address,
                extracted_authors=extracted_author,
                doi=provided_doi,
                title=title,
            ),
            fallback={"verified": False, "tier": "unverified", "confidence": 0.0,
                      "reason": "Authorship verification was unavailable for this assessment."},
            label="authorship verification",
        )

        emission = compute_piq_emission(
            pix_score=final_score,
            logic_integrity=logic_integrity,
            total_papers=corpus_size,
            author_paper_count=author_paper_count,
        )
        # Minted vs escrowed. `piq_minted` remains the settled figure — it is
        # what the leaderboard ranks and what settles on-chain — so holding an
        # unverified claim can never inflate it. The escrow records what the
        # paper earned so it is visible and claimable rather than silently lost.
        verified = bool(attribution.get("verified"))
        piq_minted = emission["minted"] if verified else 0.0
        piq_escrowed = 0.0 if verified else emission["minted"]
        emission["attribution"] = attribution
        emission["escrowed"] = piq_escrowed
        if not verified:
            emission["minted"] = 0.0
            emission["withheld_reason"] = "unverified_authorship"
            warnings_list.append(
                "piQ WITHHELD — AUTHORSHIP UNVERIFIED: " + attribution.get("reason", "")
                + (" " + attribution["how_to_verify"] if attribution.get("how_to_verify") else "")
            )
        # Report the reason that actually applies.
        #
        # This previously showed a paper's real reason for minting nothing only
        # when authorship was verified; every other failure fell through to the
        # "EMISSION DIFFICULTY" branch, which then printed "minted 0.0000 piQ"
        # beside a supply factor of 1.0000 and an author factor of 0.99. That
        # blamed scarcity for an outcome scarcity had no part in — a paper
        # blocked by the logic gate was told the platform was getting harder.
        #
        # Qualification is now reported whenever the paper failed to qualify,
        # whoever submitted it, and the difficulty note is reserved for papers
        # that DID qualify and were genuinely scaled down.
        if not emission["qualified"]:
            warnings_list.append("piQ NOT MINTED: " + " ".join(emission["reasons"]))
        elif (emission["halving_epoch"] > 0 or emission["author_factor"] < 1.0) and (
                piq_minted > 0 or piq_escrowed > 0):
            amount = piq_minted if piq_minted > 0 else piq_escrowed
            where = "minted" if piq_minted > 0 else "earned and held"
            warnings_list.append(
                f"EMISSION DIFFICULTY: {amount:.4f} piQ {where} at halving epoch "
                f"{emission['halving_epoch']} (supply factor {emission['supply_factor']:.4f}, "
                f"author factor {emission['author_factor']:.4f}). Emission hardens as the "
                f"platform grows."
            )

        zk_proof = generate_zk_snark_proof(file_hash, pidyne_ai_rating, logic_integrity, "None")
        
        # Settlement no longer depends on whether a language model answered.
        #
        # `external_active` used to gate this. It means "at least one external
        # juror was reachable", which is a statement about provider uptime and
        # has nothing to do with whether a token should settle. A paper with
        # verified authorship, a qualifying score and a connected wallet was
        # silently given a simulated record because a provider happened to be
        # down — and, since nothing re-tried, it stayed unsettled forever.
        #
        # The quality caveat that condition was standing in for is already
        # handled honestly, and separately, by the "no external juror" warning
        # appended below. One concern, one mechanism: a warning describes the
        # assessment, the ledger records what was earned.
        if (book_address
                and book_address != "0x0000000000000000000000000000000000000000"
                and piq_minted > 0):
            tx_hash = mint_pi_quotient_token(book_address, piq_minted, file_hash, zk_proof)
        else:
            tx_hash = "Simulated_Ledger_Record"

        judge_meta = consensus_raw.get("_judge_metadata", {})
        if not external_active:
            warnings_list.append(
                "NOTICE: No external LLM juror was reachable. This assessment was completed using the "
                "local SciLM (siM) neural model and deterministic heuristics only; judgement quality is LIMITED."
            )
        elif judge_meta.get("external_juror_count", 0) == 1:
            warnings_list.append(
                "NOTICE: Only one external LLM juror participated. The verdict was not corroborated "
                "across independent providers; judgement quality is MODERATE."
            )
        if judge_meta.get("failed_models"):
            warnings_list.append(
                "MODEL AVAILABILITY: " + "; ".join(
                    f"{m['label']} did not return a verdict" for m in judge_meta["failed_models"]
                ) + "."
            )
        if not judge_meta.get("judge_succeeded", True):
            warnings_list.append(
                "JUDGE FALLBACK: The final adjudicating model was unavailable; the verdict was "
                "synthesized from the unified fallback consensus path instead."
            )
        agreement = judge_meta.get("inter_model_agreement", 0.0)
        if judge_meta.get("external_juror_count", 0) >= 2 and agreement < 0.4:
            warnings_list.append(
                f"LOW INTER-MODEL AGREEMENT: Jurors converged on the document's identity only "
                f"{agreement * 100:.0f}% of the time, suggesting ambiguous or poorly structured front matter."
            )
        if not full_text.strip():
            warnings_list.append(
                "TEXT EXTRACTION EMPTY: No machine-readable text could be extracted from this PDF "
                "(it may be a scanned image). Scores derive from limited signal."
            )
        elif len(full_text) < 2000:
            warnings_list.append(
                f"SHORT DOCUMENT: Only {len(full_text)} characters of text were extracted; "
                f"criteria coverage may be incomplete."
            )
        if rrid_count == 0:
            warnings_list.append(
                "NO VALID RRIDs: No Research Resource Identifiers were detected, which caps the "
                "achievable C2 Methodological Rigor score."
            )

        cursor.execute(
            """INSERT OR REPLACE INTO papers_assessment (
                eval_hash, user_id, title, filename, scope, c1, c2, c3, c4, c5, c6, c7, c8, 
                logic_score, scope_alignment, subfields, fields, author_name, final_score, 
                timestamp, eth_book, piq_minted, tx_hash, zk_proof, did, zk_email_proof, 
                gaming_penalty, mdar_adherence_score, rrid_valid_count, credit_taxonomy_roles,
                reproducibility_score, doi, consensus_data, evidence_report, scilem_score,
                warnings_json, judge_metadata, integrity_report, reference_audit,
                authorship_signal, topology_detail, classification, criteria_breakdown,
                signal_vector, rubric_version, author_metrics, emission_record,
                author_openalex_id, scoring_epoch, unweighted_score, attribution,
                scilem_signals, piq_escrowed, contact_emails, content_hash
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (
                file_hash, user_id, title, filename, scope, *scores_dict.values(),
                logic_integrity, 0.0,
                json.dumps(classification.get("subfields", ["Unclassified"])),
                json.dumps(classification.get("fields", ["Unclassified"])),
                extracted_author, final_score,
                datetime.now().isoformat(), book_address, piq_minted,
                tx_hash, zk_proof, user_id, "None", 0.0,
                mdar_score, rrid_count, json.dumps(infer_credit_taxonomy_roles(full_text)), reproducibility_score,
                provided_doi, json.dumps(consensus_raw), evidence_report, scilem_score,
                json.dumps(warnings_list), json.dumps(judge_meta),
                json.dumps(integrity), json.dumps(reference_audit),
                json.dumps(authorship), json.dumps(topology_detail),
                json.dumps(classification), json.dumps(criteria_breakdown),
                json.dumps(signal_vector), RUBRIC_VERSION, json.dumps(author_metrics),
                json.dumps(emission), author_key, scoring_epoch, unweighted_score,
                json.dumps(attribution),
                # Stored so a correction submitted later can be learned from
                # without this deployment having to retain manuscript text.
                json.dumps(measure_structural_signals(full_text)),
                piq_escrowed,
                json.dumps([e["email"] for e in
                            extract_candidate_emails(full_text)]),
                # Identifies the work, so the next copy of this paper to arrive
                # in a different file merges into this record instead of
                # opening a second one.
                paper_fingerprint,
            ),
        )

        if work_authors is not None:
            cursor.execute("UPDATE papers_assessment SET author_ids = ? WHERE eval_hash = ?",
                           (json.dumps(work_authors), file_hash))

        cursor.execute("SELECT COUNT(*) FROM blockchain_por_weights")
        count_row = cursor.fetchone()
        block_count = count_row[0] if count_row else 1

        cursor.execute(
            """SELECT block_hash, w1, w2, w3, w4, w5, w6, w7, w8
               FROM blockchain_por_weights ORDER BY block_height DESC LIMIT 1"""
        )
        hash_row = cursor.fetchone()
        prev_hash = hash_row[0] if hash_row and hash_row[0] else "0" * 64
        prev_weights = list(hash_row[1:9]) if hash_row else None

        active_weights = derive_next_epoch_weights(scores_dict, prev_weights)

        new_height = block_count + 1
        ts = datetime.now().isoformat()
        f_hash = compute_rubric_fingerprint()
        val_node, b_hash, por_p = validate_block_por(
            new_height, active_weights, ts, prev_hash, file_hash, "Pidyne_Scilem_Ensemble", final_score, f_hash
        )

        cursor.execute(
            """INSERT INTO blockchain_por_weights 
               (w1, w2, w3, w4, w5, w6, w7, w8, timestamp, previous_hash, validator_node, block_hash, eval_hash, model_used, por_proof, formulas_hash)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (*active_weights, ts, prev_hash, val_node, b_hash, file_hash, "Pidyne_Scilem_Ensemble", por_p, f_hash)
        )

        conn.commit()
    finally:
        conn.close()

    backup_state_to_web3()

    return (
        title, extracted_author, final_score, logic_integrity,
        classification, criteria_breakdown,
        classification.get("fields", ["Unclassified"]),
        classification.get("subfields", ["Unclassified"]),
        scores_dict, file_hash, piq_minted, tx_hash, zk_proof,
        active_weights, mdar_score, rrid_count, reproducibility_score, False, warnings_list,
        consensus_raw, evidence_report, scilem_score,
        integrity, reference_audit, authorship, topology_detail, author_metrics, emission
    )


# ==============================================================================================================
# bugreport.py (was its own module; LicenseRef-PiTechLab-Proprietary)
# ==============================================================================================================
"""
Bug reports: stored first, mailed second.

The ordering is the whole design. Mail is the failure-prone half of this
feature — credentials expire, providers throttle, hosts block outbound port
587 — and a report that a user was told had been sent, but which was silently
dropped, is worse than a feature that does not exist. So every report is
committed to the database before any network call is attempted, and the
delivery outcome is recorded against the row. Nothing a user takes the trouble
to write can be lost by a mail failure.

Mail is also sent on a background thread. A user pressing "Send report" should
not wait on an SMTP handshake, and an unreachable mail server must not hold the
request open until the gateway times out — which would present as the very
class of bug people are most likely to be reporting.
"""


MAX_MESSAGE_CHARS = 5000
MAX_CONTACT_CHARS = 200

# Deliberately permissive: this validates shape, not deliverability. Rejecting
# an unusual-but-valid address would lose a report, which costs more than
# accepting one that later bounces.
_bugreport_EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")


def smtp_configured() -> bool:
    return bool(SMTP_HOST and SMTP_FROM)


def delivery_status() -> Dict:
    """What the UI should promise the user before they type anything.

    If mail is not configured, the form still works and still stores the
    report — but it must not claim the message was emailed.
    """
    return {
        "recipient": BUG_REPORT_TO,
        "email_enabled": smtp_configured(),
        "note": (
            "Your report is sent by email and also stored on the server."
            if smtp_configured() else
            "Email delivery is not configured on this deployment, so your report is stored "
            "on the server for the maintainer to read. It will not be lost."
        ),
    }


def bugreport_validate(message: str, contact: str = "") -> Optional[str]:
    """Returns an error string, or None when the report is acceptable."""
    message = (message or "").strip()
    if len(message) < 10:
        return "Please describe the problem in a little more detail (at least 10 characters)."
    if len(message) > MAX_MESSAGE_CHARS:
        return f"Report is too long (max {MAX_MESSAGE_CHARS:,} characters)."
    contact = (contact or "").strip()
    if contact:
        if len(contact) > MAX_CONTACT_CHARS:
            return "Contact address is too long."
        if not _bugreport_EMAIL_RE.match(contact):
            return "That does not look like a valid email address. Leave it blank to report anonymously."
    return None


def _header_safe(value: str) -> str:
    """Strip CR/LF from anything interpolated into a mail header.

    A newline in a user-supplied header value lets the sender inject arbitrary
    additional headers — extra Bcc recipients, a forged Reply-To — turning this
    form into an open relay. The contact address reaches the Reply-To header,
    so it is untrusted input in a header position and must be flattened.
    """
    return re.sub(r"[\r\n]+", " ", str(value or "")).strip()[:MAX_CONTACT_CHARS]


def bugreport_build_message(report: Dict) -> EmailMessage:
    msg = EmailMessage()
    summary = _header_safe(report.get("message", ""))[:60] or "Bug report"
    msg["Subject"] = f"[ScholarPi] Bug report #{report.get('id', '?')}: {summary}"
    msg["From"] = SMTP_FROM
    msg["To"] = BUG_REPORT_TO
    contact = _header_safe(report.get("contact", ""))
    if contact and _bugreport_EMAIL_RE.match(contact):
        # Lets the maintainer reply straight to the reporter. Only set when the
        # address passed validation, so a malformed value cannot land here.
        msg["Reply-To"] = contact

    # The body carries the context that makes a report actionable without a
    # follow-up round trip: what they were doing, what the client was, and
    # which identity (if any) it happened under.
    body = [
        f"Report #{report.get('id', '?')}",
        f"Received:  {report.get('created_at', '')}",
        f"Contact:   {contact or '(not provided)'}",
        f"Identity:  {report.get('identity') or '(anonymous)'}",
        f"Page:      {report.get('page') or '(unknown)'}",
        f"Env:       {ENVIRONMENT}",
        "",
        "--- Report ---",
        str(report.get("message", "")).strip(),
    ]
    if report.get("user_agent"):
        body += ["", "--- Client ---", str(report["user_agent"])[:500]]
    msg.set_content("\n".join(body))
    return msg


def send_email(report: Dict) -> Dict:
    """Attempt delivery. Never raises — the caller has already stored the row."""
    if not smtp_configured():
        return {"sent": False, "error": "SMTP is not configured on this deployment."}
    try:
        msg = bugreport_build_message(report)
        if SMTP_PORT == 465:
            # Implicit TLS: the socket is encrypted from the first byte, so
            # STARTTLS is neither needed nor available on this port.
            with smtplib.SMTP_SSL(SMTP_HOST, SMTP_PORT, timeout=20,
                                  context=ssl.create_default_context()) as server:
                if SMTP_USER:
                    server.login(SMTP_USER, SMTP_PASSWORD)
                server.send_message(msg)
        else:
            with smtplib.SMTP(SMTP_HOST, SMTP_PORT, timeout=20) as server:
                if SMTP_USE_TLS:
                    server.starttls(context=ssl.create_default_context())
                if SMTP_USER:
                    server.login(SMTP_USER, SMTP_PASSWORD)
                server.send_message(msg)
        return {"sent": True, "error": None}
    except Exception as e:
        # The exception text can name the mail host and the account, so it is
        # logged rather than returned to the browser.
        logging.warning("Bug report #%s email delivery failed: %s: %s",
                        report.get("id"), type(e).__name__, e)
        return {"sent": False, "error": f"{type(e).__name__}: {e}"[:300]}


def send_async(report: Dict, on_result=None):
    """Deliver off the request thread.

    The user's confirmation depends on the report being *stored*, which has
    already happened by the time this is called. Blocking their request on an
    SMTP handshake would add a multi-second wait, and a hung mail server would
    stall the request until the gateway killed it.
    """
    def run():
        result = send_email(report)
        if on_result:
            try:
                on_result(report.get("id"), result)
            except Exception:
                logging.exception("Bug report delivery callback failed")

    threading.Thread(target=run, name="bugreport-mail", daemon=True).start()


def normalise(message: str, contact: str, identity: str, page: str,
              user_agent: str, report_id=None) -> Dict:
    return {
        "id": report_id,
        "message": (message or "").strip()[:MAX_MESSAGE_CHARS],
        "contact": (contact or "").strip()[:MAX_CONTACT_CHARS],
        "identity": (identity or "").strip()[:120],
        "page": (page or "").strip()[:120],
        "user_agent": (user_agent or "").strip()[:500],
        "created_at": datetime.now().isoformat(timespec="seconds"),
    }


# ==============================================================================================================
# challenge.py (was its own module; LicenseRef-PiTechLab-Proprietary)
# ==============================================================================================================
"""
Proof-of-work challenge for free-tier submissions.

Why proof-of-work rather than a visual CAPTCHA
----------------------------------------------
Image CAPTCHAs no longer separate humans from automated agents: commercial
solvers and multimodal models clear them at high accuracy and low cost, so the
puzzle mostly taxes legitimate users — disproportionately those using screen
readers. They also require a third-party service, which means embedding an
external tracker on a research tool whose entire premise is researcher
sovereignty.

A computational proof-of-work inverts the economics instead of testing
perception. Solving one challenge costs a browser roughly a second of CPU;
it is imperceptible for someone assessing a paper, and it makes bulk automated
submission expensive in exactly the dimension an abuser cares about. It needs
no third party, sets no cookies, collects no biometrics, and works identically
for assistive technology.

Design
------
* The server issues a random challenge and a difficulty, signed with HMAC. No
  server-side state is required to validate it later — the signature carries
  the parameters, so this survives restarts and multiple workers.
* The client searches for a nonce where ``sha256(challenge:nonce)`` begins with
  the required number of zero bits.
* Difficulty scales with observed pressure: a first-time visitor gets a trivial
  puzzle, and a client that has been submitting heavily gets a harder one. The
  cost lands on abusive patterns rather than on everyone.
* Solutions are single-use and short-lived, so a solved challenge cannot be
  replayed across a batch of submissions.

Cloudflare Turnstile is supported as an optional additional layer when keys are
configured, for operators who want a managed signal as well.
"""


# --- Tuning ---------------------------------------------------------------
# Leading zero bits required. 16 bits ≈ 65k hashes ≈ well under a second in a
# browser; 22 bits ≈ 4M hashes ≈ several seconds. The point is not to be
# unsolvable but to make thousands of submissions costly.
BASE_DIFFICULTY = 16
MAX_DIFFICULTY = 24
CHALLENGE_TTL_SECONDS = 300
_challenge_SECRET = (ETH_ADMIN_PRIVATE_KEY or "scholarpi_pow_seed").encode("utf-8")

_challenge_lock = threading.Lock()
_consumed = {}          # solution digest -> expiry, prevents replay
_recent_solves = {}     # ip -> [timestamps], drives adaptive difficulty


def _challenge_sign(payload: str) -> str:
    return hmac.new(_challenge_SECRET, payload.encode("utf-8"), hashlib.sha256).hexdigest()[:32]


def _prune(now: float):
    for digest, expiry in list(_consumed.items()):
        if expiry < now:
            _consumed.pop(digest, None)
    for ip, stamps in list(_recent_solves.items()):
        kept = [t for t in stamps if now - t < 3600]
        if kept:
            _recent_solves[ip] = kept
        else:
            _recent_solves.pop(ip, None)


def difficulty_for(ip: str) -> int:
    """Escalate with recent solve volume from the same client.

    A researcher assessing a handful of papers never leaves the base tier. A
    client solving continuously climbs until each puzzle costs real time, which
    is the behaviour that should be expensive.
    """
    now = time.time()
    with _challenge_lock:
        _prune(now)
        recent = len(_recent_solves.get(ip, []))
    return min(MAX_DIFFICULTY, BASE_DIFFICULTY + (recent // 3) * 2)


def issue_challenge(ip: str) -> Dict:
    """Mint a stateless, signed challenge."""
    nonce = secrets.token_hex(16)
    issued = int(time.time())
    difficulty = difficulty_for(ip)
    payload = f"{nonce}:{issued}:{difficulty}"
    return {
        "challenge": nonce,
        "issued_at": issued,
        "difficulty": difficulty,
        "signature": _challenge_sign(payload),
        "algorithm": "sha256-leading-zero-bits",
        "expires_in": CHALLENGE_TTL_SECONDS,
        "instructions": (
            "Find an integer nonce such that the SHA-256 of "
            "'<challenge>:<nonce>' begins with the required number of zero bits."
        ),
    }


def _leading_zero_bits(digest: bytes) -> int:
    bits = 0
    for byte in digest:
        if byte == 0:
            bits += 8
            continue
        # Count leading zeros within the first non-zero byte.
        for shift in range(7, -1, -1):
            if byte >> shift:
                break
            bits += 1
        break
    return bits


def verify_solution(ip: str, challenge: str, issued_at, difficulty,
                    signature: str, solution) -> Tuple[bool, Optional[str]]:
    """Validate a submitted proof of work.

    Every parameter is re-derived from the signature rather than trusted, so a
    client cannot lower its own difficulty or extend its own expiry.
    """
    try:
        issued_at = int(issued_at)
        difficulty = int(difficulty)
        solution = str(solution)
    except (TypeError, ValueError):
        return False, "Malformed challenge response."

    if not challenge or not signature:
        return False, "Missing challenge parameters."

    expected = _challenge_sign(f"{challenge}:{issued_at}:{difficulty}")
    if not hmac.compare_digest(expected, signature):
        return False, "Challenge signature is invalid."

    now = time.time()
    if now - issued_at > CHALLENGE_TTL_SECONDS:
        return False, "Challenge expired. Request a new one."
    if issued_at > now + 60:
        return False, "Challenge timestamp is in the future."
    if not (BASE_DIFFICULTY <= difficulty <= MAX_DIFFICULTY):
        return False, "Challenge difficulty is out of range."

    digest = hashlib.sha256(f"{challenge}:{solution}".encode("utf-8")).digest()
    if _leading_zero_bits(digest) < difficulty:
        return False, "Proof of work is insufficient."

    # Single use: a solved challenge cannot be replayed across submissions.
    fingerprint = hashlib.sha256(f"{challenge}:{solution}".encode()).hexdigest()
    with _challenge_lock:
        _prune(now)
        if fingerprint in _consumed:
            return False, "This challenge has already been used."
        _consumed[fingerprint] = now + CHALLENGE_TTL_SECONDS
        _recent_solves.setdefault(ip, []).append(now)
    return True, None


# ---------------------------------------------------------------------------
# Optional managed layer
# ---------------------------------------------------------------------------
def verify_turnstile(token: str, ip: str = "") -> Tuple[bool, Optional[str]]:
    """Validate a Cloudflare Turnstile token, when configured.

    Additive rather than a replacement: proof-of-work still applies, so the
    deployment does not depend on a third party being reachable.
    """
    if not TURNSTILE_SECRET_KEY:
        return True, None
    if not token:
        return False, "Verification token missing."
    try:
        pass
        res = get_session().post(
            "https://challenges.cloudflare.com/turnstile/v0/siteverify",
            data={"secret": TURNSTILE_SECRET_KEY, "response": token, "remoteip": ip},
            timeout=8,
        )
        payload = res.json() if res.status_code == 200 else {}
        if payload.get("success"):
            return True, None
        return False, "Verification failed. Please try again."
    except Exception as e:
        # An outage at the verification provider must not lock out legitimate
        # users; proof-of-work remains in force either way.
        logging.warning("Turnstile verification unavailable: %s", e)
        return True, None


# ==============================================================================================================
# consent.py (was its own module; LicenseRef-PiTechLab-Proprietary)
# ==============================================================================================================
"""consent.py -- permission requests with a confirm link.

The owner writes to an author ("may we feature your work?") and includes a
link. The link opens a page that states exactly what is being asked, and the
recipient answers with one click. The answer is kept as the written record.

    owner   POST /api/consent              create a request, get its link
    owner   GET  /api/consent              every request and its answers
    owner   POST /api/consent/{id}/close   stop accepting answers
    link    GET  /api/consent/r/{token}    what is being asked (public with the token)
    link    POST /api/consent/r/{token}    answer: granted or declined

DESIGN NOTES

  * The token in the link is the only credential the recipient has, so it is
    long (32 bytes, urlsafe) and random. Without it the request cannot be
    read or answered; with it, only that one request can be.
  * Answers are append-only. If the recipient changes their mind the new
    answer is recorded after the old one, and the latest one counts. A record
    that could be silently overwritten would not be a record.
  * Each answer stores what the recipient saw: the title and terms are
    copied into the answer, so editing a request later cannot change what
    someone agreed to.
  * Stored in its own SQLite file next to the main database. It touches no
    existing table, so it cannot affect assessments, ledgers or migrations.
"""




MAX_ANSWERS_PER_REQUEST = 50


class NewRequest(BaseModel):
    title: str = Field(..., min_length=3, max_length=200)
    recipient: str = Field(..., min_length=2, max_length=120)
    work: str = Field("", max_length=300)            # the work being asked about
    message: str = Field("", max_length=4000)        # shown above the terms
    terms: List[str] = Field(default_factory=list, max_length=20)
    requester: str = Field("", max_length=200)       # who is asking


class Answer(BaseModel):
    decision: str = Field(..., pattern="^(granted|declined)$")
    name: str = Field(..., min_length=2, max_length=120)
    note: str = Field("", max_length=2000)


def _consent_now() -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


def consent_build_router(base_dir: str, require_owner: Callable) -> APIRouter:
    db_path = os.path.join(base_dir, "consent.db")
    router = APIRouter(prefix="/api/consent", tags=["consent"])

    def conn():
        os.makedirs(base_dir, exist_ok=True)
        c = sqlite3.connect(db_path, timeout=10)
        c.row_factory = sqlite3.Row
        c.execute("""CREATE TABLE IF NOT EXISTS requests (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            token TEXT UNIQUE NOT NULL,
            title TEXT NOT NULL, recipient TEXT NOT NULL, work TEXT,
            message TEXT, terms TEXT NOT NULL, requester TEXT,
            created_at TEXT NOT NULL, closed_at TEXT)""")
        c.execute("""CREATE TABLE IF NOT EXISTS answers (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            request_id INTEGER NOT NULL REFERENCES requests(id),
            decision TEXT NOT NULL, name TEXT NOT NULL, note TEXT,
            answered_at TEXT NOT NULL,
            seen_title TEXT NOT NULL, seen_terms TEXT NOT NULL,
            ip TEXT, user_agent TEXT)""")
        return c

    def public_view(row) -> dict:
        return {
            "title": row["title"], "recipient": row["recipient"], "work": row["work"] or "",
            "message": row["message"] or "", "terms": json.loads(row["terms"]),
            "requester": row["requester"] or "", "created_at": row["created_at"],
            "closed": bool(row["closed_at"]),
        }

    def latest_answer(c, request_id):
        a = c.execute("SELECT decision, name, note, answered_at FROM answers WHERE request_id=? "
                      "ORDER BY id DESC LIMIT 1", (request_id,)).fetchone()
        return dict(a) if a else None

    def ip_of(request: Request) -> str:
        return client_ip(request, "")

    # ---------------------------------------------------------------- owner
    @router.post("")
    def create(body: NewRequest, request: Request):
        require_owner(request)
        terms = [t.strip()[:500] for t in body.terms if t and t.strip()]
        if not terms:
            raise HTTPException(status_code=400, detail="Add at least one term the recipient agrees to.")
        token = secrets.token_urlsafe(32)
        with conn() as c:
            cur = c.execute(
                "INSERT INTO requests (token, title, recipient, work, message, terms, requester, created_at) "
                "VALUES (?,?,?,?,?,?,?,?)",
                (token, body.title.strip(), body.recipient.strip(), body.work.strip(),
                 body.message.strip(), json.dumps(terms), body.requester.strip(), _consent_now()))
            rid = cur.lastrowid
        return {"id": rid, "token": token, "path": "/confirm/?t=" + token}

    @router.get("")
    def list_all(request: Request):
        require_owner(request)
        out = []
        with conn() as c:
            for r in c.execute("SELECT * FROM requests ORDER BY id DESC").fetchall():
                answers = [dict(a) for a in c.execute(
                    "SELECT decision, name, note, answered_at, ip, user_agent FROM answers "
                    "WHERE request_id=? ORDER BY id", (r["id"],)).fetchall()]
                item = public_view(r)
                item.update({"id": r["id"], "path": "/confirm/?t=" + r["token"],
                             "status": answers[-1]["decision"] if answers else "pending",
                             "answers": answers})
                out.append(item)
        return {"requests": out}

    @router.post("/{rid}/close")
    def close(rid: int, request: Request):
        require_owner(request)
        with conn() as c:
            c.execute("UPDATE requests SET closed_at=? WHERE id=? AND closed_at IS NULL", (_consent_now(), rid))
        return {"ok": True}

    # ---------------------------------------------------------------- recipient
    def by_token(c, token: str):
        if not token or len(token) > 100:
            raise HTTPException(status_code=404, detail="This link is not valid.")
        row = c.execute("SELECT * FROM requests WHERE token=?", (token,)).fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="This link is not valid.")
        return row

    @router.get("/r/{token}")
    def view(token: str):
        with conn() as c:
            row = by_token(c, token)
            data = public_view(row)
            data["answer"] = latest_answer(c, row["id"])
        return data

    @router.post("/r/{token}")
    def answer(token: str, body: Answer, request: Request):
        with conn() as c:
            row = by_token(c, token)
            if row["closed_at"]:
                raise HTTPException(status_code=409, detail="This request has been closed by its sender.")
            n = c.execute("SELECT COUNT(*) FROM answers WHERE request_id=?", (row["id"],)).fetchone()[0]
            if n >= MAX_ANSWERS_PER_REQUEST:
                raise HTTPException(status_code=429, detail="Too many answers for this request.")
            when = _consent_now()
            c.execute(
                "INSERT INTO answers (request_id, decision, name, note, answered_at, seen_title, "
                "seen_terms, ip, user_agent) VALUES (?,?,?,?,?,?,?,?,?)",
                (row["id"], body.decision, body.name.strip(), body.note.strip(), when,
                 row["title"], row["terms"], ip_of(request)[:64],
                 (request.headers.get("user-agent") or "")[:300]))
        # A short receipt the recipient can keep: hash of what they agreed to.
        receipt = hashlib.sha256(
            f"{token}|{body.decision}|{body.name.strip()}|{when}|{row['terms']}".encode()).hexdigest()[:16]
        return {"decision": body.decision, "answered_at": when, "receipt": receipt}

    return router


# ==============================================================================================================
# cookies.py (was its own module; LicenseRef-PiTechLab-Proprietary)
# ==============================================================================================================
"""cookies.py -- the cookies and browser storage the site uses, and what a visitor allowed.

Owner, 2026-10-13: "add ask for permission what site is doing with users when site loads", "use cookies", "add use
of cookies for the site and its permissions".

The visitor's choice is the first-party cookie pi_consent, set by the first-visit notice (frontend/super/consent.js):

    pi_consent=v1.c1.l0.e1      c: count my visit   l: help PiEn learn   e: outside AI providers

The page already sends nothing a visitor declined. Here the server honours the same choice on its own, so a
request that reaches it anyway is refused: when a browser's pi_consent says no to something, the server does not
do it. With no pi_consent at all (an API client, a script, a test) the server does not guess: it serves the request
as before, since a browser that has not chosen yet sends nothing optional in the first place.

    GET /api/cookies   -> {version, cookies: [...], storage: [...], choice: {count, learn, ext} | null}

The lists below are what the notice shows under "Cookies and storage", so what the site says it uses and what it
does use are written in one place. Add a cookie or a storage key here when the site starts using one.
"""


cookies_COOKIE = "pi_consent"
VERSION = "v1"
YEAR = 365 * 24 * 3600

# every cookie the site sets: no tracking or advertising cookies, and none from other sites
COOKIES: List[Dict] = [
    {"name": "pi_consent", "purpose": "Remembers your privacy choices (this notice), so we do not ask again.",
     "essential": True, "lasts": "1 year", "set_by": "this site (the page)", "read_by": "this site (page and server)"},
    {"name": "pi_gate", "purpose": "Only on private test copies of the site: remembers that you typed their password.",
     "essential": True, "lasts": "30 days", "set_by": "this site (server, HttpOnly)", "read_by": "this site (server)"},
]
# what the page keeps in your browser's storage (not cookies: never sent with requests by themselves)
STORAGE: List[Dict] = [
    {"name": "lv:, orbit:, se:, superai: keys", "purpose": "Your layout, the supers you make and draw, your wires, saved states.",
     "essential": True, "lasts": "until you clear it or reset the app"},
    {"name": "sp_token, sp_wallet, sp_orcid", "purpose": "Your sign-in, if you sign in (sent only to this site).",
     "essential": True, "lasts": "until you sign out"},
    {"name": "pisave:pending (session)", "purpose": "Hands a saved state to the page while it reloads after a reset.",
     "essential": True, "lasts": "this tab only"},
]

# the optional things, and what each one switches
CHOICES = {"count": "c", "learn": "l", "ext": "e"}
OUTSIDE = ("llama", "mistral", "qwen", "gemini", "deepseek", "judge")

# requests that need a choice: (method, path pattern, the choice, what happens when it is off)
#   "skip"    answered as done but not done (a visit not counted, a lesson not learned): nothing breaks
#   "refuse"  403 with the reason, the page shows it
RULES = [
    ("POST", re.compile(r"^/api/visit$"), "count", "skip"),
    ("POST", re.compile(r"^/api/pien/learn$"), "learn", "skip"),
    ("POST", re.compile(r"^/api/assess(/|$)"), "ext", "refuse"),
    ("POST", re.compile(r"^/api/super/(panel|weigh)$"), "ext", "refuse"),
    ("POST", re.compile(r"^/api/assessments/[^/]+/review/llm$"), "ext", "refuse"),
]
WHY = {"count": "you chose not to have your visit counted",
       "learn": "you chose not to help PiEn learn",
       "ext": "you chose not to use outside AI providers (this uses them); change it in Privacy choices"}


def parse(value: Optional[str]) -> Optional[Dict[str, bool]]:
    """The choice in a pi_consent value, or None when there is none (or it is from an older notice)."""
    if not value:
        return None
    parts = str(value).strip().split(".")
    if not parts or parts[0] != VERSION:
        return None
    flags = {p[0]: p[1:] == "1" for p in parts[1:] if len(p) == 2 and p[1] in "01"}
    return {k: bool(flags.get(c, False)) for k, c in CHOICES.items()}


def from_request(request) -> Optional[Dict[str, bool]]:
    try:
        return parse(request.cookies.get(cookies_COOKIE))
    except Exception:                                   # noqa: BLE001 -- no cookies at all: no choice
        return None


def declined(request, what: str) -> bool:
    """True only when the visitor's cookie says no to `what` (no cookie: not declined, see the module notes)."""
    c = from_request(request)
    return c is not None and not c.get(what, False)


def rule_for(method: str, path: str):
    m = (method or "").upper()
    for rm, rx, what, how in RULES:
        if m == rm and rx.search(path or ""):
            return what, how
    return None


def outside_engine(engine: str) -> bool:
    return (engine or "").strip().lower() in OUTSIDE


def info(request) -> Dict:
    return {"version": VERSION, "cookie": cookies_COOKIE, "cookies": COOKIES, "storage": STORAGE, "choice": from_request(request)}


def cookies_install(app):
    """The server honours pi_consent: a middleware for the rules above, and GET /api/cookies."""
    from fastapi import Request
    from fastapi.responses import JSONResponse

    @app.middleware("http")
    async def _consent(request: Request, call_next):
        try:
            r = rule_for(request.method, request.url.path)
            if r and declined(request, r[0]):
                what, how = r
                if how == "skip":
                    return JSONResponse(status_code=200, content={"skipped": True, "why": WHY[what]}, headers={"Cache-Control": "no-store"})
                return JSONResponse(status_code=403, content={"detail": WHY[what], "declined": what}, headers={"Cache-Control": "no-store"})
        except Exception as e:                          # noqa: BLE001 -- never let the check itself take the site down
            logging.warning("cookies: consent check skipped: %s", e)
        return await call_next(request)

    @app.get("/api/cookies")
    def _cookies(request: Request):
        return JSONResponse(content=info(request), headers={"Cache-Control": "no-store"})


# ==============================================================================================================
# diagnostics.py (was its own module; AGPL-3.0-only)
# ==============================================================================================================
# Copyright (c) 2026 Ali Vafadar Yengejeh (Pi Tech Lab). Part of ScholarPi's open science engines: see LICENSE.
"""
Reception diagnostics — why a manuscript is not landing, and what to do.

The scoring engine answers "how rigorous is this work?". This module answers a
different and much more useful question for the person who wrote it: "given
that the work is what it is, why is nobody reading it, and what can I actually
change?"

The critical separation
-----------------------
These are NOT score inputs, and nothing here feeds back into piX. That is
deliberate and it is the whole reason this can exist at all.

ScholarPi assesses the work, not the author: venue prestige, h-index, team size and author
seniority are explicitly excluded from assessment, because they measure career
stage and field citation culture rather than the quality of the work. Letting
them influence a score would reproduce exactly the bias responsible assessment exists to
dismantle.

But they *do* influence reception, and a researcher pretending otherwise is
worse off than one who knows. So this module reports them honestly as
**visibility factors**, clearly labelled as such, while the score stays blind
to them. "Your paper is good and structurally invisible" is a coherent and
common finding, and it is the one most worth telling someone.

Determinism
-----------
Every finding is derived from signals the assessment already produced. No LLM
call, so this costs nothing to run, never hallucinates a citation count, and
returns the same report for the same inputs — which matters when the report is
telling someone their coauthors are a problem.
"""

diagnostics_logger = logging.getLogger(__name__)

# Criterion titles, used to name the weakest dimensions in plain language.
CRITERION_LABELS = {
    "C1": "semantic originality",
    "C2": "MDAR methodological rigor",
    "C3": "citation entropy (breadth of literature engaged)",
    "C4": "open infrastructure (data and code availability)",
    "C5": "containerized execution (reproducibility)",
    "C6": "citation polarity (how the work positions itself)",
    "C7": "empirical density",
    "C8": "future actionability and FAIR compliance",
}

# Severity ranks, used to order findings so the most consequential lead.
CRITICAL, MAJOR, MINOR, POSITIVE = "critical", "major", "minor", "positive"
_SEVERITY_ORDER = {CRITICAL: 0, MAJOR: 1, MINOR: 2, POSITIVE: 3}

PREPRINT_HOSTS = (
    "arxiv", "biorxiv", "medrxiv", "chemrxiv", "psyarxiv", "ssrn", "preprints.org",
    "research square", "researchsquare", "osf", "hal", "zenodo", "techrxiv",
)


def _finding(severity, title, reality, action, kind="visibility"):
    """One diagnostic item.

    ``reality`` states what is true without softening it; ``action`` must be
    something the researcher can actually do. A finding with no actionable
    response is discouragement, not diagnosis, so every entry carries both.
    """
    return {"severity": severity, "title": title, "reality": reality,
            "action": action, "kind": kind}


def _looks_like_preprint(journal: str) -> bool:
    j = (journal or "").strip().lower()
    if not j:
        return False
    return any(host in j for host in PREPRINT_HOSTS)


def _count_authors(author_name: str) -> int:
    """Best-effort author count from the extracted byline."""
    if not author_name:
        return 0
    cleaned = author_name.replace(" and ", ",").replace(";", ",")
    parts = [p.strip() for p in cleaned.split(",") if p.strip()]
    # A byline of "Surname, Given" for one person splits into two fragments.
    # Treat very short fragments as name parts rather than separate authors.
    real = [p for p in parts if len(p) > 2]
    return len(real)


def analyse_venue(payload: Dict) -> List[Dict]:
    findings = []
    ref_audit = payload.get("reference_audit") or {}
    biblio = ref_audit.get("bibliographic") or {}
    journal = (biblio.get("journal") or "").strip()

    if not journal:
        findings.append(_finding(
            MAJOR, "No publication venue detected",
            "No journal or conference could be identified for this manuscript. If it is "
            "unpublished or sitting on a personal page, it is effectively invisible: it will "
            "not be indexed, will not appear in literature searches, and cannot accumulate "
            "citations no matter how good it is.",
            "Deposit it on a recognised preprint server for your field to get a DOI and make it "
            "discoverable immediately, then submit to a peer-reviewed venue in parallel."))
    elif _looks_like_preprint(journal):
        findings.append(_finding(
            MINOR, f"Preprint only ({journal})",
            f"This is hosted on {journal} and shows no sign of peer review. Preprints are "
            f"indexed and citable, so this is far better than nothing — but many hiring "
            f"panels, funders and reviewers discount unreviewed work, and some fields ignore "
            f"preprints almost entirely.",
            "Submit to a peer-reviewed venue. The preprint keeps priority on the idea while "
            "review is under way, so there is no cost to doing both."))
    return findings


def analyse_authorship(payload: Dict) -> List[Dict]:
    findings = []
    author_count = _count_authors(payload.get("author_name", ""))
    metrics = payload.get("author_metrics") or {}

    if author_count == 1:
        findings.append(_finding(
            MAJOR, "Single-author paper",
            "This has one author. Single-author papers are cited measurably less in most "
            "fields — not because they are worse, but because each additional author brings "
            "their own network, institution and reading audience. One author means one "
            "network doing all the distribution.",
            "Collaborate. A coauthor in an adjacent subfield roughly doubles the paper's "
            "natural readership and usually strengthens the methods section as well."))
    elif 0 < author_count <= 2:
        findings.append(_finding(
            MINOR, "Very small author team",
            f"{author_count} authors. Small teams reach fewer readers on publication and tend "
            f"to draw a narrower range of methodological expertise.",
            "Consider bringing in a collaborator with complementary methods for the next "
            "paper in this line."))

    if metrics.get("resolved"):
        h = metrics.get("h_index")
        works = metrics.get("works_count")
        if isinstance(h, int) and h <= 3 and isinstance(works, int) and works <= 5:
            findings.append(_finding(
                MINOR, "Early-career author profile",
                f"The lead author resolves to an h-index of {h} across {works} indexed works. "
                f"This says nothing about the quality of this paper, but it does mean the work "
                f"arrives without an established readership — early-career papers rely far more "
                f"on venue, topic timing and coauthor networks to get seen.",
                "Prioritise visibility you control: a clear preprint, an accessible thread or "
                "summary, conference presentation, and a coauthor with an existing audience."))
        if not metrics.get("affiliation"):
            findings.append(_finding(
                MINOR, "No institutional affiliation resolved",
                "No affiliation could be resolved for the lead author. Unaffiliated work is "
                "systematically discounted by reviewers and is harder for readers to place, "
                "fairly or not.",
                "Ensure your affiliation is stated on the manuscript and correct in your ORCID "
                "and OpenAlex records — this is often a metadata problem, not a real one."))
    else:
        findings.append(_finding(
            MAJOR, "Author not discoverable in the literature graph",
            "The lead author could not be resolved in OpenAlex. That usually means an "
            "inconsistent name form across publications, or no ORCID linkage — so citations "
            "and works are being split across several partial identities instead of "
            "accumulating against one.",
            "Register an ORCID, attach it to every publication, and use one consistent name "
            "form. This is the single highest-leverage fix here and it costs an afternoon."))
    return findings


def analyse_rigor(payload: Dict) -> List[Dict]:
    """The findings that *are* about the work, drawn from the scored criteria."""
    findings = []
    criteria = payload.get("criteria_detail") or []
    scored = [c for c in criteria if isinstance(c.get("score"), (int, float))]
    if not scored:
        return findings

    weakest = sorted(scored, key=lambda c: c["score"])[:3]
    for c in weakest:
        if c["score"] >= 50:
            continue
        label = CRITERION_LABELS.get(c.get("id"), c.get("title") or c.get("id"))
        findings.append(_finding(
            MAJOR if c["score"] < 30 else MINOR,
            f"Weak on {label}",
            f"This scored {c['score']:.0f}/100 on {label} — one of its three weakest "
            f"dimensions. Unlike venue or team size, this is a property of the work itself, "
            f"and it is what reviewers will catch.",
            _remedy_for(c.get("id")),
            kind="quality"))

    repro = payload.get("repro_score")
    if isinstance(repro, (int, float)) and repro < 40:
        findings.append(_finding(
            MAJOR, "Low reproducibility signal",
            f"Reproducibility scored {repro:.0f}/100. Work that cannot be re-run is cited less "
            f"and is increasingly desk-rejected outright at reproducibility-conscious venues.",
            "Publish data and analysis code in a public repository with a DOI, and state "
            "software versions. This is usually a day of work and it moves several criteria "
            "at once.", kind="quality"))
    return findings


def _remedy_for(criterion_id: str) -> str:
    return {
        "C1": "Sharpen what is genuinely new here. State the specific claim that did not exist "
              "before this paper, in one sentence, in the abstract.",
        "C2": "Report methods against the MDAR framework — materials, design, analysis, "
              "reporting. Most losses here are omissions, not flaws.",
        "C3": "Engage a wider literature. Narrow citation ranges read as unaware of the field "
              "and reviewers notice quickly.",
        "C4": "Deposit data and code in a public repository and cite them with a DOI.",
        "C5": "Provide a container or environment specification so the analysis can be re-run.",
        "C6": "Position the work explicitly against the literature it disagrees with, rather "
              "than only citing what supports it.",
        "C7": "Strengthen the empirical basis — more data, clearer effect sizes, or explicit "
              "acknowledgement of what the evidence cannot support.",
        "C8": "Make outputs FAIR: findable, accessible, interoperable, reusable.",
    }.get(criterion_id, "Address this dimension directly in the next revision.")


def analyse_engagement(payload: Dict) -> List[Dict]:
    findings = []
    ref_audit = payload.get("reference_audit") or {}
    summary = ref_audit.get("summary") or {}
    total = summary.get("total")
    if isinstance(total, int) and 0 < total < 15:
        findings.append(_finding(
            MINOR, "Thin reference list",
            f"Only {total} references were found. Sparse bibliographies signal limited "
            f"engagement with the field, and they also reduce reciprocal citation — the "
            f"authors you cite are the ones most likely to read and cite you back.",
            "Engage the recent literature in your subfield properly, particularly work that "
            "complicates your result."))
    return findings


def diagnostics_build_report(payload: Dict, profile: Optional[Dict] = None) -> Dict:
    """The full reception diagnostic for one assessed manuscript.

    ``profile`` is the researcher's stated field and goal, used only to frame
    the summary — it never changes the findings, so the report cannot be
    talked into being kinder by describing yourself differently.
    """
    if not isinstance(payload, dict):
        return {"available": False, "reason": "No assessment data available."}

    findings: List[Dict] = []
    for analyser in (analyse_venue, analyse_authorship, analyse_rigor, analyse_engagement):
        try:
            findings.extend(analyser(payload) or [])
        except Exception as e:                      # one bad signal must not kill the report
            diagnostics_logger.warning("Diagnostic %s failed: %s", analyser.__name__, e)

    findings.sort(key=lambda f: _SEVERITY_ORDER.get(f["severity"], 9))

    score = payload.get("score")
    score_val = float(score) if isinstance(score, (int, float)) else None
    quality = [f for f in findings if f["kind"] == "quality"]
    visibility = [f for f in findings if f["kind"] == "visibility"]

    return {
        "available": True,
        "score": score_val,
        "headline": _headline(score_val, quality, visibility),
        "verdict": _verdict(quality, visibility),
        "findings": findings,
        "quality_count": len(quality),
        "visibility_count": len(visibility),
        "profile_context": _profile_context(profile),
        "disclaimer": (
            "Visibility factors — venue, team size, author profile — are reported here because "
            "they affect how work is received. They are deliberately excluded from the piX "
            "score itself: they reflect career stage and field culture, "
            "not the quality of this manuscript."
        ),
    }


def _headline(score, quality, visibility) -> str:
    if score is None:
        return "Assessment incomplete — diagnostic is partial."
    if score >= 70 and not quality and visibility:
        return ("Strong work with a distribution problem. The manuscript holds up; what is "
                "limiting it is how and where it reaches people.")
    if score >= 70:
        return "Strong work, and nothing structural is holding it back."
    if score >= 45 and visibility and not quality:
        return ("Reasonable work whose main obstacle is visibility rather than substance.")
    if quality and visibility:
        return ("Two separate problems: specific weaknesses in the work, and structural "
                "barriers to it being read. They need different fixes.")
    if quality:
        return "The main obstacles are in the manuscript itself, and they are addressable."
    return "No major structural obstacles detected."


def _verdict(quality, visibility) -> str:
    if not quality and not visibility:
        return "clear"
    if quality and visibility:
        return "both"
    return "quality" if quality else "visibility"


def recommend_papers(papers: List[Dict], limit: int = 4,
                     user_fields: Optional[List[str]] = None) -> Dict:
    """riB's picks: which assessed papers to read, which to treat with care.

    Grounded entirely in the per-criterion scores the engine already produced.
    Each verdict names the specific criteria driving it, because "recommended"
    without a reason is just a ranking, and a researcher cannot act on a rank.

    The negative list is framed as *read critically*, not *ignore*. A low piX
    means weak methodological reporting, not that the findings are wrong, and
    presenting it as a blacklist would be both unfair to the authors and
    misleading about what the score measures.
    """
    if not papers:
        return {"available": False, "reason": "No assessed papers to draw on yet.",
                "recommended": [], "caution": [], "unrelated": []}

    def strengths(criteria, high=True):
        scored = [(k, v) for k, v in (criteria or {}).items() if isinstance(v, (int, float))]
        if not scored:
            return []
        scored.sort(key=lambda kv: kv[1], reverse=high)
        picked = [k for k, v in scored[:2] if (v >= 60 if high else v < 45)]
        return [CRITERION_LABELS.get(k.upper(), k) for k in picked]

    # Papers sharing no field with the profile are set aside rather than ranked
    # against it. A rubric score says how well work is reported; it says nothing
    # about whether the work is relevant to the reader. Mixing an unrelated
    # paper into "worth reading" presents a relevance judgement the engine never
    # made — and one it cannot make from scores alone.
    wanted = {f.strip().lower() for f in (user_fields or []) if f and f.strip()}
    unrelated_src = []
    if wanted:
        related = []
        for p in papers:
            fields = {str(f).strip().lower() for f in (p.get("fields") or []) if str(f).strip()}
            # An unclassified paper is not "unrelated" — it is unknown, and
            # filing it under a heading that says otherwise would be a claim.
            (related if (not fields or fields & wanted) else unrelated_src).append(p)
        papers = related

    ranked = sorted(papers, key=lambda p: p["score"], reverse=True)

    recommended = []
    for p in ranked[:limit]:
        if p["score"] < 55:
            break                      # nothing above the bar; don't pad the list
        good = strengths(p["criteria"], high=True)
        recommended.append({
            "eval_hash": p["eval_hash"], "title": p["title"],
            "author_name": p["author_name"], "score": p["score"],
            "fields": p["fields"],
            "why": ("Strong on " + " and ".join(good) + ".") if good
                   else "Scores consistently well across the rubric.",
        })

    caution = []
    for p in reversed(ranked):
        if len(caution) >= limit or p["score"] >= 45:
            break
        weak = strengths(p["criteria"], high=False)
        caution.append({
            "eval_hash": p["eval_hash"], "title": p["title"],
            "author_name": p["author_name"], "score": p["score"],
            "fields": p["fields"],
            "why": ("Weak on " + " and ".join(weak) + ".") if weak
                   else "Scores below the rubric threshold across several dimensions.",
        })

    unrelated = [{
        "eval_hash": p["eval_hash"], "title": p["title"],
        "author_name": p["author_name"], "score": p["score"], "fields": p["fields"],
        "why": ("Outside the fields on your profile"
                + (" (" + ", ".join(p["fields"][:3]) + ")" if p["fields"] else "")
                + ". riB cannot judge it against your work."),
    } for p in sorted(unrelated_src, key=lambda p: p["score"], reverse=True)[:limit]]

    return {
        "available": bool(recommended or caution or unrelated),
        "recommended": recommended,
        "caution": caution,
        "unrelated": unrelated,
        "considered": len(papers) + len(unrelated_src),
        "note": (
            "Ranked by riB's rubric scores, which measure how well work is reported and "
            "reproducible — not whether its conclusions are correct. A low score means the "
            "methods are hard to verify, so read critically rather than dismiss."
        ),
    }


def _profile_context(profile: Optional[Dict]) -> str:
    if not profile:
        return ""
    field = (profile.get("field") or "").strip()
    goal = (profile.get("goal") or "").strip()
    if field and goal:
        return f"Framed against your stated field ({field}) and goal: {goal}"
    if field:
        return f"Framed against your stated field: {field}"
    return ""


# ==============================================================================================================
# gate.py (was its own module; LicenseRef-PiTechLab-Proprietary)
# ==============================================================================================================
"""gate.py -- a password on the whole site, for the experimental copies.

Set SITE_PASSWORD on a deployment and nothing is served until the visitor has
typed it once: every page and API call answers with a small password page
(or 401 for an API caller) until a signed cookie says they have. The cookie
is an HMAC of the password with the deployment's secret, so changing the
password logs everyone out; it carries no password itself. Nothing is written
and nothing is logged about who tried what.

Unset (the default, and always on production), the gate does nothing.

    POST /api/gate   {"password": "..."}   -> 204 + cookie, or 401

Let through without the cookie: the health check Railway polls, robots.txt
and the gate endpoint itself. Everything else, static files included, waits
behind the password: a hidden site should not leak its scripts either.
"""



gate_COOKIE = "pi_gate"
MAX_AGE = 60 * 60 * 24 * 30          # a month, then the password is asked again
OPEN = ("/api/gate", "/api/health", "/robots.txt", "/icon.svg", "/manifest.webmanifest")
OPEN_PREFIXES = ("/app/", "/fonts/")   # the front end itself, which draws the password field


def password() -> str:
    return (os.getenv("SITE_PASSWORD") or "").strip()


def enabled() -> bool:
    return bool(password())


def token(pw: str, secret: str) -> str:
    """The cookie value for a password: an HMAC, never the password."""
    return hmac.new((secret or pw).encode(), ("gate:" + pw).encode(), hashlib.sha256).hexdigest()


def passes(request: Request, secret: str) -> bool:
    pw = password()
    if not pw:
        return True
    if request.url.path in OPEN or request.url.path.startswith(OPEN_PREFIXES):
        return True
    got = request.cookies.get(gate_COOKIE) or ""
    return bool(got) and hmac.compare_digest(got, token(pw, secret))


def check(given: str, secret: str) -> Optional[str]:
    """The cookie to set for a correct password, else None."""
    pw = password()
    if not pw or not hmac.compare_digest((given or "").strip().encode(), pw.encode()):
        return None
    return token(pw, secret)


def set_cookie(response: Response, value: str, secure: bool):
    response.set_cookie(gate_COOKIE, value, max_age=MAX_AGE, httponly=True, samesite="lax", secure=secure, path="/")


def wants_html(request: Request) -> bool:
    return request.method == "GET" and "text/html" in (request.headers.get("accept") or "")


def page(msg: str = "") -> HTMLResponse:
    """The site itself, answered 401: the Rust app sees the deployment is private and asks for the password."""
    try:
        doc = rust_loader()
    except OSError:
        doc = "This deployment is private."
    return HTMLResponse(doc, status_code=401, headers={"Cache-Control": "no-store", "X-Robots-Tag": "noindex, nofollow"})


def gate_install(app, secret_of: Callable[[], str]):
    """Mount the gate on a FastAPI app. secret_of() gives the signing secret (SESSION_SECRET)."""

    @app.middleware("http")
    async def _gate(request: Request, call_next):
        if passes(request, secret_of()):
            return await call_next(request)
        if wants_html(request):
            return page()
        return JSONResponse(status_code=401, content={"detail": "This deployment is private."}, headers={"Cache-Control": "no-store"})

    @app.post("/api/gate", status_code=204)
    async def _enter(request: Request):
        try:
            body = await request.json()
        except Exception:                                   # noqa: BLE001
            body = {}
        value = check(str((body or {}).get("password", "")), secret_of())
        if not value:
            return JSONResponse(status_code=401, content={"detail": "That is not it."})
        response = Response(status_code=204)
        set_cookie(response, value, secure=request.url.scheme == "https" or request.headers.get("x-forwarded-proto") == "https")
        return response


# ==============================================================================================================
# idle_worker.py (was its own module; LicenseRef-PiTechLab-Proprietary)
# ==============================================================================================================
"""Idle-time corpus growth.

When nobody is using the site, ScholarPi assesses open-access papers on its
own: it picks a live research topic, asks OpenAlex for open-access works on it,
retrieves one, and runs it through the ordinary assessment pipeline. The Map of
Science and the leaderboards therefore keep growing on a quiet deployment
instead of sitting at whatever the last visitor happened to upload.

Four constraints shape everything here, and each of them exists because the
obvious implementation gets it wrong:

  1. NOBODY IS CHARGED. An auto-assessment is work no user requested, so no
     user's piQ balance may move for it. `charge_fees` is off on this path.
     Author emission is untouched — the paper still earns what it qualifies
     for, because the paper's merit does not depend on who submitted it.

  2. IT ONLY RUNS WHEN THE SITE IS IDLE. "Idle" is measured from real request
     activity, not from a clock. Background work that competes with a live
     visitor for the same rate-limited provider quota makes the site slower for
     the one person actually using it.

  3. IT IS CAPPED, AND THE CAP IS DAILY. Providers rate-limit, and a runaway
     loop against a free tier is both expensive and self-defeating. The counter
     resets on the date, so a restart cannot be used to buy a fresh budget
     within the same day.

  4. IT NEVER RAISES INTO THE SERVER. Every step is wrapped. A failure here
     costs one skipped paper and a log line, never a request served to a
     person.

On by default on the hosted deployments (see config.ENABLE_IDLE_ASSESSMENTS),
off elsewhere unless ENABLE_IDLE_ASSESSMENTS is set, so a clone of the public
repository never starts spending on provider calls because it was left running.

What counts as "busy" (note_request): somebody arriving on the site, or any
request that uses the model providers (assessing, SciM chat, reviews, defence
strategies, rescoring), for as long as it is in flight. Background polling an
open tab does every few seconds (layout sync, PiEN, status panels) does not
count: it competes for nothing, and counting it meant a single tab left open
anywhere kept the site "busy" forever, so nothing was ever assessed.
"""




# ---------------------------------------------------------------------------
# Shared state
# ---------------------------------------------------------------------------
_STATE = {
    "day": "",
    "assessed_today": 0,
    "attempted_today": 0,
    "last_request_at": 0.0,
    "last_run_at": 0.0,
    "last_title": "",
    "last_error": "",
    "running": False,
    "seen": set(),          # DOIs tried this process, so a dud is not retried
}
_LOCK = threading.Lock()


def _idle_worker_today() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%d")


def _roll_day():
    """Reset the daily counters when the date changes. Caller holds the lock."""
    today = _idle_worker_today()
    if _STATE["day"] != today:
        _STATE["day"] = today
        _STATE["assessed_today"] = 0
        _STATE["attempted_today"] = 0
        _STATE["seen"] = set()


# Requests that mean a person is here and may need the model providers.
_BUSY_PREFIXES = ("/api/assess/", "/api/scilem/chat", "/api/defense-strategy",
                  "/api/reviews/rebut", "/api/admin/rescore")
_INFLIGHT = {"n": 0}


def is_busy_request(path: str = "", method: str = "GET") -> bool:
    """Does this request mean the site is in use (see the module docstring)?"""
    path = path or ""
    if path in ("/", "/index.html"):
        return True
    if path.startswith(_BUSY_PREFIXES):
        return True
    if method.upper() == "POST" and path.startswith("/api/assessments/") and path.endswith("/review/llm"):
        return True
    return False


def note_request(path: str = None, method: str = "GET"):
    """Record that a real request was served. Called from the HTTP middleware.

    With no path (older callers), every request counts. With a path, only the
    ones that mean somebody is using the site (is_busy_request) do. A timer
    alone would happily run a batch of provider calls while somebody is waiting
    on an assessment, competing for the same rate-limited quota as the person
    who actually asked for something.
    """
    if path is None or is_busy_request(path, method):
        _STATE["last_request_at"] = time.time()


def begin(path: str, method: str = "GET") -> bool:
    """Mark a provider-using request as in flight; returns whether it counted."""
    if path.startswith(_BUSY_PREFIXES) or (method.upper() == "POST" and path.endswith("/review/llm")):
        with _LOCK:
            _INFLIGHT["n"] += 1
        return True
    return False


def end():
    with _LOCK:
        _INFLIGHT["n"] = max(0, _INFLIGHT["n"] - 1)
    _STATE["last_request_at"] = time.time()


def idle_seconds() -> float:
    last = _STATE["last_request_at"]
    if not last:
        # Nothing has been served since start-up. Treat that as idle from the
        # moment the process began rather than as infinitely idle, so a fresh
        # deployment does not immediately fire a batch during boot.
        return 0.0
    return max(0.0, time.time() - last)


def activity() -> dict:
    """What the server is processing right now, for the π mark and counter:
    provider-using requests in flight (people's assessments, chats, reviews)
    and whether the idle worker is assessing a paper."""
    n = _INFLIGHT["n"]
    working = bool(_STATE["running"])
    total = n + (1 if working else 0)
    return {"in_flight": n, "idle_working": working,
            "level": "busy" if total >= 2 else "working" if total == 1 else "quiet"}


def public_status() -> dict:
    """What anyone may see: whether the site works while idle, and what it did
    today. No errors, timings or thresholds, which are the owner's business."""
    with _LOCK:
        _roll_day()
        return {
            "enabled": bool(ENABLE_IDLE_ASSESSMENTS),
            "assessed_today": _STATE["assessed_today"],
            "daily_cap": IDLE_MAX_PER_DAY,
            "last_title": _STATE["last_title"],
            "last_run_at": _STATE["last_run_at"],
            "working_now": _STATE["running"],
        }


def idle_worker_status() -> dict:
    """Everything the owner panel needs, including when it is switched off."""
    with _LOCK:
        _roll_day()
        return {
            "enabled": bool(ENABLE_IDLE_ASSESSMENTS),
            "running": _STATE["running"],
            "assessed_today": _STATE["assessed_today"],
            "attempted_today": _STATE["attempted_today"],
            "daily_cap": IDLE_MAX_PER_DAY,
            "remaining_today": max(0, IDLE_MAX_PER_DAY - _STATE["assessed_today"]),
            "idle_seconds": round(idle_seconds()),
            "in_flight": _INFLIGHT["n"],
            "idle_threshold": IDLE_AFTER_SECONDS,
            "site_is_idle": idle_seconds() >= IDLE_AFTER_SECONDS,
            "last_title": _STATE["last_title"],
            "last_run_at": _STATE["last_run_at"],
            "last_error": _STATE["last_error"],
            # Stated explicitly because "the site assessed something while I was
            # away" invites exactly one question, and it should be answered
            # before it is asked.
            "funding": ("Assessed at no cost to any account. Idle assessments are not "
                        "charged to a user's piQ balance."),
        }


def _may_run() -> bool:
    with _LOCK:
        _roll_day()
        if not ENABLE_IDLE_ASSESSMENTS:
            return False
        if _STATE["running"]:
            return False
        if _STATE["assessed_today"] >= IDLE_MAX_PER_DAY:
            return False
        # Attempts are capped separately and more loosely. A run of papers that
        # cannot be retrieved must not be able to spin indefinitely against
        # OpenAlex just because none of them reached the assessment stage.
        if _STATE["attempted_today"] >= IDLE_MAX_PER_DAY * 4:
            return False
        if idle_seconds() < IDLE_AFTER_SECONDS:
            return False
        if _INFLIGHT["n"] > 0:          # somebody's assessment is still running
            return False
        _STATE["running"] = True
        return True


# ---------------------------------------------------------------------------
# One unit of work
# ---------------------------------------------------------------------------
def _pick_candidate():
    """Choose one open-access work that this process has not already tried.

    Imports are deferred to call time, not module scope: api imports this
    module, so importing api from the top of this file would be circular.
    """
    # These live in two different modules and it matters which: topic discovery
    # is a scientometrics concern, retrieval is an integrations one. Importing
    # both from `integrations` raised ImportError on the first idle tick — the
    # loop caught it and logged, so the worker degraded to doing nothing at all
    # rather than failing loudly at start-up.
    pass
    pass

    topics = []
    try:
        topics = (fetch_active_research_topics(limit=10) or {}).get("topics") or []
    except Exception as e:                                       # noqa: BLE001
        logging.warning("Idle worker could not fetch topics: %s", e)
    if not topics:
        pass
        topics = list(HOT_TOPICS)
    if not topics:
        return None

    topic = random.choice(topics)
    topic = topic.get("name") if isinstance(topic, dict) else str(topic)
    if not topic:
        return None

    try:
        results = search_open_access_works(topic, limit=25) or []
    except Exception as e:                                       # noqa: BLE001
        logging.warning("Idle worker search failed for %r: %s", topic, e)
        return None

    random.shuffle(results)
    for r in results:
        doi = (r.get("doi") or "").strip()
        if not doi or doi in _STATE["seen"]:
            continue
        return {"topic": topic, "doi": doi,
                "title": (r.get("title") or "").strip(),
                "pdf_url": (r.get("pdf_url") or "").strip(),
                "pdf_candidates": r.get("pdf_candidates") or []}
    return None


def run_once() -> dict:
    """Assess at most one paper. Safe to call from a thread or a scheduler."""
    if not _may_run():
        return {"ran": False, "reason": "not eligible"}

    try:
        pass
        pass
        pass

        candidate = _pick_candidate()
        if not candidate:
            return {"ran": False, "reason": "no candidate found"}

        with _LOCK:
            _STATE["attempted_today"] += 1
            _STATE["seen"].add(candidate["doi"])

        pdf_bytes, attempts = retrieve_manuscript_bytes(
            doi=candidate["doi"], pdf_url=candidate["pdf_url"],
            candidates=candidate["pdf_candidates"])
        if not pdf_bytes:
            return {"ran": False, "reason": "could not retrieve", "doi": candidate["doi"]}

        store_paper(pdf_bytes)
        fname = f"Idle_{candidate['doi'].replace('/', '_')[:60]}.pdf"

        # user_id is the platform itself, never a person. An idle assessment
        # has no submitter, so attributing one would put a paper in somebody's
        # history that they did not submit — and, worse, could make them look
        # like its curator.
        res = process_single_pdf(pdf_bytes, fname, "", "ScholarPi (idle)", "",
                                 provided_doi=candidate["doi"])
        if not res:
            return {"ran": False, "reason": "assessment returned nothing"}

        item = build_result_payload(res, fname)

        # A merged duplicate is not growth. It cost a retrieval, not an
        # assessment, so it does not consume the daily budget — otherwise a
        # corpus that already holds the popular papers on a topic would burn
        # its whole allowance rediscovering them.
        if item.get("duplicate"):
            return {"ran": False, "reason": "already in the corpus",
                    "doi": candidate["doi"], "eval_hash": item.get("eval_hash")}

        with _LOCK:
            _STATE["assessed_today"] += 1
            _STATE["last_title"] = item.get("title") or candidate["title"]
            _STATE["last_run_at"] = time.time()
            _STATE["last_error"] = ""

        add_log(f"Idle assessment: {(item.get('title') or candidate['doi'])[:70]} "
                f"(topic: {candidate['topic'][:40]}) — no account was charged.")
        return {"ran": True, "title": item.get("title"), "doi": candidate["doi"],
                "eval_hash": item.get("eval_hash"), "score": item.get("score")}

    except Exception as e:                                       # noqa: BLE001
        logging.exception("Idle assessment failed")
        with _LOCK:
            _STATE["last_error"] = str(e)[:300]
        return {"ran": False, "reason": "error", "error": str(e)[:200]}
    finally:
        with _LOCK:
            _STATE["running"] = False


# ---------------------------------------------------------------------------
# Scheduler
# ---------------------------------------------------------------------------
def _loop():
    # A first wait before anything happens, so a restart during a busy period
    # does not immediately treat "no requests yet this process" as quiet.
    time.sleep(max(10, IDLE_AFTER_SECONDS))
    while True:
        try:
            run_once()
        except Exception:                                        # noqa: BLE001
            logging.exception("Idle worker loop error")
        # Jittered, so several instances behind one load balancer do not all
        # wake at the same second and hit the same provider together.
        # Never less than 10 s: IDLE_POLL_SECONDS=0 would otherwise spin the
        # loop flat out and take a whole CPU core from the site.
        time.sleep(max(10, IDLE_POLL_SECONDS) * (0.75 + random.random() * 0.5))


def start():
    """Start the background loop if the deployment has opted in."""
    if not ENABLE_IDLE_ASSESSMENTS:
        logging.info("Idle assessments are disabled (ENABLE_IDLE_ASSESSMENTS is not set).")
        return False
    t = threading.Thread(target=_loop, name="idle-assessments", daemon=True)
    t.start()
    logging.info("Idle assessments enabled: up to %d papers/day after %ds of quiet. "
                 "No account is charged for them.",
                 IDLE_MAX_PER_DAY, IDLE_AFTER_SECONDS)
    return True


# ==============================================================================================================
# paper_store.py (was its own module; LicenseRef-PiTechLab-Proprietary)
# ==============================================================================================================
"""Retention of uploaded manuscript files.

The assessment pipeline previously read an upload into memory, scored it and
discarded the bytes — only the filename string survived. That made every
"published" badge a pointer to an assessment of a document nobody could read,
which is a weak form of publication: a reader could see the verdict but never
the thing it was a verdict about.

Files are stored here, keyed by the SHA-256 of their own bytes. That key is not
an arbitrary choice — `brain.py` derives `eval_hash` the same way, so the file
for an assessment is addressable from the assessment's own identifier with no
extra column, no join, and no possibility of the two drifting apart. Two
identical uploads collapse to one stored file for the same reason.

ACCESS IS NOT DECIDED HERE. This module stores and retrieves; the API decides
who may read. The rule the API enforces is that a file becomes publicly
readable only once its author has published the assessment, and stops being
readable the moment they withdraw it — so retention never silently becomes
publication.

Copyright note, recorded where the code is rather than only in a UI string: a
manuscript's author is not always free to redistribute the typeset version a
publisher produced. Publishing here asks the author to attest that they hold
that right; the platform cannot verify it and does not claim to.
"""


PAPER_STORE_DIR = os.path.join(BASE_DIR, "paper_store")
os.makedirs(PAPER_STORE_DIR, exist_ok=True)

# A stored file is only ever useful alongside its assessment, and an assessment
# is refused above this size upstream, so anything larger here is a bug or an
# abuse attempt rather than a large paper.
MAX_STORED_BYTES = 40 * 1024 * 1024


def _env_bytes(name: str, default: int) -> int:
    try:
        return max(0, int(os.environ.get(name, default)))
    except (TypeError, ValueError):
        return default


# Total budget for the whole store. Without one, retained manuscripts grew until
# they filled the production volume — and a full volume stops the database too.
# Override with PAPER_STORE_MAX_TOTAL_BYTES; 0 disables the cap.
MAX_TOTAL_BYTES = _env_bytes("PAPER_STORE_MAX_TOTAL_BYTES", 2 * 1024 * 1024 * 1024)

# The API registers a callable returning the hashes that still have an
# assessment. Eviction removes orphans first, and only then the oldest files.
_known_hashes: Optional[Callable[[], Iterable[str]]] = None


def set_known_hashes_provider(fn: Optional[Callable[[], Iterable[str]]]) -> None:
    global _known_hashes
    _known_hashes = fn


def _stored_files():
    """(name, size, mtime) for every stored PDF."""
    out = []
    try:
        names = os.listdir(PAPER_STORE_DIR)
    except OSError:
        return out
    for name in names:
        if not name.endswith(".pdf"):
            continue
        try:
            st = os.stat(os.path.join(PAPER_STORE_DIR, name))
        except OSError:
            continue
        out.append((name, st.st_size, st.st_mtime))
    return out


def total_bytes() -> int:
    return sum(size for _, size, _ in _stored_files())


def _make_room(incoming: int) -> int:
    """Evict until `incoming` more bytes fit under MAX_TOTAL_BYTES.

    Orphans (no assessment) go first, then the oldest files. Returns the number
    of files removed.
    """
    if not MAX_TOTAL_BYTES:
        return 0
    files = _stored_files()
    used = sum(size for _, size, _ in files)
    if used + incoming <= MAX_TOTAL_BYTES:
        return 0
    known = set()
    if _known_hashes:
        try:
            known = set(_known_hashes())
        except Exception as e:                                   # noqa: BLE001
            logging.warning("Could not list known assessments for eviction: %s", e)
    files.sort(key=lambda f: (f[0][:-4] in known, f[2], f[0]))
    removed = 0
    for name, size, _ in files:
        if used + incoming <= MAX_TOTAL_BYTES:
            break
        try:
            os.remove(os.path.join(PAPER_STORE_DIR, name))
        except OSError as e:
            logging.warning("Could not evict stored manuscript %s: %s", name, e)
            continue
        used -= size
        removed += 1
        logging.warning("Paper store over its %d-byte cap: evicted %s (%s)",
                        MAX_TOTAL_BYTES, name[:12],
                        "assessed" if name[:-4] in known else "orphan")
    return removed


def _path_for(eval_hash: str) -> Optional[str]:
    """Filesystem path for a hash, or None if the hash is not a plausible one.

    The hash reaches this module from a URL path segment. Validating its shape
    is what stops "../../etc/passwd" from being treated as an identifier —
    os.path.join would happily build that path otherwise.
    """
    h = (eval_hash or "").strip().lower()
    if len(h) != 64 or not all(c in "0123456789abcdef" for c in h):
        return None
    return os.path.join(PAPER_STORE_DIR, f"{h}.pdf")


def store_paper(raw: bytes) -> str:
    """Persist an uploaded manuscript. Returns its hash, or "" if not stored.

    Never raises: a failure to retain the file must not fail the assessment the
    user is paying for. It degrades to the previous behaviour — the paper is
    assessed, and there is simply no file to serve later.
    """
    if not raw or len(raw) > MAX_STORED_BYTES:
        return ""
    digest = hashlib.sha256(raw).hexdigest()
    path = _path_for(digest)
    if not path:
        return ""
    if os.path.exists(path):
        return digest              # identical upload; one copy is enough
    if MAX_TOTAL_BYTES and len(raw) > MAX_TOTAL_BYTES:
        return ""
    _make_room(len(raw))
    try:
        # Written to a temporary name and moved into place, so a crash midway
        # cannot leave a truncated PDF that looks like a complete one.
        tmp = path + ".part"
        with open(tmp, "wb") as fh:
            fh.write(raw)
        os.replace(tmp, path)
        return digest
    except OSError as e:
        logging.warning("Could not store manuscript %s: %s", digest[:12], e)
        return ""


def paper_path(eval_hash: str) -> Optional[str]:
    """Path to a stored manuscript, or None when there is no file for it."""
    path = _path_for(eval_hash)
    if path and os.path.exists(path):
        return path
    return None


def has_paper(eval_hash: str) -> bool:
    return paper_path(eval_hash) is not None


def delete_paper(eval_hash: str) -> bool:
    """Remove a stored manuscript.

    Called when an assessment is withdrawn from the corpus. The ledger block is
    deliberately immutable, but the manuscript is not part of the ledger — a
    researcher who removes their paper expects the file to go with it, and
    keeping it would make "remove" mean something narrower than it says.
    """
    path = paper_path(eval_hash)
    if not path:
        return False
    try:
        os.remove(path)
        return True
    except OSError as e:
        logging.warning("Could not delete manuscript %s: %s", str(eval_hash)[:12], e)
        return False


def count_papers() -> int:
    """How many manuscripts are on disk.

    Used by the owner's reset preview, where the number of files is not
    derivable from the database: an assessment can exist without a stored file
    (papers submitted by DOI), and an orphaned file can outlive its row.
    """
    try:
        return sum(1 for name in os.listdir(PAPER_STORE_DIR) if name.endswith(".pdf"))
    except OSError:
        return 0


def clear_all() -> int:
    """Delete every stored manuscript. Returns the number removed.

    Only reachable from the owner reset, and only when the corpus itself is
    being wiped. Files are not rows: wiping `papers_assessment` while leaving
    the PDFs behind would leave a directory of manuscripts belonging to
    assessments that no longer exist, readable by anyone who could guess a
    hash — so the two have to be clearable together.

    Deletes only *.pdf inside the store, never the directory, so a
    misconfigured BASE_DIR cannot escalate into removing something else.
    """
    removed = 0
    try:
        names = os.listdir(PAPER_STORE_DIR)
    except OSError as e:
        logging.warning("Could not list the paper store: %s", e)
        return 0
    for name in names:
        if not name.endswith(".pdf"):
            continue
        try:
            os.remove(os.path.join(PAPER_STORE_DIR, name))
            removed += 1
        except OSError as e:
            logging.warning("Could not delete stored manuscript %s: %s", name, e)
    return removed


# ==============================================================================================================
# persistence.py (was its own module; LicenseRef-PiTechLab-Proprietary)
# ==============================================================================================================
"""
Storage persistence check.

The problem this exists to catch
-------------------------------
ScholarPi keeps everything that matters — the SQLite database, the
Proof-of-Research ledger, piQ balances, trained Scilem weights — in a single
directory (``SCHOLARPI_DATA_DIR``, default ``~/Scientometric_Pi_Index``).

On a container platform, that directory is ephemeral *by default*. Railway,
Render, Fly and Heroku all give a fresh filesystem on every deploy unless a
persistent volume is explicitly attached and mounted at that path. So the app
runs perfectly, writes everything correctly, and then loses the entire ledger
on the next push — with no error, because nothing failed. The first symptom is
a user reporting their piQ balance reset.

Silence is the whole danger here. A wipe is indistinguishable from a first run
unless something remembers that a previous run happened, so this module leaves
a marker behind and counts boots. If the marker keeps vanishing while the
database is also empty, storage is ephemeral and the operator is told in terms
that name the fix.

This only reports. It never blocks startup: a deployment that is genuinely
meant to be disposable is legitimate, and refusing to boot would be worse than
the problem.
"""

persistence_logger = logging.getLogger(__name__)

MARKER_NAME = ".scholarpi_persistence.json"


def _marker_path(data_dir: str) -> str:
    return os.path.join(data_dir, MARKER_NAME)


def check_persistence(data_dir: str, db_path: str) -> dict:
    """Record this boot and report whether storage looks durable.

    Returns a dict describing what was found. Safe to call on every start; it
    performs one small read and one small write.
    """
    report = {
        "data_dir": data_dir,
        "marker_found": False,
        "boot_count": 1,
        "previous_boot": None,
        "db_exists": False,
        "db_bytes": 0,
        "verdict": "unknown",
        "warning": None,
    }

    try:
        os.makedirs(data_dir, exist_ok=True)
    except Exception as e:
        report["verdict"] = "unwritable"
        report["warning"] = f"Data directory {data_dir} could not be created: {e}"
        persistence_logger.error(report["warning"])
        return report

    try:
        if os.path.exists(db_path):
            report["db_exists"] = True
            report["db_bytes"] = os.path.getsize(db_path)
    except OSError:
        pass

    marker = {}
    path = _marker_path(data_dir)
    try:
        if os.path.exists(path):
            with open(path, "r") as fh:
                marker = json.load(fh) or {}
            report["marker_found"] = True
    except Exception as e:
        persistence_logger.debug("Persistence marker unreadable: %s", e)

    previous_boots = int(marker.get("boot_count", 0) or 0)
    report["boot_count"] = previous_boots + 1
    report["previous_boot"] = marker.get("last_boot")

    # A marker that was written by a previous run and survived means the
    # directory outlived at least one process. That is the only positive
    # evidence of durability available without waiting for a redeploy.
    if report["marker_found"]:
        report["verdict"] = "persistent"
    elif report["db_exists"] and report["db_bytes"] > 0:
        # Database present but no marker: first run after this check was added.
        report["verdict"] = "likely-persistent"
    else:
        report["verdict"] = "fresh"
        report["warning"] = (
            f"Starting with an EMPTY data directory ({data_dir}). If this is not a first "
            f"install, your storage is ephemeral and the previous ledger, piQ balances and "
            f"assessments were lost on redeploy. Attach a persistent volume and mount it at "
            f"this path, then set SCHOLARPI_DATA_DIR to it. On Railway/Render/Fly this is a "
            f"'Volume'; with Docker Compose the bundled 'scholarpi_data' volume already does it."
        )

    try:
        with open(path, "w") as fh:
            json.dump({
                "boot_count": report["boot_count"],
                "last_boot": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                "instance": marker.get("instance") or str(uuid.uuid4()),
            }, fh)
    except Exception as e:
        persistence_logger.warning("Could not write persistence marker in %s: %s", data_dir, e)

    if report["warning"]:
        persistence_logger.warning("STORAGE: %s", report["warning"])
    else:
        persistence_logger.info("STORAGE: %s (boot #%d, db %s)", report["verdict"],
                    report["boot_count"],
                    f"{report['db_bytes']} bytes" if report["db_exists"] else "not yet created")
    return report


# ==============================================================================================================
# pid_engine.py (was its own module; LicenseRef-PiTechLab-Proprietary)
# ==============================================================================================================
"""
piD — the pi-Dyne forecasting engine.

Epoch-weight forecasting: cached, bounded, and degradable.

The problem
-----------
Forecasting trained a 300-epoch LSTM inside the HTTP request. On a small host
that is slow enough to hit a gateway timeout and heavy enough to risk being
OOM-killed, which surfaced in the browser as "could not reach the forecasting
service" — a network-level failure with no explanation, on an endpoint that was
working correctly in principle.

Three changes make it reliable:

* **Caching.** The weight series only changes when a new Proof-of-Research
  block is written, so a forecast is recomputed only when the block count or
  lookback actually changes. Repeated views cost nothing.
* **Bounded training.** Epoch count scales with how much data exists. Running
  300 epochs over four data points is not more accurate, only slower.
* **A statistical fallback.** Holt's linear-trend method is implemented in
  plain NumPy and produces a comparable projection for a short series. If
  PyTorch is unavailable, too slow, or fails for any reason, the forecast
  degrades to this rather than failing. A working forecast computed by
  exponential smoothing is far more useful than a neural one that times out —
  and on series this short the two largely agree anyway.
"""


_pid_engine_lock = threading.Lock()
_cache: Dict[Tuple, Dict] = {}
_CACHE_TTL = 600  # seconds; also invalidated by block count changing

# Training is capped by data volume: more epochs over a handful of points
# fits noise rather than signal.
MIN_EPOCHS = 40
MAX_EPOCHS = 200
TRAINING_TIME_BUDGET = 6.0  # seconds; a forecast is not worth a timeout


def cache_key(block_count: int, lookback: int, source: str) -> Tuple:
    return (block_count, lookback, source)


def get_cached(key: Tuple) -> Optional[Dict]:
    with _pid_engine_lock:
        entry = _cache.get(key)
        if not entry:
            return None
        if time.time() - entry["at"] > _CACHE_TTL:
            _cache.pop(key, None)
            return None
        result = dict(entry["value"])
        result["cached"] = True
        return result


def store_cached(key: Tuple, value: Dict):
    with _pid_engine_lock:
        if len(_cache) > 64:
            _cache.clear()
        _cache[key] = {"at": time.time(), "value": value}


def epochs_for(sample_count: int) -> int:
    """Training length proportional to available data."""
    return int(max(MIN_EPOCHS, min(MAX_EPOCHS, sample_count * 25)))


# ---------------------------------------------------------------------------
# Statistical projection — the always-available path
# ---------------------------------------------------------------------------
def holt_linear_forecast(series: np.ndarray, alpha: float = 0.6,
                         beta: float = 0.3) -> np.ndarray:
    """One-step-ahead projection by Holt's linear-trend method.

    Chosen because it models level *and* trend with two parameters, which is
    the right complexity for a series of a few dozen points. Fitting anything
    heavier to this much data estimates noise.

    Operates column-wise, so all eight criteria are projected together.
    """
    data = np.asarray(series, dtype=np.float64)
    if data.ndim == 1:
        data = data.reshape(-1, 1)
    if len(data) < 2:
        return data[-1].copy()

    level = data[0].copy()
    trend = data[1] - data[0]
    for point in data[1:]:
        previous_level = level
        level = alpha * point + (1 - alpha) * (level + trend)
        trend = beta * (level - previous_level) + (1 - beta) * trend
    return level + trend


def train_lstm_forecast(weight_matrix: np.ndarray, lookback: int,
                        model_factory, dataset_factory, loader_factory,
                        torch_mod, nn_mod, optim_mod) -> Optional[np.ndarray]:
    """Train the pi-Dyne LSTM under a wall-clock budget.

    Returns None on any failure or overrun, so the caller falls back to the
    statistical path rather than propagating an error to the user.
    """
    try:
        samples = max(1, len(weight_matrix) - lookback)
        epochs = epochs_for(samples)
        dataset = dataset_factory(weight_matrix, lookback)
        loader = loader_factory(dataset, batch_size=min(4, max(1, len(dataset))), shuffle=False)

        model = model_factory()
        optimizer = optim_mod.Adam(model.parameters(), lr=0.01)
        loss_fn = nn_mod.MSELoss()

        model.train()
        deadline = time.time() + TRAINING_TIME_BUDGET
        completed = 0
        for _ in range(epochs):
            if time.time() > deadline:
                logging.info("Forecast training stopped at %d/%d epochs (time budget).",
                             completed, epochs)
                break
            for sequence, target in loader:
                optimizer.zero_grad()
                loss = loss_fn(model(sequence), target)
                loss.backward()
                optimizer.step()
            completed += 1

        if completed == 0:
            return None

        model.eval()
        with torch_mod.no_grad():
            window = torch_mod.tensor(weight_matrix[-lookback:],
                                      dtype=torch_mod.float32).unsqueeze(0)
            return np.asarray(model(window).squeeze().numpy(), dtype=np.float64)
    except Exception as e:
        logging.warning("LSTM forecast unavailable, using statistical projection: %s", e)
        return None


# ---------------------------------------------------------------------------
# piD as a genuine learner
# ---------------------------------------------------------------------------
# What was here before this section: Holt's linear trend with two constants
# (alpha 0.6, beta 0.3) chosen at authoring time, or an optional LSTM refitted
# from scratch inside each request and thrown away afterwards. Neither learned.
# Holt's constants never moved however wrong they were, and the LSTM could not
# carry anything between runs because nothing persisted it — a model retrained
# from zero on every call is a fitting procedure, not a learning system.
#
# What makes this one genuine: it forecasts, the forecast is recorded, and when
# the next Proof-of-Research block arrives the recorded forecast is scored
# against what actually happened and the parameters move. State persists in
# SQLite, so a restart resumes rather than restarts.
#
# The model is a per-criterion linear combination of five features drawn from
# the recent weight series. That is 5 parameters per criterion, 40 in total,
# which costs about a kilobyte — the whole point, given a 500 MB envelope that
# PyTorch would consume most of on import alone.
FEATURES = ["last", "trend", "mean3", "deviation", "momentum"]

# Authored defaults reproduce a sensible naive forecast: last value plus its
# recent trend. Starting from the previous behaviour rather than from zero
# means the model is useful on day one and the circuit breaker has a fair
# baseline to judge it against.
pid_engine_DEFAULT_WEIGHTS = [1.0, 1.0, 0.0, 0.0, 0.0]

_models: Dict[str, "object"] = {}
_MODEL_LOCK = threading.Lock()


def _feature_vector(series) -> list:
    """Five bounded features describing where a criterion's weight is heading."""
    s = np.asarray(series, dtype=float)
    s = np.nan_to_num(s, nan=0.0, posinf=0.0, neginf=0.0)
    if s.size == 0:
        return [0.0] * len(FEATURES)
    last = float(s[-1])
    prev = float(s[-2]) if s.size > 1 else last
    trend = last - prev
    mean3 = float(np.mean(s[-3:]))
    deviation = last - mean3
    # Second difference: is the trend itself accelerating?
    momentum = (last - 2 * prev + float(s[-3])) if s.size > 2 else 0.0
    return [last, trend, mean3, deviation, momentum]


def _model_for(criterion: str):
    """The persisted model for one criterion, loaded once per process."""
    pass
    pass

    with _MODEL_LOCK:
        m = _models.get(criterion)
        if m is None:
            m = RecursiveLeastSquares(
                name=f"pid:{criterion}", features=FEATURES,
                defaults=pid_engine_DEFAULT_WEIGHTS, forgetting=0.98, lo=0.0, hi=8.0)
            raw = load_engine_state(m.name)
            if raw:
                m.load_json(raw)
            _models[criterion] = m
        return m


def learned_forecast(series, criterion: str) -> float:
    """Next-epoch weight for one criterion, from the learned model."""
    return _model_for(criterion).predict(_feature_vector(series))


def learn_from_history(weight_matrix, criteria: List[str]) -> Dict:
    """Walk the recorded block history and learn from every transition.

    Called when new blocks appear. Each row is predicted from only the rows
    before it, then compared with what was actually written — so the model is
    trained the way it will be used, one step ahead, never having seen the
    answer.
    """
    pass

    matrix = np.asarray(weight_matrix, dtype=float)
    if matrix.ndim != 2 or matrix.shape[0] < 3:
        return {"learned": 0, "reason": "Not enough blocks to learn from yet."}

    learned = 0
    for idx, criterion in enumerate(criteria[:matrix.shape[1]]):
        model = _model_for(criterion)
        already = engine_observation_count(f"pid:{criterion}")
        column = matrix[:, idx]
        # Resume where the previous pass stopped rather than relearning the
        # whole history on every call, which would multiply-count old blocks
        # and make the observation count meaningless.
        start = max(2, already + 2)
        for t in range(start, column.size):
            model.observe(_feature_vector(column[:t]), float(column[t]))
            learned += 1
        save_engine_state(model.name, model.to_json())
    return {"learned": learned}


def pid_engine_engine_status(criteria: List[str]) -> Dict:
    """What piD has learned, per criterion, in auditable form."""
    pass
    models = []
    total_obs = 0
    improving = 0
    for c in criteria:
        st = _model_for(c).status()
        st["logged_observations"] = engine_observation_count(f"pid:{c}")
        total_obs += st["observations"]
        if st.get("learning"):
            improving += 1
        models.append(st)
    # Aggregate error across the eight criteria.
    #
    # Every per-criterion model already carries `mean_abs_error` and
    # `baseline_abs_error`; this function summed only the observation counts,
    # so piD published a five-figure observation total and no score, and the
    # engine card read "no error baseline to score against yet" against 39,696
    # observations. The numbers were there the whole time — nothing was adding
    # them up.
    #
    # Weighted by how many outcomes each criterion was actually scored over, so
    # a criterion evaluated twice cannot swing the headline as hard as one
    # evaluated a thousand times.
    num_m = num_b = weight = 0.0
    scored = 0
    for st in models:
        n = float(st.get("evaluated_over") or 0)
        m, bl = st.get("mean_abs_error"), st.get("baseline_abs_error")
        if n <= 0 or m is None or bl is None:
            continue
        num_m += float(m) * n
        num_b += float(bl) * n
        weight += n
        scored += 1

    return {
        "engine": "piD",
        "kind": "online linear forecaster (5 parameters per criterion)",
        "criteria": models,
        "total_observations": total_obs,
        "criteria_improving": improving,
        # None rather than 0 when nothing has been scored: zero error would be
        # a perfect forecaster, which is the opposite of "no data".
        "mean_abs_error": round(num_m / weight, 4) if weight else None,
        "baseline_abs_error": round(num_b / weight, 4) if weight else None,
        "evaluated_over": int(weight),
        "criteria_scored": scored,
        # Top-level `learning`, in the same vocabulary the other two engines
        # use. Without it piD reported `criteria_improving` and nothing else,
        # so the shared normaliser defaulted it to False and piD's card could
        # never take the "learning" highlight — it was the only one of the
        # three that could not, however well it was doing.
        "learning": bool(weight and num_m < num_b),
        "memory_note": ("NumPy only. ~40 parameters total; no PyTorch import, "
                        "so the 500 MB process budget is unaffected."),
    }


# ==============================================================================================================
# rib_engine.py (was its own module; LicenseRef-PiTechLab-Proprietary)
# ==============================================================================================================
"""
riB — the Research Buddy engine.

One of three engines in the framework, each with its own file:

    piD  (pid_engine.py)  epoch-weight forecasting
    riB  (rib_engine.py)  researcher-relative corpus guidance   <- this file
    siM  (sim_engine.py)  SciLM's learned structural calibration

What riB does
-------------
It answers one question the frontend cannot: how does *this researcher's*
stated work sit against what this deployment has actually assessed? Which of
their fields are crowded, which are empty, how their scores compare to the
corpus mean, and which adjacent fields hold material they have not claimed.

What it refuses to do
---------------------
Every number returned is a real count or a real mean over assessed papers.
Where there is no data it says so, rather than generating plausible advice —
a researcher cannot distinguish a grounded suggestion from an invented one, and
should not have to. That constraint is the whole reason this is an engine
rather than a prompt: the moment guidance comes from a language model, its
provenance stops being checkable.

It was previously inline in the API handler, which made the assessment
pipeline's only researcher-facing analysis indistinguishable from routing code.
"""

rib_engine_logger = logging.getLogger(__name__)


def parse_fields(profile: Dict) -> List[str]:
    """The researcher's stated fields, as a clean list."""
    raw = str((profile or {}).get("field", "") or "")
    return [f.strip() for f in raw.split(",") if f.strip()]


def corpus_summary(corpus: List[Dict]) -> Dict:
    """Totals over the assessed corpus.

    The mean is weighted by paper count, not a mean of per-field means. An
    unweighted average would let a field with one paper move the corpus mean as
    much as a field with fifty, which is not what "the corpus average" means to
    anyone reading it.
    """
    total_papers = sum(r.get("papers", 0) for r in (corpus or []))
    if not total_papers:
        return {"total_papers": 0, "mean_score": None, "fields_assessed": 0}
    weighted = sum(r.get("avg_score", 0.0) * r.get("papers", 0) for r in corpus)
    return {
        "total_papers": total_papers,
        "mean_score": round(weighted / total_papers, 1),
        "fields_assessed": len(corpus),
    }


def compare_fields(fields: List[str], corpus: List[Dict],
                   corpus_mean: Optional[float]) -> List[Dict]:
    """Each stated field against the corpus, including the ones with no data.

    Fields with nothing assessed are returned explicitly rather than omitted.
    Silently dropping them would leave a researcher believing every field they
    listed had been evaluated, when the honest answer is that this deployment
    has never seen work in that area.
    """
    by_field = {r["field"].lower(): r for r in (corpus or []) if r.get("field")}
    reports = []
    for name in fields:
        row = by_field.get(name.lower())
        if not row:
            reports.append({"field": name, "in_corpus": False,
                            "papers": 0, "avg_score": None, "vs_corpus": None})
            continue
        delta = (round(row["avg_score"] - corpus_mean, 1)
                 if corpus_mean is not None else None)
        reports.append({
            "field": name, "in_corpus": True,
            "papers": row["papers"], "avg_score": row["avg_score"],
            "vs_corpus": delta,
        })
    return reports


def adjacent_fields(fields: List[str], corpus: List[Dict], limit: int = 5) -> List[Dict]:
    """Fields with assessed work that the researcher did not list.

    The most useful suggestion available without external data: these are areas
    this deployment demonstrably holds material in, so pointing at them is a
    statement of fact rather than a guess about where someone should publish.
    """
    listed = {f.lower() for f in fields}
    return [
        {"field": r["field"], "papers": r["papers"], "avg_score": r.get("avg_score")}
        for r in (corpus or []) if r.get("field", "").lower() not in listed
    ][:limit]


def rib_engine_build_report(profile: Dict, corpus: List[Dict], picks: Optional[Dict] = None) -> Dict:
    """Assemble the full riB report from already-fetched inputs.

    Takes data rather than fetching it, so the engine can be exercised without
    a database and its output is a pure function of its input — which is what
    makes the "every number is grounded" claim testable rather than asserted.
    """
    fields = parse_fields(profile)
    summary = corpus_summary(corpus)
    reports = compare_fields(fields, corpus, summary["mean_score"])

    in_corpus = [r for r in reports if r["in_corpus"]]
    missing = [r for r in reports if not r["in_corpus"]]

    if not summary["total_papers"]:
        headline = ("Nothing has been assessed in this deployment yet, so there is nothing to "
                    "compare your fields against.")
    elif not fields:
        headline = (f"{summary['total_papers']} paper(s) assessed across "
                    f"{summary['fields_assessed']} field(s). Add your research fields to see "
                    f"how yours compare.")
    elif not in_corpus:
        headline = ("None of your listed fields have assessed work here yet, so no comparison "
                    "is possible for them.")
    else:
        best = max(in_corpus, key=lambda r: (r["vs_corpus"] if r["vs_corpus"] is not None else -99))
        headline = (f"{len(in_corpus)} of your {len(fields)} field(s) have assessed work here. "
                    f"{best['field']} scores "
                    f"{'above' if (best['vs_corpus'] or 0) >= 0 else 'below'} the corpus mean "
                    f"by {abs(best['vs_corpus'] or 0):.1f} piX.")

    return {
        "available": True,
        "engine": "riB",
        "profile_fields": fields,
        "fields": reports,
        "fields_with_data": len(in_corpus),
        "fields_without_data": [r["field"] for r in missing],
        # Ordered by the learned relevance model rather than by corpus order.
        # The figures in each entry are untouched measurements; learning
        # decides only which the researcher sees first.
        "adjacent": rank_suggestions(adjacent_fields(fields, corpus, limit=12),
                                     summary, fields)[:5],
        "corpus": summary,
        "picks": picks or {"available": False, "recommended": [], "caution": []},
        "headline": headline,
        "grounding": ("Every figure here is a count or mean over papers actually assessed by "
                      "this deployment. Where there is no data, riB reports its absence rather "
                      "than estimating."),
    }


# ---------------------------------------------------------------------------
# riB as a genuine learner
# ---------------------------------------------------------------------------
# riB was the hardest of the three to make learn, for a reason worth stating:
# it had no target. piD can be scored against the block that actually gets
# written, and siM against a corroborated panel verdict, but "was this guidance
# useful?" is not observable anywhere in the system. A model with no error
# signal cannot learn regardless of its architecture, and dressing statistics
# up as a network would have produced something that looked like learning and
# was not.
#
# So the target is created rather than inferred: a researcher marks a suggestion
# useful or not, and that verdict is the label. What riB learns is which
# suggestions are worth surfacing — a relevance model over the features of a
# candidate field, used to RANK what it shows.
#
# What it deliberately does not learn: the counts and means themselves. Those
# are measurements, they are the reason riB is trustworthy, and a learned
# adjustment to a fact is a fabrication. Learning is confined to ordering.
RIB_FEATURES = ["papers", "score_gap", "corpus_share", "is_listed", "novelty"]

# Authored prior: prefer fields with more assessed papers and a positive score
# gap. This reproduces the previous fixed ordering, so the breaker has a real
# baseline and day-one behaviour is unchanged.
RIB_DEFAULTS = [0.5, 0.3, 0.2, 0.0, 0.1]

_rib_model = None
_RIB_NAME = "rib:relevance"


def _rib():
    global _rib_model
    if _rib_model is None:
        pass
        pass
        # Swept against held-out feedback rather than guessed. lr 0.05 gave
        # +7% error reduction over the frozen defaults; 0.30 gives +29.7% at
        # the same 88-90% agreement, because riB's target is a bounded 0/1
        # verdict where a larger step cannot run away. max_step still caps any
        # single researcher's influence on the ranking.
        _rib_model = OnlineLinearModel(
            name=_RIB_NAME, features=RIB_FEATURES, defaults=RIB_DEFAULTS,
            lr=0.30, max_step=0.05, decay_scale=800.0, lo=0.0, hi=1.0)
        raw = load_engine_state(_RIB_NAME)
        if raw:
            _rib_model.load_json(raw)
    return _rib_model


def rib_features(candidate: Dict, summary: Dict, listed: bool = False) -> List[float]:
    """Bounded features for one candidate suggestion.

    All normalised to roughly [0, 1] so no single feature dominates the
    gradient purely by living on a larger scale — a field with 400 papers must
    not swamp a score gap measured in piX points.
    """
    total = max(1, int((summary or {}).get("total_papers", 0) or 1))
    mean = float((summary or {}).get("mean_score", 0.0) or 0.0)
    papers = float(candidate.get("papers", 0) or 0)
    avg = candidate.get("avg_score")
    gap = (float(avg) - mean) if avg is not None else 0.0
    return [
        min(1.0, papers / 25.0),              # depth of material available
        max(-1.0, min(1.0, gap / 25.0)),      # quality relative to the corpus
        min(1.0, papers / total),             # how much of the corpus this is
        1.0 if listed else 0.0,               # already one of theirs
        1.0 if papers <= 2 else 0.0,          # thin, i.e. an opening
    ]


def rank_suggestions(candidates: List[Dict], summary: Dict,
                     listed_fields: Optional[List[str]] = None) -> List[Dict]:
    """Order candidate fields by learned relevance.

    Every candidate keeps its real figures untouched; only the order changes,
    and each carries the score it was ranked by so the ordering is inspectable
    rather than mysterious.
    """
    listed = {f.lower() for f in (listed_fields or [])}
    model = _rib()
    scored = []
    for c in candidates or []:
        feats = rib_features(c, summary, c.get("field", "").lower() in listed)
        scored.append({**c,
                       "relevance": round(model.predict(feats), 4),
                       "_features": feats})
    scored.sort(key=lambda r: -r["relevance"])
    return scored


def observe_feedback(candidate: Dict, summary: Dict, useful: bool,
                     account_key: str = "", listed: bool = False) -> Dict:
    """Learn from a researcher's verdict on one suggestion."""
    pass

    model = _rib()
    feats = candidate.get("_features") or rib_features(candidate, summary, listed)
    result = model.observe(feats, 1.0 if useful else 0.0)
    save_engine_state(_RIB_NAME, model.to_json())
    log_engine_observation(_RIB_NAME, feats, 1.0 if useful else 0.0, result,
                           source="user")
    record_rib_feedback(account_key, candidate.get("field", ""), feats, useful)
    return result


def rib_engine_engine_status() -> Dict:
    pass
    st = _rib().status()
    st["logged_observations"] = engine_observation_count(_RIB_NAME)
    st["feedback"] = rib_feedback_totals()
    st["engine"] = "riB"
    st["kind"] = "online relevance ranker (5 parameters)"
    st["learns"] = "which suggestions to surface, from researcher feedback"
    st["never_learns"] = "the counts and means themselves, which stay measured"
    return st


# ---------------------------------------------------------------------------
# LLM tutoring
#
# The ranker learns from researcher feedback. A new deployment has none, so it
# sits on its authored defaults until enough people vote — which on a quiet
# platform may be never. Tutoring bootstraps it: while real feedback is scarce,
# a language model judges whether a candidate is relevant to a stated profile,
# and that judgement is fed in as a WEAK observation.
#
# Three properties make this a bootstrap rather than a dependency:
#
#   * It stops on its own once real feedback passes the threshold. A person's
#     verdict about their own field beats a model's guess, and once there are
#     enough of the former the latter is noise.
#   * Every tutored observation is logged with source="llm", so the engine's
#     history can always separate what people said from what a model said.
#   * The learning rate is scaled down (RIB_TUTOR_WEIGHT), so a wrong model
#     answer moves the ranker less than a right human one.
#
# It is never shown to the user as advice. The only thing that reaches the
# interface is the ranking the engine already produced.
# ---------------------------------------------------------------------------
_TUTOR_CALLS = {"day": "", "count": 0}


def rib_engine_tutor_status() -> Dict:
    """Whether tutoring is on, and why it is or is not running."""
    pass
    pass
    human = _human_observation_count()
    return {
        "enabled": bool(ENABLE_RIB_LLM_TUTOR),
        "active": rib_engine_tutor_phase_active(),
        "human_observations": human,
        "stops_at": RIB_TUTOR_UNTIL_OBS,
        "calls_today": _TUTOR_CALLS["count"] if _TUTOR_CALLS["day"] == _rib_engine_today() else 0,
        "daily_cap": RIB_TUTOR_MAX_CALLS_PER_DAY,
        "total_observations": engine_observation_count(_RIB_NAME),
        "note": ("A language model is helping train riB's relevance ranking while real "
                 "researcher feedback is scarce. It stops automatically once enough people "
                 "have rated suggestions, and its judgements are recorded separately from "
                 "theirs."),
    }


def _rib_engine_today() -> str:
    from datetime import datetime as _dt
    return _dt.now().strftime("%Y-%m-%d")


def _human_observation_count() -> int:
    """Observations that came from a person, not from the tutor."""
    pass
    try:
        return engine_observation_count(_RIB_NAME, source="user")
    except TypeError:
        # Older signature with no source filter: fall back to the total rather
        # than failing. It over-counts, which makes tutoring stop EARLIER —
        # the safe direction to be wrong in.
        return engine_observation_count(_RIB_NAME)


def rib_engine_tutor_phase_active() -> bool:
    pass
    if not ENABLE_RIB_LLM_TUTOR:
        return False
    if _TUTOR_CALLS["day"] == _rib_engine_today() and _TUTOR_CALLS["count"] >= RIB_TUTOR_MAX_CALLS_PER_DAY:
        return False
    return _human_observation_count() < RIB_TUTOR_UNTIL_OBS


def rib_engine_tutor_from_llm(candidates: List[Dict], profile: Dict, summary: Dict) -> Dict:
    """Ask a model which candidates are relevant, and teach the ranker.

    Returns a small record of what happened. Never raises: tutoring is an
    optimisation, and a provider outage must not affect the report the user is
    waiting for — which is why the caller runs this AFTER responding.
    """
    pass
    if not rib_engine_tutor_phase_active() or not candidates:
        return {"tutored": 0, "reason": "not active"}

    fields = ", ".join(parse_fields(profile)) or "unstated"
    goal = (profile.get("goal") or "").strip() or "unstated"
    # A handful per call. The point is a steady trickle of signal, not to
    # label the whole corpus in one burst.
    batch = candidates[:5]

    listing = "\n".join(
        f"{i + 1}. {str(c.get('title') or 'Untitled')[:160]} "
        f"[fields: {', '.join(c.get('fields') or []) or 'unclassified'}]"
        for i, c in enumerate(batch))
    prompt = (
        "You are helping calibrate a recommender that suggests papers to a researcher.\n\n"
        f"The researcher works in: {fields}\n"
        f"Their stated goal: {goal}\n\n"
        "For each paper below, answer whether it is RELEVANT to that researcher — that is, "
        "whether reading it would plausibly help them with their stated field and goal. "
        "Judge relevance only. Do not judge quality; another part of the system does that.\n\n"
        f"{listing}\n\n"
        'Return JSON: {"verdicts": [{"n": 1, "relevant": true}, ...]}'
    )

    try:
        pass
        pass
        routes = [r for r in build_routes("judge") if not is_scilm_route(r)]
        answer = None
        for route in routes[:3]:
            cooling, _ = is_route_cooling(route["model"], route["provider"])
            if cooling:
                continue
            _, attempt = request_model_assessment(
                "pidyne", route["model"], route["key"], route["base"], prompt)
            if not attempt.get("api_failed", True):
                record_success(route["model"], route["provider"])
                answer = attempt
                break
        if not answer:
            return {"tutored": 0, "reason": "no model reachable"}
    except Exception as e:                                   # noqa: BLE001
        logging.warning("riB tutoring call failed: %s", e)
        return {"tutored": 0, "reason": "call failed"}

    if _TUTOR_CALLS["day"] != _rib_engine_today():
        _TUTOR_CALLS["day"], _TUTOR_CALLS["count"] = _rib_engine_today(), 0
    _TUTOR_CALLS["count"] += 1

    verdicts = answer.get("verdicts")
    if not isinstance(verdicts, list):
        return {"tutored": 0, "reason": "unparseable answer"}

    pass
    model = _rib()
    taught = 0
    for v in verdicts:
        try:
            idx = int(v.get("n", 0)) - 1
            relevant = bool(v.get("relevant"))
        except (TypeError, ValueError):
            continue
        if not (0 <= idx < len(batch)):
            continue
        cand = batch[idx]
        feats = cand.get("_features") or rib_features(cand, summary, False)
        # Scaled down: a model's guess should move the ranker less than a
        # researcher's verdict about their own field.
        target = 1.0 if relevant else 0.0
        result = model.observe(feats, target, weight=RIB_TUTOR_WEIGHT) \
            if _observe_accepts_weight(model) else model.observe(feats, target)
        log_engine_observation(_RIB_NAME, feats, target, result, source="llm")
        taught += 1

    if taught:
        save_engine_state(_RIB_NAME, model.to_json())
        logging.info("riB tutored on %d candidate(s); %d/%d calls used today.",
                     taught, _TUTOR_CALLS["count"], RIB_TUTOR_MAX_CALLS_PER_DAY)
    return {"tutored": taught, "reason": ""}


def _observe_accepts_weight(model) -> bool:
    """Whether the online model supports a per-observation learning weight.

    Checked rather than assumed: the ranker predates tutoring, and calling it
    with an argument it does not take would break ordinary user feedback too.
    """
    try:
        import inspect
        return "weight" in inspect.signature(model.observe).parameters
    except (TypeError, ValueError):
        return False


# ==============================================================================================================
# rib_suggest.py (was its own module; LicenseRef-PiTechLab-Proprietary)
# ==============================================================================================================
"""RiBD suggestions: papers to read (one from the ledger explorer, one scanned
manuscript and up to three more), chosen for the researcher's profile, and the
hot topics: the fields where papers here earn the most piX and piQ and where
activity is rising (hot_topics).

Pure functions over plain rows, so they can be tested without a database.

Relevance comes only from what the researcher wrote in their profile:
  - a shared field                       +3 each
  - a profile keyword found in the title +2 each
  - a word from their core claim in the title (5+ letters, not a stop word) +1 each
Nothing is suggested on relevance zero: a pick that matches nothing in the
profile would be advice assembled from someone else's interests, the very thing
RiBD refuses to do elsewhere. The researcher's own papers are never suggested.

The two picks are different papers:
  - from the explorer: a paper recorded on the Proof-of-Research ledger, the
    best match, ties broken by piX;
  - a scanned manuscript: any assessed manuscript, the best match, ties broken
    by how recently it was scanned.
"""


rib_suggest_STOP = set("""about above after again against among because before being below between
both could doing during each further having however might other their there these
those through under until using which while would within without study paper
results based model models method methods analysis approach towards toward""".split())


def _fields(raw) -> List[str]:
    if isinstance(raw, list):
        return [str(f).strip() for f in raw if str(f).strip()]
    try:
        v = json.loads(raw or "[]")
        if isinstance(v, list):
            return [str(f).strip() for f in v if str(f).strip()]
    except (ValueError, TypeError):
        pass
    return [f.strip() for f in str(raw or "").split(",") if f.strip()]


def profile_terms(profile: Dict) -> Dict[str, List[str]]:
    p = profile or {}
    fields = [f.strip() for f in str(p.get("field", "") or "").split(",") if f.strip()]
    keywords = [k.strip() for k in str(p.get("goal", "") or "").split(",") if k.strip()]
    idea_words = sorted({w for w in re.findall(r"[a-zA-Z][a-zA-Z\-]{4,}", str(p.get("idea", "") or "").lower())
                         if w not in rib_suggest_STOP})
    return {"fields": fields, "keywords": keywords, "idea": idea_words}


def relevance(row: Dict, terms: Dict[str, List[str]]):
    """(score, reasons) for one paper against the profile terms."""
    title = str(row.get("title") or "").lower()
    pf = {f.lower() for f in _fields(row.get("fields"))}
    score, why = 0, []
    shared = [f for f in terms["fields"] if f.lower() in pf]
    if shared:
        score += 3 * len(shared)
        why.append("shares your field " + ", ".join(shared))
    kws = [k for k in terms["keywords"] if k.lower() in title]
    if kws:
        score += 2 * len(kws)
        why.append("mentions " + ", ".join(f"“{k}”" for k in kws))
    words = [w for w in terms["idea"] if re.search(r"\b" + re.escape(w) + r"\b", title)]
    if words:
        score += len(words)
        why.append("touches your core claim (" + ", ".join(words[:3]) + ")")
    return score, why


def _pick(rows: Iterable[Dict], terms, tiebreak: str, skip: set) -> Optional[Dict]:
    best, best_key = None, None
    for r in rows:
        h = r.get("eval_hash")
        if not h or h in skip:
            continue
        s, why = relevance(r, terms)
        if s <= 0:
            continue
        tb = (r.get("score") or 0.0) if tiebreak == "score" else str(r.get("timestamp") or "")
        key = (s, tb)
        if best_key is None or key > best_key:
            best_key = key
            best = dict(r, relevance=s, why="Suggested because it " + "; ".join(why) + ".",
                        fields=_fields(r.get("fields")))
    return best


def suggest(profile: Dict, rows: List[Dict], own_hashes: Iterable[str] = ()) -> Dict:
    """{"explorer": pick|None, "manuscript": pick|None, "reason": str|None}.

    rows: dicts with eval_hash, title, author, fields (JSON or list), score,
    timestamp, on_ledger (bool).
    """
    terms = profile_terms(profile)
    if not (terms["fields"] or terms["keywords"] or terms["idea"]):
        return {"explorer": None, "manuscript": None, "more": [],
                "reason": "Add your fields or keywords to your profile and RiBD will suggest papers.",
                "hot": hot_topics(rows)}
    own = set(own_hashes or ())
    explorer = _pick((r for r in rows if r.get("on_ledger")), terms, "score", own)
    skip = own | ({explorer["eval_hash"]} if explorer else set())
    manuscript = _pick(rows, terms, "recent", skip)
    reason = None
    if not explorer and not manuscript:
        reason = "Nothing assessed here matches your profile yet."
    keep = ("eval_hash", "title", "author", "fields", "score", "timestamp", "why", "relevance")
    trim = lambda p: {k: p.get(k) for k in keep} if p else None   # noqa: E731
    # Also worth reading: up to three more relevant papers, best match first,
    # then highest piX.
    taken = skip | ({manuscript["eval_hash"]} if manuscript else set())
    more = []
    for r in rows:
        h = r.get("eval_hash")
        if not h or h in taken:
            continue
        sc, why = relevance(r, terms)
        if sc > 0:
            more.append((sc, r.get("score") or 0.0, dict(r, why="Suggested because it " + "; ".join(why) + ".",
                                                         fields=_fields(r.get("fields")), relevance=sc)))
    more.sort(key=lambda x: (x[0], x[1]), reverse=True)
    return {"explorer": trim(explorer), "manuscript": trim(manuscript),
            "more": [trim(m[2]) for m in more[:3]], "reason": reason,
            "hot": hot_topics(rows, terms["fields"])}


def _ts_days_ago(ts: str, now) -> Optional[float]:
    from datetime import datetime
    try:
        t = datetime.fromisoformat(str(ts).replace("Z", "")[:19])
    except ValueError:
        return None
    return (now - t).total_seconds() / 86400.0


def hot_topics(rows: List[Dict], my_fields: Iterable[str] = (), limit: int = 5, now=None) -> List[Dict]:
    """Fields worth researching here: where papers earn the most piX and piQ,
    and where activity is rising.

    Per field with at least two assessed papers:
      avg_pix      mean piX
      avg_piq      mean piQ minted per paper
      recent       papers in the last 30 days
    Each is scaled to 0..1 across fields and combined
    0.4 piX + 0.4 piQ + 0.2 recent activity. It describes what has paid off
    in this corpus so far, not a promise about any future paper.
    """
    from datetime import datetime
    now = now or datetime.utcnow()
    stats: Dict[str, Dict] = {}
    for r in rows:
        try:
            score = float(r.get("score"))
        except (TypeError, ValueError):
            continue
        piq = float(r.get("piq") or 0.0)
        age = _ts_days_ago(r.get("timestamp"), now)
        for f in _fields(r.get("fields"))[:2]:
            s = stats.setdefault(f, {"n": 0, "pix": 0.0, "piq": 0.0, "recent": 0})
            s["n"] += 1
            s["pix"] += score
            s["piq"] += piq
            if age is not None and age <= 30:
                s["recent"] += 1
    rowsf = [(f, s["n"], s["pix"] / s["n"], s["piq"] / s["n"], s["recent"])
             for f, s in stats.items() if s["n"] >= 2]
    if not rowsf:
        return []

    def scale(vals):
        lo, hi = min(vals), max(vals)
        return [0.5 if hi == lo else (v - lo) / (hi - lo) for v in vals]

    px = scale([r[2] for r in rowsf])
    pq = scale([r[3] for r in rowsf])
    rc = scale([r[4] for r in rowsf])
    mine = {f.lower() for f in (my_fields or [])}
    out = []
    for i, (f, n, apx, apq, rec) in enumerate(rowsf):
        heat = 0.4 * px[i] + 0.4 * pq[i] + 0.2 * rc[i]
        out.append({"field": f, "papers": n, "avg_pix": round(apx, 1), "avg_piq": round(apq, 3),
                    "recent": rec, "heat": round(heat, 3), "yours": f.lower() in mine})
    out.sort(key=lambda d: (d["heat"], d["avg_pix"]), reverse=True)
    return out[:limit]


