# routes/bugreport.py (was its own module; LicenseRef-PiTechLab-Proprietary)
# ==============================================================================================================
"""routes/bugreport.py: bug reports. Split from api.py; see DESIGN.md section 5."""

bugreport_router = APIRouter()



# ---------------------------------------------------------------------------
# Bug reports
# ---------------------------------------------------------------------------
class BugReport(BaseModel):
    message: str
    contact: str = ""
    page: str = ""
    # "bug" or "suggestion". Defaults to bug so an older client, which has no
    # such field, keeps behaving exactly as it did.
    kind: str = "bug"
    wallet: str = ""
    orcid: str = ""


@bugreport_router.get("/api/bug-report/status")
def bug_report_status():
    """What the form should promise before the user types anything."""
    # Kinds travel with the status so the form and the store share one
    # vocabulary rather than each hardcoding its own.
    return {**delivery_status(),
            "kinds": [{"id": k, "label": v} for k, v in CONTACT_KINDS.items()]}


@bugreport_router.post("/api/bug-report")
def submit_bug_report(payload: BugReport, request: Request):
    """Store the report, then attempt email delivery in the background.

    Storing first is the point. Mail is the part that fails — expired
    credentials, a throttling provider, a host that blocks outbound 587 — and
    telling someone their report was sent when it was silently dropped is worse
    than not offering the button. The confirmation the user gets is a receipt
    for something already committed to the database.
    """
    client_ip = get_client_ip(request)
    check_rate_limit(client_ip, bucket="bug_report")

    problem = bugreport_validate(payload.message, payload.contact)
    if problem:
        raise HTTPException(status_code=400, detail=problem)

    kind = payload.kind if payload.kind in CONTACT_KINDS else "bug"
    key = _profile_key(payload.wallet, payload.orcid)
    report = normalise(
        message=payload.message, contact=payload.contact, identity=key,
        page=payload.page, user_agent=request.headers.get("user-agent", ""),
    )
    report["kind"] = kind
    # The raw IP is not stored: a bug report is not an abuse signal, and
    # keeping one would attach an identifier to a complaint for no operational
    # reason. The hash still supports rate limiting and duplicate detection.
    ip_hash = hashlib.sha256(f"bugreport:{client_ip}".encode()).hexdigest()[:32]

    try:
        report["id"] = store_bug_report(report, ip_hash=ip_hash)
    except Exception as e:
        logging.exception("Bug report could not be stored")
        raise HTTPException(status_code=500,
                            detail="The report could not be saved. Please try again.") from e

    add_log(f"Contact message #{report['id']} received ({kind}, "
            f"{len(report['message'])} chars).")
    send_async(report, on_result=lambda rid, res: mark_bug_report_delivered(
        rid, res["sent"], res.get("error") or ""))

    emailed = smtp_configured()
    return {
        "received": True,
        "id": report["id"],
        "emailed": emailed,
        "kind": kind,
        "message": (
            f"Thank you — {'suggestion' if kind == 'suggestion' else 'report'} "
            f"#{report['id']} was saved"
            + (" and is being emailed to the maintainer." if emailed
               else ". Email delivery is not configured on this deployment, so it is stored "
                    "on the server for the maintainer to read.")
        ),
    }


@bugreport_router.get("/api/bug-report/list")
def bug_report_list(request: Request, wallet: str = Query(default=""),
                    limit: int = Query(default=100, ge=1, le=300)):
    """Owner-only. The reports that failed to send exist nowhere else."""
    require_owner(request, wallet)
    reports = list_bug_reports(limit=limit)
    return {"reports": reports,
            "undelivered": sum(1 for r in reports if not r["delivered"]),
            "count": len(reports)}


# ---------------------------------------------------------------------------
# The open portal (owner, 2026-10-17: "can you make a open portal in piii.app so whatever you type in it stays
# public and saved on the site"). Anyone may write; everyone reads it, newest first. Plain text only (the page
# shows it as text, never as markup). Limits per writer, counted in the database so they hold across workers and
# restarts: one post per PORTAL_GAP seconds, PORTAL_PER_DAY a day, and the same words not twice. The writer gets a
# key, kept in their browser, to take their own post down; the owner can take any down.
# ---------------------------------------------------------------------------
portal_router = APIRouter()

PORTAL_MAX = 1000
PORTAL_NAME_MAX = 32
PORTAL_GAP = 20
PORTAL_PER_DAY = 40


class PortalPost(BaseModel):
    text: str
    name: str = ""


class PortalDelete(BaseModel):
    key: str = ""
    wallet: str = ""


def _portal_clean(s: str, limit: int) -> str:
    # no control characters but line breaks and tabs; no more than two blank lines in a row
    s = "".join(c for c in (s or "") if c in "\n\t" or (ord(c) >= 32 and not 0x7F <= ord(c) < 0xA0
                                                         and c not in "\u200b\u200c\u200d\u2028\u2029\u202a\u202b\u202c\u202d\u202e\ufeff"))
    s = re.sub(r"\n{3,}", "\n\n", s.replace("\r", "")).strip()
    return s[:limit]


def _portal_ip_hash(request: Request) -> str:
    salt = os.getenv("SESSION_SECRET", "") or "portal"
    return hashlib.sha256(f"portal:{salt}:{get_client_ip(request)}".encode()).hexdigest()[:32]


def _portal_row(r) -> dict:
    return {"id": r[0], "text": r[1], "name": r[2] or "", "at": str(r[3] or "")}


@portal_router.get("/api/portal")
def portal_list(before: int = Query(default=0, ge=0), limit: int = Query(default=50, ge=1, le=100)):
    """What is on the portal, newest first; `before` pages back."""
    conn = get_db_connection()
    try:
        q = "SELECT id, text, name, created_at FROM portal_posts WHERE hidden=0"
        args: list = []
        if before:
            q += " AND id < ?"
            args.append(before)
        rows = conn.execute(q + " ORDER BY id DESC LIMIT ?", (*args, limit + 1)).fetchall()
        total = conn.execute("SELECT COUNT(*) FROM portal_posts WHERE hidden=0").fetchone()[0]
    finally:
        conn.close()
    return {"posts": [_portal_row(r) for r in rows[:limit]], "more": len(rows) > limit, "total": total,
            "max": PORTAL_MAX, "name_max": PORTAL_NAME_MAX}


@portal_router.post("/api/portal")
def portal_post(payload: PortalPost, request: Request):
    check_rate_limit(get_client_ip(request), bucket="portal")
    text = _portal_clean(payload.text, PORTAL_MAX + 1)
    name = _portal_clean(payload.name, PORTAL_NAME_MAX + 1).replace("\n", " ")
    if not text:
        raise HTTPException(status_code=400, detail="Write something first.")
    if len(text) > PORTAL_MAX:
        raise HTTPException(status_code=400, detail=f"At most {PORTAL_MAX} characters.")
    if len(name) > PORTAL_NAME_MAX:
        raise HTTPException(status_code=400, detail=f"A name of at most {PORTAL_NAME_MAX} characters.")
    ip_hash = _portal_ip_hash(request)
    now = datetime.utcnow()
    conn = get_db_connection()
    try:
        last = conn.execute("SELECT created_at FROM portal_posts WHERE ip_hash=? ORDER BY id DESC LIMIT 1",
                            (ip_hash,)).fetchone()
        if last:
            try:
                wait = PORTAL_GAP - (now - datetime.fromisoformat(str(last[0]))).total_seconds()
            except ValueError:
                wait = 0
            if wait > 0:
                raise HTTPException(status_code=429, detail=f"One post every {PORTAL_GAP} seconds: "
                                                            f"wait {int(wait) + 1} more.")
        day = (now - timedelta(days=1)).isoformat(sep=" ", timespec="seconds")
        n = conn.execute("SELECT COUNT(*) FROM portal_posts WHERE ip_hash=? AND created_at > ?",
                         (ip_hash, day)).fetchone()[0]
        if n >= PORTAL_PER_DAY:
            raise HTTPException(status_code=429, detail=f"{PORTAL_PER_DAY} posts a day at most: come back tomorrow.")
        if conn.execute("SELECT 1 FROM portal_posts WHERE ip_hash=? AND text=? AND created_at > ?",
                        (ip_hash, text, day)).fetchone():
            raise HTTPException(status_code=409, detail="You wrote exactly this already.")
        key = secrets.token_urlsafe(18)
        cur = conn.execute(
            "INSERT INTO portal_posts (text, name, ip_hash, key_hash, created_at) VALUES (?, ?, ?, ?, ?)",
            (text, name, ip_hash, hashlib.sha256(key.encode()).hexdigest(), now.isoformat(sep=" ", timespec="seconds")))
        conn.commit()
        pid = int(cur.lastrowid)
        row = conn.execute("SELECT id, text, name, created_at FROM portal_posts WHERE id=?", (pid,)).fetchone()
    finally:
        conn.close()
    add_log(f"Portal post #{pid} ({len(text)} chars).")
    return {**_portal_row(row), "key": key}


@portal_router.post("/api/portal/{post_id}/delete")
def portal_delete(post_id: int, payload: PortalDelete, request: Request):
    """The writer (with the key their browser kept) or the owner takes a post down."""
    check_rate_limit(get_client_ip(request), bucket="portal_delete")
    conn = get_db_connection()
    try:
        row = conn.execute("SELECT key_hash FROM portal_posts WHERE id=? AND hidden=0", (post_id,)).fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="No such post.")
        mine = bool(payload.key) and hmac.compare_digest(row[0] or "", hashlib.sha256(payload.key.encode()).hexdigest())
        if not mine:
            require_owner(request, payload.wallet)
        conn.execute("UPDATE portal_posts SET hidden=1, text='', name='' WHERE id=?", (post_id,))
        conn.commit()
    finally:
        conn.close()
    add_log(f"Portal post #{post_id} taken down ({'by its writer' if mine else 'by the owner'}).")
    return {"deleted": post_id}


# ---------------------------------------------------------------------------
# The web proxy (owner, 2026-10-17: "A web proxy on piii.app", chosen over a VPN that needs an app). A page of
# another site, fetched by this server and shown here: browsing from the server's address instead of the
# visitor's, with nothing to install. Websites only, and pages that need their own scripts do not work.
#
# What keeps it safe, each because the obvious version gets it wrong:
#   - Only with the password (PROXY_PASSWORD, set by the owner): otherwise it is an open proxy, and whatever
#     anyone does through it comes from the owner's address. Unset, the proxy is off.
#   - Only public addresses, every redirect checked again (public_url): never the router, the LAN or this server.
#   - The fetched page runs no scripts and is sandboxed (Content-Security-Policy, sandbox): it is served from
#     piii.app's own address, and a script there could read the visitor's piii.app session.
#   - Its links, pictures, styles and forms are rewritten to come through the proxy too; its cookies are not
#     passed on in either direction.
#   - A size cap and a time limit per fetch, and a per-address rate.
# Nothing about what is visited is stored or logged.
# ---------------------------------------------------------------------------
proxy_router = APIRouter()

PROXY_COOKIE = "pi_proxy"
PROXY_MAX_BYTES = 12 * 1024 * 1024
PROXY_TIMEOUT = 20
PROXY_RATE = 240          # fetches a minute for one address (a page with its pictures is tens of them)
_proxy_hits: Dict[str, list] = defaultdict(list)
PROXY_CSP = ("sandbox allow-forms allow-same-origin allow-popups allow-popups-to-escape-sandbox "
             "allow-top-navigation-by-user-activation; "
             "default-src 'self' data:; script-src 'none'; object-src 'none'; base-uri 'none'; "
             "form-action 'self'; frame-ancestors 'self'; style-src 'self' 'unsafe-inline' data:; "
             "img-src 'self' data:; font-src 'self' data:; media-src 'self' data:; frame-src 'self'")
PROXY_UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) "
            "Chrome/128.0.0.0 Safari/537.36")


def proxy_password() -> str:
    return (os.getenv("PROXY_PASSWORD") or "").strip()


def proxy_token(pw: str) -> str:
    secret = os.getenv("SESSION_SECRET", "").strip() or pw
    return hmac.new(secret.encode(), ("proxy:" + pw).encode(), hashlib.sha256).hexdigest()


def proxy_allowed(request: Request) -> bool:
    pw = proxy_password()
    got = request.cookies.get(PROXY_COOKIE) or ""
    return bool(pw) and bool(got) and hmac.compare_digest(got, proxy_token(pw))


def proxy_rate(request: Request):
    ip = get_client_ip(request)
    now = time.time()
    hits = _proxy_hits[ip]
    while hits and hits[0] < now - 60:
        hits.pop(0)
    if len(hits) >= PROXY_RATE:
        raise HTTPException(status_code=429, detail="Too many pages a minute through the proxy. Wait a little.")
    hits.append(now)


def proxy_link(url: str) -> str:
    return "/proxy?u=" + urllib.parse.quote(url, safe="")


def proxy_target(url: str) -> str:
    """What was typed, as an address: https:// added when it has none."""
    url = (url or "").strip()
    if url and not re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*://", url):
        url = "https://" + url
    return url


def _proxy_abs(base: str, ref: str) -> Optional[str]:
    ref = (ref or "").strip()
    if not ref or ref.startswith(("#", "javascript:", "data:", "mailto:", "tel:", "about:", "blob:")):
        return None
    try:
        u = urllib.parse.urljoin(base, ref)
    except ValueError:
        return None
    return u if u.startswith(("http://", "https://")) else None


_CSS_URL = re.compile(r"""url\(\s*(['"]?)([^'")]+)\1\s*\)""", re.I)
_CSS_IMPORT = re.compile(r"""@import\s+(['"])([^'"]+)\1""", re.I)


def proxy_css(css: str, base: str) -> str:
    def u(m):
        a = _proxy_abs(base, m.group(2))
        return f"url('{proxy_link(a)}')" if a else m.group(0)

    def i(m):
        a = _proxy_abs(base, m.group(2))
        return f"@import '{proxy_link(a)}'" if a else m.group(0)
    return _CSS_IMPORT.sub(i, _CSS_URL.sub(u, css))


class _ProxyHTML(__import__("html.parser", fromlist=["HTMLParser"]).HTMLParser):
    """A page rewritten so everything it points to comes through the proxy, and nothing of its own runs."""
    URL_ATTRS = {"href", "src", "action", "poster", "background", "data", "formaction", "data-src", "longdesc"}
    DROP = {"script", "noscript", "object", "embed", "applet"}
    VOID = {"area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "param", "source", "track", "wbr"}

    def __init__(self, base: str):
        super().__init__(convert_charrefs=False)
        self.base = base
        self.out: list = []
        self.skip = 0
        self.in_style = False
        self.title = ""
        self._in_title = False

    def _attrs(self, tag, attrs):
        out, has_action = [], False
        for k, v in attrs:
            k = k.lower()
            if k.startswith("on") or k in ("integrity", "nonce", "ping", "srcdoc"):
                continue
            if v is None:
                out.append(k)
                continue
            if k == "action" and tag == "form":
                has_action = True
                a = _proxy_abs(self.base, v) or self.base
                out.append(f'action="/proxy/form"')
                out.append(f'data-to="{__import__("html").escape(a)}"')
                continue
            if k in self.URL_ATTRS:
                a = _proxy_abs(self.base, v)
                v = proxy_link(a) if a else ("#" if v.strip().lower().startswith("javascript:") else v)
            elif k in ("srcset", "imagesrcset"):
                parts = []
                for c in v.split(","):
                    bits = c.strip().split()
                    if bits:
                        a = _proxy_abs(self.base, bits[0])
                        if a:
                            parts.append(" ".join([proxy_link(a)] + bits[1:]))
                v = ", ".join(parts)
            elif k == "style":
                v = proxy_css(v, self.base)
            elif k == "target":
                continue
            out.append(f'{k}="{__import__("html").escape(v, quote=True)}"')
        if tag == "form" and not has_action:
            out.append('action="/proxy/form"')
            out.append(f'data-to="{__import__("html").escape(self.base)}"')
        return out

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if tag in self.DROP:
            if tag not in self.VOID:
                self.skip += 1
            return
        if self.skip:
            return
        if tag == "base":
            href = dict(attrs).get("href")
            a = _proxy_abs(self.base, href or "")
            if a:
                self.base = a
            return
        if tag == "meta":
            d = {k.lower(): (v or "") for k, v in attrs}
            if d.get("http-equiv", "").lower() in ("refresh", "content-security-policy", "set-cookie"):
                return
        if tag == "title":
            self._in_title = True
        if tag == "style":
            self.in_style = True
        a = self._attrs(tag, attrs)
        self.out.append("<" + tag + ("" if not a else " " + " ".join(a)) + ">")
        if tag == "form":
            to = next((x for x in a if x.startswith("data-to=")), None)
            if to:
                self.out.append(f'<input type="hidden" name="__u" value={to[8:]}>')
        if tag == "body":
            self.out.append("\x00BAR\x00")

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag in self.DROP:
            if tag not in self.VOID:
                self.skip = max(0, self.skip - 1)
            return
        if self.skip:
            return
        if tag == "title":
            self._in_title = False
        if tag == "style":
            self.in_style = False
        self.out.append(f"</{tag}>")

    def handle_data(self, data):
        if self.skip:
            return
        if self._in_title:
            self.title += data
        self.out.append(proxy_css(data, self.base) if self.in_style else data)

    def handle_entityref(self, name):
        if not self.skip:
            self.out.append(f"&{name};")

    def handle_charref(self, name):
        if not self.skip:
            self.out.append(f"&#{name};")

    def handle_comment(self, data):
        pass

    def handle_decl(self, decl):
        self.out.append(f"<!{decl}>")


def proxy_bar(url: str) -> str:
    esc = __import__("html").escape
    return ('<div style="all:initial;display:flex;gap:8px;align-items:center;position:sticky;top:0;z-index:2147483647;'
            'background:#f7f6f2;border-bottom:1px solid #d9d6cc;padding:8px 12px;font:14px system-ui,sans-serif;color:#1b1b1a">'
            '<a href="/" style="all:initial;font:600 14px system-ui,sans-serif;color:#1b1b1a;cursor:pointer">piii.app proxy</a>'
            '<form action="/proxy" method="get" style="all:initial;display:flex;flex:1;gap:6px">'
            f'<input name="u" value="{esc(url)}" style="all:initial;flex:1;font:14px system-ui,sans-serif;background:#fff;'
            'border:1px solid #d9d6cc;border-radius:8px;padding:6px 10px;color:#1b1b1a;min-width:0">'
            '<button style="all:initial;font:600 14px system-ui,sans-serif;background:#1b1b1a;color:#fff;border-radius:8px;'
            'padding:6px 12px;cursor:pointer">Go</button></form></div>')


def proxy_page(body: bytes, url: str, encoding: str) -> str:
    text = body.decode(encoding or "utf-8", errors="replace")
    p = _ProxyHTML(url)
    try:
        p.feed(text)
        p.close()
    except Exception:                                       # noqa: BLE001 — a broken page is shown as it parsed
        pass
    out = "".join(p.out)
    bar = proxy_bar(url)
    out = out.replace("\x00BAR\x00", bar, 1) if "\x00BAR\x00" in out else bar + out
    return out


def proxy_message(title: str, msg: str, url: str = "", status: int = 200) -> HTMLResponse:
    esc = __import__("html").escape
    doc = (f'<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
           f'<title>{esc(title)}</title><body style="margin:0;font:16px system-ui,sans-serif;background:#f7f6f2;color:#1b1b1a">'
           f'{proxy_bar(url)}<div style="max-width:640px;margin:40px auto;padding:0 16px"><h1 style="font-size:22px">{esc(title)}</h1>'
           f'<p>{esc(msg)}</p></div></body>')
    return HTMLResponse(doc, status_code=status, headers={"Content-Security-Policy": PROXY_CSP, "Cache-Control": "no-store",
                                                          "Referrer-Policy": "no-referrer", "X-Robots-Tag": "noindex, nofollow"})


def proxy_fetch(method: str, url: str, data: Optional[bytes] = None, ctype: str = ""):
    """(final url, response, body) through public addresses only, every redirect checked; or raises HTTPException."""
    session = requests.Session()
    session.trust_env = False
    headers = {"User-Agent": PROXY_UA, "Accept": "text/html,application/xhtml+xml,image/avif,image/webp,*/*;q=0.8",
               "Accept-Language": "en-GB,en;q=0.9,it;q=0.8"}
    if ctype:
        headers["Content-Type"] = ctype
    for _ in range(6):
        if not public_url(url):
            raise HTTPException(status_code=400, detail="Only public websites can be opened through the proxy.")
        try:
            res = session.request(method, url, headers=headers, data=data, timeout=PROXY_TIMEOUT,
                                  allow_redirects=False, stream=True)
        except requests.RequestException:
            raise HTTPException(status_code=502, detail="That site could not be reached.")
        if res.status_code in (301, 302, 303, 307, 308) and res.headers.get("Location"):
            nxt = urllib.parse.urljoin(url, res.headers["Location"])
            res.close()
            if res.status_code in (301, 302, 303):
                method, data = "GET", None
                headers.pop("Content-Type", None)
            url = nxt
            continue
        declared = res.headers.get("Content-Length", "")
        if declared.isdigit() and int(declared) > PROXY_MAX_BYTES:
            res.close()
            raise HTTPException(status_code=413, detail="That file is too large for the proxy (12 MB at most).")
        body = bytearray()
        try:
            for chunk in res.iter_content(chunk_size=65536):
                body.extend(chunk)
                if len(body) > PROXY_MAX_BYTES:
                    res.close()
                    raise HTTPException(status_code=413, detail="That file is too large for the proxy (12 MB at most).")
        except requests.RequestException:
            raise HTTPException(status_code=502, detail="That site stopped answering.")
        return url, res, bytes(body)
    raise HTTPException(status_code=508, detail="Too many redirects.")


def proxy_answer(request: Request, method: str, url: str, data: Optional[bytes] = None, ctype: str = ""):
    if not proxy_password():
        return proxy_message("The proxy is off", "The owner has not set a proxy password (PROXY_PASSWORD) on this server.", url, 403)
    if not proxy_allowed(request):
        return RedirectResponse("/#/proxy", status_code=303)
    url = proxy_target(url)
    if not url:
        return proxy_message("piii.app proxy", "Type an address above.")
    host = (urllib.parse.urlsplit(url).hostname or "").lower()
    own = (request.headers.get("host") or "").split(":")[0].lower()
    if host and (host == own or host.endswith("." + own) or host in ("piii.app", "www.piii.app")):
        return RedirectResponse("/", status_code=303)
    proxy_rate(request)
    try:
        final, res, body = proxy_fetch(method, url, data, ctype)
    except HTTPException as e:
        return proxy_message("Not opened", str(e.detail), url, e.status_code)
    kind = (res.headers.get("Content-Type") or "application/octet-stream").split(";")[0].strip().lower()
    common = {"Content-Security-Policy": PROXY_CSP, "Referrer-Policy": "no-referrer", "X-Content-Type-Options": "nosniff",
              "X-Robots-Tag": "noindex, nofollow", "Cache-Control": "private, max-age=300"}
    if kind in ("text/html", "application/xhtml+xml"):
        enc = res.encoding if res.encoding and "charset" in (res.headers.get("Content-Type") or "").lower() else None
        if not enc:
            m = re.search(rb'<meta[^>]+charset=["\']?([a-zA-Z0-9_-]+)', body[:4096], re.I)
            enc = m.group(1).decode() if m else "utf-8"
        try:
            page = proxy_page(body, final, enc)
        except LookupError:
            page = proxy_page(body, final, "utf-8")
        return HTMLResponse(page, status_code=res.status_code if res.status_code < 600 else 200, headers=common)
    if kind == "text/css":
        css = proxy_css(body.decode(res.encoding or "utf-8", errors="replace"), final)
        return Response(css, media_type="text/css", status_code=res.status_code, headers=common)
    if kind in ("application/javascript", "text/javascript", "application/x-javascript"):
        return Response(b"", media_type="text/javascript", headers=common)
    if kind == "image/svg+xml":
        common["Content-Disposition"] = "inline"
    return Response(body, media_type=kind, status_code=res.status_code, headers=common)


@proxy_router.get("/proxy", include_in_schema=False)
def proxy_get(request: Request, u: str = Query(default="")):
    return proxy_answer(request, "GET", u)


@proxy_router.get("/proxy/form", include_in_schema=False)
def proxy_form_get(request: Request):
    params = [(k, v) for k, v in request.query_params.multi_items() if k != "__u"]
    to = request.query_params.get("__u", "")
    if not to:
        return proxy_message("Not opened", "That form gave no address.")
    parts = urllib.parse.urlsplit(to)
    target = urllib.parse.urlunsplit((parts.scheme, parts.netloc, parts.path, urllib.parse.urlencode(params), ""))
    return proxy_answer(request, "GET", target)


@proxy_router.post("/proxy/form", include_in_schema=False)
async def proxy_form_post(request: Request):
    raw = await request.body()
    if len(raw) > 1024 * 1024:
        return proxy_message("Not sent", "That form is too large for the proxy.")
    ctype = request.headers.get("content-type", "")
    if "application/x-www-form-urlencoded" not in ctype:
        return proxy_message("Not sent", "Only simple forms work through the proxy (no file uploads).")
    pairs = urllib.parse.parse_qsl(raw.decode("utf-8", errors="replace"), keep_blank_values=True)
    to = next((v for k, v in pairs if k == "__u"), "")
    body = urllib.parse.urlencode([(k, v) for k, v in pairs if k != "__u"]).encode()
    if not to:
        return proxy_message("Not sent", "That form gave no address.")
    return proxy_answer(request, "POST", to, body, "application/x-www-form-urlencoded")


class ProxyEnter(BaseModel):
    password: str = ""


@proxy_router.get("/api/proxy/status")
def proxy_status(request: Request):
    return {"enabled": bool(proxy_password()), "allowed": proxy_allowed(request)}


@proxy_router.post("/api/proxy/enter")
def proxy_enter(payload: ProxyEnter, request: Request):
    check_rate_limit(get_client_ip(request), bucket="proxy_enter")
    pw = proxy_password()
    if not pw:
        raise HTTPException(status_code=403, detail="The proxy is off: no proxy password is set on this server.")
    if not hmac.compare_digest(payload.password.strip().encode(), pw.encode()):
        raise HTTPException(status_code=401, detail="That is not the proxy password.")
    r = JSONResponse({"allowed": True})
    secure = request.url.scheme == "https" or request.headers.get("x-forwarded-proto") == "https"
    r.set_cookie(PROXY_COOKIE, proxy_token(pw), max_age=60 * 60 * 24 * 30, httponly=True, samesite="lax", secure=secure, path="/")
    return r


@proxy_router.post("/api/proxy/leave")
def proxy_leave():
    r = JSONResponse({"allowed": False})
    r.delete_cookie(PROXY_COOKIE, path="/")
    return r


# ---------------------------------------------------------------------------
# piii VPN through Tailscale (owner, 2026-10-17: "can tailscale be integrated to my website" — "do it"). No router
# needed: the owner's computer runs Tailscale and offers itself as an exit node; piii.app shares that one device
# with each person invited, allowed as an exit node (Tailscale's device invites). They sign in to Tailscale with
# their own account, can reach nothing of the owner's but the way out, and do not count against the owner's plan.
#
# Settings (/etc/piii-site.env): TAILSCALE_API_KEY (tskey-api-…, made in Tailscale: Settings → Keys),
# TAILSCALE_TAILNET (default "-": the key's own), TAILSCALE_EXIT_NODE (the computer's name, if it is not found by
# itself), VPN_ADMIN_PASSWORD (to manage invites here; the site owner's signed session works too).
# ---------------------------------------------------------------------------
ts_router = APIRouter()
TS_API = "https://api.tailscale.com/api/v2"
TS_COOKIE = "pi_vpnadmin"
EXIT_ROUTES = ("0.0.0.0/0", "::/0")


def ts_key() -> str:
    return (os.getenv("TAILSCALE_API_KEY") or "").strip()


def ts_tailnet() -> str:
    return (os.getenv("TAILSCALE_TAILNET") or "-").strip() or "-"


def ts_admin_password() -> str:
    return (os.getenv("VPN_ADMIN_PASSWORD") or "").strip()


def ts_admin_token(pw: str) -> str:
    secret = os.getenv("SESSION_SECRET", "").strip() or pw
    return hmac.new(secret.encode(), ("vpnadmin:" + pw).encode(), hashlib.sha256).hexdigest()


def ts_is_admin(request: Request) -> bool:
    pw = ts_admin_password()
    got = request.cookies.get(TS_COOKIE) or ""
    if pw and got and hmac.compare_digest(got, ts_admin_token(pw)):
        return True
    try:
        return auth_is_owner(identity_from_request(request, ""))
    except Exception:                                      # noqa: BLE001
        return False


def ts_require_admin(request: Request):
    if not ts_is_admin(request):
        raise HTTPException(status_code=403, detail="Only the owner manages piii VPN. Enter the VPN admin password.")
    if not ts_key():
        raise HTTPException(status_code=503, detail="Tailscale is not connected: TAILSCALE_API_KEY is not set on the server.")


def ts_call(method: str, path: str, body=None):
    """Tailscale's API; its answer, or an HTTPException in plain words."""
    try:
        r = requests.request(method, TS_API + path, json=body, timeout=20,
                             headers={"Authorization": "Bearer " + ts_key(), "Accept": "application/json"})
    except requests.RequestException:
        raise HTTPException(status_code=502, detail="Tailscale could not be reached from the server.")
    if r.status_code == 401:
        raise HTTPException(status_code=502, detail="Tailscale refused the API key: it is wrong or expired (keys last at most 90 days). Make a new one.")
    if r.status_code == 403:
        raise HTTPException(status_code=502, detail="The Tailscale API key may not do this. Make it as an owner or admin of the tailnet.")
    if r.status_code >= 400:
        try:
            msg = r.json().get("message") or r.text
        except ValueError:
            msg = r.text
        raise HTTPException(status_code=502, detail=f"Tailscale said: {str(msg)[:300]}")
    if not r.content:
        return {}
    try:
        return r.json()
    except ValueError:
        return {}


def ts_exit_device(devices: list) -> Optional[dict]:
    """The owner's computer: the one named in TAILSCALE_EXIT_NODE, else the one offering itself as an exit node."""
    want = (os.getenv("TAILSCALE_EXIT_NODE") or "").strip().lower()
    if want:
        for d in devices:
            if want in ((d.get("hostname") or "").lower(), (d.get("name") or "").lower().split(".")[0]):
                return d
    for d in devices:
        if any(r in (d.get("advertisedRoutes") or []) for r in EXIT_ROUTES):
            return d
    host = socket.gethostname().lower()
    for d in devices:
        if (d.get("hostname") or "").lower() == host:
            return d
    return None


def ts_online(d: dict) -> bool:
    if d.get("connectedToControl") is not None:
        return bool(d.get("connectedToControl"))
    seen = d.get("lastSeen") or ""
    try:
        t = datetime.fromisoformat(seen.replace("Z", "+00:00"))
        return (datetime.now(timezone.utc) - t).total_seconds() < 300
    except ValueError:
        return False


def ts_names() -> dict:
    conn = get_db_connection()
    try:
        return {r[0]: r[1] for r in conn.execute("SELECT id, name FROM ts_invites").fetchall()}
    finally:
        conn.close()


class TsLogin(BaseModel):
    password: str = ""


class TsInvite(BaseModel):
    name: str = ""
    email: str = ""
    multi: bool = False


@ts_router.get("/api/ts/status")
def ts_status(request: Request):
    """Anyone: whether piii VPN runs through Tailscale here. The owner: the computer, and everyone invited."""
    out = {"configured": bool(ts_key()), "admin": ts_is_admin(request), "can_login": bool(ts_admin_password())}
    if not out["admin"] or not out["configured"]:
        return out
    devices = ts_call("GET", f"/tailnet/{ts_tailnet()}/devices?fields=all").get("devices", [])
    d = ts_exit_device(devices)
    if not d:
        out["exit_node"] = None
        out["devices_seen"] = [x.get("hostname") or x.get("name") for x in devices][:20]
        return out
    adv, ena = d.get("advertisedRoutes") or [], d.get("enabledRoutes") or []
    out["exit_node"] = {
        "id": d.get("nodeId") or d.get("id"), "name": d.get("hostname") or d.get("name"), "os": d.get("os"),
        "online": ts_online(d), "last_seen": d.get("lastSeen"),
        "offers_exit": all(r in adv for r in EXIT_ROUTES), "exit_approved": all(r in ena for r in EXIT_ROUTES),
    }
    names = ts_names()
    invites = ts_call("GET", f"/device/{out['exit_node']['id']}/device-invites")
    invites = invites if isinstance(invites, list) else invites.get("invites", [])
    out["invites"] = [{
        "id": i.get("id"), "name": names.get(str(i.get("id")), ""), "created": i.get("created"),
        "accepted": bool(i.get("accepted")), "by": ((i.get("acceptedBy") or {}).get("loginName") or ""),
        "email": i.get("email") or "", "multi": bool(i.get("multiUse")), "exit": bool(i.get("allowExitNode")),
        "url": "" if i.get("accepted") and not i.get("multiUse") else (i.get("inviteUrl") or ""),
    } for i in invites]
    return out


@ts_router.post("/api/ts/login")
def ts_login(payload: TsLogin, request: Request):
    check_rate_limit(get_client_ip(request), bucket="ts_login")
    pw = ts_admin_password()
    if not pw:
        raise HTTPException(status_code=403, detail="No VPN admin password is set on the server (VPN_ADMIN_PASSWORD).")
    if not hmac.compare_digest(payload.password.strip().encode(), pw.encode()):
        raise HTTPException(status_code=401, detail="That is not the VPN admin password.")
    r = JSONResponse({"admin": True})
    secure = request.url.scheme == "https" or request.headers.get("x-forwarded-proto") == "https"
    r.set_cookie(TS_COOKIE, ts_admin_token(pw), max_age=60 * 60 * 24 * 30, httponly=True, samesite="strict", secure=secure, path="/")
    return r


@ts_router.post("/api/ts/logout")
def ts_logout():
    r = JSONResponse({"admin": False})
    r.delete_cookie(TS_COOKIE, path="/")
    return r


@ts_router.post("/api/ts/approve-exit")
def ts_approve_exit(request: Request):
    """Lets the owner's computer be used as an exit node (it must offer itself: tailscale up --advertise-exit-node)."""
    ts_require_admin(request)
    devices = ts_call("GET", f"/tailnet/{ts_tailnet()}/devices?fields=all").get("devices", [])
    d = ts_exit_device(devices)
    if not d:
        raise HTTPException(status_code=404, detail="Your computer is not in Tailscale yet (run the commands on it first).")
    dev = d.get("nodeId") or d.get("id")
    routes = ts_call("GET", f"/device/{dev}/routes")
    adv = routes.get("advertisedRoutes") or []
    if not all(r in adv for r in EXIT_ROUTES):
        raise HTTPException(status_code=409, detail="Your computer does not offer itself as an exit node yet. On it: sudo tailscale set --advertise-exit-node")
    enabled = sorted(set((routes.get("enabledRoutes") or []) + list(EXIT_ROUTES)))
    ts_call("POST", f"/device/{dev}/routes", {"routes": enabled})
    add_log("piii VPN: the computer is approved as Tailscale exit node.")
    return {"approved": True}


@ts_router.post("/api/ts/invite")
def ts_invite(payload: TsInvite, request: Request):
    """A new invite: the owner's computer shared with one person, as an exit node. Its link goes to them."""
    ts_require_admin(request)
    name = re.sub(r"[\x00-\x1f]", "", payload.name).strip()[:60]
    email = payload.email.strip()[:200]
    if email and not re.fullmatch(r"[^@\s]+@[^@\s]+\.[^@\s]+", email):
        raise HTTPException(status_code=400, detail="That email address does not look right (or leave it empty for a link).")
    devices = ts_call("GET", f"/tailnet/{ts_tailnet()}/devices?fields=all").get("devices", [])
    d = ts_exit_device(devices)
    if not d:
        raise HTTPException(status_code=404, detail="Your computer is not in Tailscale yet (run the commands on it first).")
    one = {"multiUse": bool(payload.multi), "allowExitNode": True}
    if email:
        one["email"] = email
    got = ts_call("POST", f"/device/{d.get('nodeId') or d.get('id')}/device-invites", [one])
    inv = (got[0] if isinstance(got, list) and got else got) or {}
    iid = str(inv.get("id") or "")
    if iid:
        conn = get_db_connection()
        try:
            conn.execute("INSERT OR REPLACE INTO ts_invites (id, name, created_at) VALUES (?, ?, ?)",
                         (iid, name, datetime.now().isoformat(timespec="seconds")))
            conn.commit()
        finally:
            conn.close()
    add_log("piii VPN: an invite was made.")
    return {"id": iid, "url": inv.get("inviteUrl") or "", "emailed": bool(email), "name": name}


@ts_router.post("/api/ts/invite/{invite_id}/delete")
def ts_invite_delete(invite_id: str, request: Request):
    """The invite withdrawn, and with it the person's use of the computer."""
    ts_require_admin(request)
    if not re.fullmatch(r"[A-Za-z0-9_-]{1,80}", invite_id):
        raise HTTPException(status_code=400, detail="Not an invite.")
    ts_call("DELETE", f"/device-invites/{invite_id}")
    conn = get_db_connection()
    try:
        conn.execute("DELETE FROM ts_invites WHERE id=?", (invite_id,))
        conn.commit()
    finally:
        conn.close()
    add_log("piii VPN: an invite was withdrawn.")
    return {"deleted": invite_id}


# ---------------------------------------------------------------------------
# Tailscale for Android, from piii.app itself (owner, 2026-10-17: "put apk there"). Not a copy that goes stale: the
# server asks F-Droid (which builds the app from Tailscale's published source) for its current version at most once
# a day, downloads that APK when it is new, and serves it. Without the internet it serves the last one it has.
# ---------------------------------------------------------------------------
apk_router = APIRouter()
APK_PACKAGE = "com.tailscale.ipn"
APK_API = f"https://f-droid.org/api/v1/packages/{APK_PACKAGE}"
APK_URL = "https://f-droid.org/repo/" + APK_PACKAGE + "_{code}.apk"
APK_MAX = 200 * 1024 * 1024
APK_REFRESH = 24 * 3600
_apk_lock = threading.Lock()


def apk_dir() -> str:
    d = os.path.join(BASE_DIR, "downloads")
    os.makedirs(d, exist_ok=True)
    return d


def apk_meta() -> dict:
    try:
        with open(os.path.join(apk_dir(), "tailscale.json")) as f:
            return json.load(f)
    except (OSError, ValueError):
        return {}


def apk_save_meta(m: dict):
    path = os.path.join(apk_dir(), "tailscale.json")
    with open(path + ".tmp", "w") as f:
        json.dump(m, f)
    os.replace(path + ".tmp", path)


def apk_current() -> dict:
    """The APK on hand, fetched anew when F-Droid has a newer one (looked at once a day at most)."""
    with _apk_lock:
        m = apk_meta()
        path = os.path.join(apk_dir(), "tailscale.apk")
        have = bool(m) and os.path.exists(path)
        if have and time.time() - m.get("checked", 0) < APK_REFRESH:
            return m
        try:
            info = requests.get(APK_API, timeout=15).json()
            code = int(info["suggestedVersionCode"])
            name = next((p.get("versionName", "") for p in info.get("packages", []) if p.get("versionCode") == code), "")
        except (requests.RequestException, ValueError, KeyError, TypeError):
            if have:
                return m
            raise HTTPException(status_code=503, detail="F-Droid could not be reached to fetch the app. Try again later.")
        if have and m.get("code") == code:
            m["checked"] = time.time()
            apk_save_meta(m)
            return m
        tmp = path + ".part"
        h = hashlib.sha256()
        size = 0
        try:
            with requests.get(APK_URL.format(code=code), timeout=60, stream=True) as r:
                r.raise_for_status()
                with open(tmp, "wb") as f:
                    for chunk in r.iter_content(chunk_size=1 << 16):
                        size += len(chunk)
                        if size > APK_MAX:
                            raise ValueError("too large")
                        h.update(chunk)
                        f.write(chunk)
            with open(tmp, "rb") as f:
                if f.read(4) != b"PK\x03\x04" or size < 1_000_000:
                    raise ValueError("not an APK")
        except (requests.RequestException, ValueError, OSError):
            try:
                os.remove(tmp)
            except OSError:
                pass
            if have:
                return m
            raise HTTPException(status_code=503, detail="The app could not be downloaded from F-Droid. Try again later.")
        os.replace(tmp, path)
        m = {"code": code, "version": name, "size": size, "sha256": h.hexdigest(), "checked": time.time(), "fetched": time.time()}
        apk_save_meta(m)
        add_log(f"Tailscale for Android {name} fetched from F-Droid ({size // 1_000_000} MB).")
        return m


@apk_router.get("/downloads/tailscale.apk", include_in_schema=False)
def apk_download():
    m = apk_current()
    version = re.sub(r"[^A-Za-z0-9._-]", "", m.get("version", "").split("-")[0]) or "latest"
    return FileResponse(os.path.join(apk_dir(), "tailscale.apk"), media_type="application/vnd.android.package-archive",
                        filename=f"tailscale-{version}.apk", headers={"Cache-Control": "no-cache", "X-Content-Type-Options": "nosniff"})


@apk_router.get("/api/downloads/tailscale")
def apk_info():
    """What /downloads/tailscale.apk is now (without fetching anything)."""
    m = apk_meta()
    return {"version": m.get("version", ""), "size": m.get("size", 0), "sha256": m.get("sha256", ""),
            "source": "https://f-droid.org/packages/" + APK_PACKAGE + "/"}


# ==============================================================================================================
# Photos on this server, for Face Mace, behind a password (owner, 2026-10-17: "the passworded portal from face mace
# to these photos"). A folder on the machine the site runs on (SERVER_PHOTOS_DIR, e.g. /mnt/photos) is offered to
# Face Mace as "Your photos on this server": /photos asks for PHOTOS_PASSWORD once and keeps a cookie; the list and
# the files are read-only, and only from inside that folder.
# ==============================================================================================================
PHOTOS_COOKIE = "pi_photos"
PHOTOS_MEDIA = re.compile(r"\.(jpe?g|png|gif|webp|heic|heif|bmp|tiff?|avif|mp4|mov|m4v|webm|avi|mkv|3gp)$", re.I)
PHOTOS_SKIP = re.compile(r"^(\$RECYCLE\.BIN|System Volume Information|FOUND\.\d+|\..*|~\$.*|lost\+found)$", re.I)
PHOTOS_MAX = 100_000
photos_router = APIRouter()


def photos_root() -> Optional[str]:
    d = (os.getenv("SERVER_PHOTOS_DIR") or "").strip()
    return os.path.realpath(d) if d and os.path.isdir(d) else None


# A strong password (owner, 2026-10-17: "a stronger password, SHA-256, or very strong"): kept on the server only as a
# salted PBKDF2-HMAC-SHA256 hash of 600,000 rounds (PHOTOS_PASSWORD_HASH, as photos_hash makes it),
# at least 12 characters; ten wrong tries from one address lock it out for 15 minutes. A plain PHOTOS_PASSWORD still
# works, so a server set up before keeps working.
PHOTOS_ROUNDS = 600_000
PHOTOS_MIN_LEN = 12


def photos_hash(pw: str, salt: Optional[bytes] = None, rounds: int = PHOTOS_ROUNDS) -> str:
    salt = salt or secrets.token_bytes(16)
    dk = hashlib.pbkdf2_hmac("sha256", pw.encode(), salt, rounds)
    return "pbkdf2_sha256${}${}${}".format(rounds, base64.b64encode(salt).decode(), base64.b64encode(dk).decode())


def photos_password() -> str:
    """What the password is checked against: its hash (or, set up the old way, the password itself). Empty: no portal."""
    return (os.getenv("PHOTOS_PASSWORD_HASH") or "").strip() or (os.getenv("PHOTOS_PASSWORD") or "").strip()


def photos_check(got: str) -> bool:
    h = (os.getenv("PHOTOS_PASSWORD_HASH") or "").strip()
    if h:
        try:
            algo, rounds, salt, want = h.split("$")
            if algo != "pbkdf2_sha256":
                return False
            dk = hashlib.pbkdf2_hmac("sha256", got.encode(), base64.b64decode(salt), int(rounds))
            return hmac.compare_digest(dk, base64.b64decode(want))
        except (ValueError, TypeError):
            logging.warning("photos: PHOTOS_PASSWORD_HASH is not a pbkdf2_sha256 hash")
            return False
    pw = (os.getenv("PHOTOS_PASSWORD") or "").strip()
    return bool(pw) and hmac.compare_digest(got.encode(), pw.encode())


def photos_token(pw: str) -> str:
    secret = os.getenv("SESSION_SECRET", "").strip() or pw
    return hmac.new(secret.encode(), ("photos:" + pw).encode(), hashlib.sha256).hexdigest()


def photos_allowed(request: Request) -> bool:
    pw = photos_password()
    got = request.cookies.get(PHOTOS_COOKIE) or ""
    return bool(pw) and bool(got) and hmac.compare_digest(got, photos_token(pw))


_PHOTOS_FAILS: Dict[str, List[float]] = {}
PHOTOS_LOCK_TRIES, PHOTOS_LOCK_SECONDS = 10, 900


def _photos_locked(ip: str) -> bool:
    now = time.time()
    tries = [t for t in _PHOTOS_FAILS.get(ip, []) if now - t < PHOTOS_LOCK_SECONDS]
    _PHOTOS_FAILS[ip] = tries
    if len(_PHOTOS_FAILS) > 5000:  # never grows without end
        for k in list(_PHOTOS_FAILS)[:1000]:
            _PHOTOS_FAILS.pop(k, None)
    return len(tries) >= PHOTOS_LOCK_TRIES


def photos_guard(request: Request) -> str:
    root = photos_root()
    if not root or not photos_password():
        raise HTTPException(status_code=404, detail="No photos are offered on this server.")
    if not photos_allowed(request):
        raise HTTPException(status_code=401, detail="Enter the photos password first, at /photos.")
    return root


def _photos_page(title: str, body: str, status: int = 200) -> HTMLResponse:
    return HTMLResponse(
        '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
        f'<title>{html.escape(title)}</title><link rel="icon" href="/icon.svg"><style>'
        "body{margin:0;min-height:100vh;display:grid;place-items:center;background:#f7f5ef;color:#1d1d1b;"
        "font:16px/1.5 system-ui,-apple-system,Segoe UI,sans-serif}"
        "main{width:min(380px,calc(100vw - 32px));text-align:center}h1{font-size:28px;margin:0 0 6px}"
        "p{color:#6b6963;margin:0 0 20px}form{display:flex;gap:8px}"
        "input{flex:1;min-width:0;font:inherit;padding:12px 14px;border:1.5px solid #2b2b2b;border-radius:14px;background:#fff}"
        "button{font:inherit;font-weight:600;padding:12px 18px;border:0;border-radius:14px;background:#2b2b2b;color:#fff;cursor:pointer}"
        ".bad{color:#b42318}</style><main>" + body + "</main></html>", status_code=status)


@photos_router.get("/photos", include_in_schema=False)
def photos_gate(request: Request, wrong: int = 0):
    if not photos_root() or not photos_password():
        return _photos_page("Photos", "<h1>No photos here</h1><p>This server does not offer a photo folder.</p>", 404)
    if photos_allowed(request):
        return RedirectResponse("/photos/browse", status_code=303)
    return _photos_page("Photos", "<h1>Photos</h1><p>Enter the password to see the photos on this server.</p>"
                        + ('<p class="bad">That password is not right.</p>' if wrong else "")
                        + '<form method="post" action="/photos"><input type="password" name="password" autocomplete="current-password" '
                          'aria-label="Password" autofocus required><button>Open</button></form>')


@photos_router.post("/photos", include_in_schema=False)
async def photos_enter(request: Request):
    form = await request.form()
    pw = photos_password()
    got = str(form.get("password") or "").strip()[:200]
    ip = client_ip(request)
    if _photos_locked(ip):
        return _photos_page("Photos", "<h1>Wait a while</h1><p>Too many wrong passwords from here. Try again in 15 "
                            "minutes.</p>", 429)
    if not pw or not await run_in_threadpool(photos_check, got):
        _PHOTOS_FAILS.setdefault(ip, []).append(time.time())
        logging.warning("photos: wrong password from %s", ip)
        await asyncio.sleep(1.5)  # a wrong guess costs time, so guessing many is slow
        return RedirectResponse("/photos?wrong=1", status_code=303)
    _PHOTOS_FAILS.pop(ip, None)
    r = RedirectResponse("/photos/browse", status_code=303)
    r.set_cookie(PHOTOS_COOKIE, photos_token(pw), max_age=30 * 86400, httponly=True, samesite="lax",
                 secure=request.url.scheme == "https")
    return r


_PHOTOS_IX: Dict = {"at": 0.0, "root": "", "items": []}
_PHOTOS_IX_LOCK = threading.Lock()
PHOTOS_VIDEO = re.compile(r"\.(mp4|mov|m4v|webm|avi|mkv|3gp)$", re.I)


def photos_index(root: str) -> List[Dict]:
    """Every photo and video under the folder, newest walk kept 10 minutes (a USB disk of 100,000 photos is slow to
    walk): system folders, hidden files and anything not a photo or video left out."""
    with _PHOTOS_IX_LOCK:
        if _PHOTOS_IX["root"] == root and time.time() - _PHOTOS_IX["at"] < 600:
            return _PHOTOS_IX["items"]
        out: List[Dict] = []
        for d, dirs, files in os.walk(root):
            dirs[:] = sorted(x for x in dirs if not PHOTOS_SKIP.match(x))
            for f in sorted(files):
                if PHOTOS_SKIP.match(f) or not PHOTOS_MEDIA.search(f):
                    continue
                full = os.path.join(d, f)
                try:
                    st_ = os.stat(full)
                except OSError:
                    continue
                out.append({"rel": os.path.relpath(full, root).replace(os.sep, "/"), "size": st_.st_size,
                            "mtime": int(st_.st_mtime * 1000), "type": mimetypes.guess_type(f)[0] or ""})
                if len(out) >= PHOTOS_MAX:
                    break
            if len(out) >= PHOTOS_MAX:
                break
        _PHOTOS_IX.update(at=time.time(), root=root, items=out)
        return out


@photos_router.get("/api/photos/list")
def photos_list(request: Request):
    """Every photo and video under the folder (system folders and hidden files left out), for Face Mace."""
    root = photos_guard(request)
    items = photos_index(root)
    return {"photos": [{"id": hashlib.sha1(x["rel"].encode()).hexdigest()[:24], "name": x["rel"], "size": x["size"],
                        "mtime": x["mtime"], "type": x["type"], "url": "/api/photos/file/" + urllib.parse.quote(x["rel"])}
                       for x in items], **({"more": True} if len(items) >= PHOTOS_MAX else {})}


@photos_router.get("/api/photos/page")
def photos_page(request: Request, offset: int = 0, limit: int = 240, folder: str = "", refresh: int = 0):
    """A page of the photos, for the preview: in a folder (and the folders under it) or all, by name."""
    root = photos_guard(request)
    if refresh:
        _PHOTOS_IX["at"] = 0.0
    items = photos_index(root)
    folder = folder.strip("/")
    sel = [x for x in items if not folder or x["rel"].startswith(folder + "/")]
    # the folders one level down from where you are, with how many are in each
    counts: Dict[str, int] = {}
    depth = len(folder.split("/")) if folder else 0
    for x in sel:
        parts = x["rel"].split("/")
        if len(parts) > depth + 1:
            k = "/".join(parts[: depth + 1])
            counts[k] = counts.get(k, 0) + 1
    limit = max(1, min(limit, 600))
    page = sel[max(0, offset): max(0, offset) + limit]
    return {"total": len(sel), "all": len(items), "folder": folder,
            "folders": [{"path": k, "count": v} for k, v in sorted(counts.items())],
            "items": [{"name": x["rel"], "size": x["size"], "mtime": x["mtime"],
                       "video": bool(PHOTOS_VIDEO.search(x["rel"])),
                       "url": "/api/photos/file/" + urllib.parse.quote(x["rel"]),
                       "thumb": "/api/photos/thumb/" + urllib.parse.quote(x["rel"])} for x in page]}


_THUMB_GATE = threading.BoundedSemaphore(4)


def _photos_inside(root: str, rel: str) -> Optional[str]:
    full = os.path.realpath(os.path.join(root, rel))
    # never outside the folder (a ../ or a link out of it is refused)
    if not (full == root or full.startswith(root + os.sep)) or not os.path.isfile(full) or not PHOTOS_MEDIA.search(full):
        return None
    return full


@photos_router.get("/api/photos/thumb/{rel:path}")
def photos_thumb(request: Request, rel: str):
    """A small preview of a photo (made once, kept on the server's disk); 404 for a video or what can't be read."""
    root = photos_guard(request)
    full = _photos_inside(root, rel)
    if not full or PHOTOS_VIDEO.search(full):
        raise HTTPException(status_code=404, detail="No preview.")
    st_ = os.stat(full)
    key = hashlib.sha1(f"{full}|{st_.st_size}|{int(st_.st_mtime)}".encode()).hexdigest()
    tdir = os.path.join(BASE_DIR, "photo-thumbs", key[:2])
    tpath = os.path.join(tdir, key + ".jpg")
    headers = {"Cache-Control": "private, max-age=2592000, immutable"}
    if os.path.isfile(tpath):
        return FileResponse(tpath, media_type="image/jpeg", headers=headers)
    try:
        from PIL import Image, ImageOps
    except ImportError:
        raise HTTPException(status_code=404, detail="Previews need Pillow on the server.")
    if full.lower().endswith((".heic", ".heif")):
        try:
            import pillow_heif
            pillow_heif.register_heif_opener()
        except ImportError:
            raise HTTPException(status_code=404, detail="HEIC previews need pillow-heif on the server.")
    with _THUMB_GATE:
        if not os.path.isfile(tpath):
            try:
                with Image.open(full) as im:
                    im.draft("RGB", (640, 640))  # a JPEG is read at a fraction of its size: far faster
                    im = ImageOps.exif_transpose(im)
                    im.thumbnail((360, 360))
                    os.makedirs(tdir, exist_ok=True)
                    tmp = tpath + ".tmp"
                    im.convert("RGB").save(tmp, "JPEG", quality=78, optimize=True)
                    os.replace(tmp, tpath)
            except Exception as e:                       # noqa: BLE001 -- a broken photo has no preview
                logging.info("photos: no preview for %s: %s", rel, e)
                raise HTTPException(status_code=404, detail="No preview.")
    return FileResponse(tpath, media_type="image/jpeg", headers=headers)


