# ---------------------------------------------------------------------------
# Super AI icons: when a super shrinks to an icon, Super AI draws its icon from its name (owner, 2026-10-14). The
# judge model is asked for a small line drawing as SVG path data only; the paths are checked character by character
# and the page builds the <svg> itself, so nothing the model writes is ever run or inserted as markup. Icons are kept
# on disk, so each name is drawn once for every visitor.
# ---------------------------------------------------------------------------
ICON_NAME_MAX = 48
ICON_MAX_PATHS = 6
ICON_PATH_MAX = 400
ICON_NEW_PER_REQUEST = 3
_ICON_PATH_RE = re.compile(r"^[MmLlHhVvCcSsQqTtAaZz0-9.,\-\s]+$")
_ICON_LOCK = threading.Lock()


def icon_name(raw) -> str:
    """A super's name as the icon key: printable, single-spaced, at most 48 characters."""
    name = " ".join("".join(ch for ch in str(raw or "") if ch.isprintable()).split())
    return name[:ICON_NAME_MAX]


def icon_paths(reply) -> Optional[List[str]]:
    """The paths of a model's icon reply, or None when they are not plain path data in a 24 x 24 box."""
    paths = reply.get("paths") if isinstance(reply, dict) else None
    if not isinstance(paths, list) or not paths:
        return None
    out = []
    for d in paths[:ICON_MAX_PATHS]:
        d = " ".join(str(d or "").split())
        if not d or len(d) > ICON_PATH_MAX or not _ICON_PATH_RE.match(d) or d[0] not in "Mm":
            return None
        nums = [float(x) for x in re.findall(r"-?\d*\.?\d+", d)]
        if any(abs(v) > 48 for v in nums):
            return None
        out.append(d)
    return out


def icon_prompt(name: str) -> str:
    return ("Draw a simple, recognisable line icon for a button labelled " + json.dumps(name) + ". "
            "Use a 24 x 24 grid, stroke only (no fill), in the style of Lucide or Feather icons: one to five SVG "
            "paths with absolute commands (M, L, H, V, C, Q, A, Z) and coordinates between 2 and 22. "
            'Reply with JSON only: {"paths": ["M...", "..."]}')


def _icons_file() -> str:
    return os.path.join(BASE_DIR, "super_icons.json")


def icons_load() -> Dict[str, List[str]]:
    try:
        with open(_icons_file(), "r", encoding="utf-8") as fh:
            data = json.load(fh)
        return {k: v for k, v in data.items() if isinstance(k, str) and icon_paths({"paths": v})}
    except (OSError, ValueError, AttributeError):
        return {}


def icons_store(name: str, paths: List[str]) -> None:
    with _ICON_LOCK:
        data = icons_load()
        data[name] = paths
        tmp = _icons_file() + ".tmp"
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(data, fh)
        os.replace(tmp, _icons_file())


def super_icons_build_router(draw: Callable[[str], Optional[List[str]]], rate_limit: Callable[[Request], None],
                             load: Callable[[], Dict[str, List[str]]] = icons_load,
                             store: Callable[[str, List[str]], None] = icons_store,
                             allowed: Callable[[Request], bool] = lambda r: True) -> APIRouter:
    router = APIRouter(prefix="/api/super", tags=["super"])

    @router.post("/icons")
    def icons(body: Dict[str, Any], request: Request):
        names = []
        for raw in (body.get("names") or [])[:24] if isinstance(body, dict) else []:
            n = icon_name(raw)
            if n and n not in names:
                names.append(n)
        have = load()
        out = {n: have[n] for n in names if n in have}
        missing = [n for n in names if n not in out]
        failed: List[str] = []
        if missing and not allowed(request):
            return {"icons": out, "pending": [], "failed": missing}
        todo = missing[:ICON_NEW_PER_REQUEST]
        if todo:
            rate_limit(request)
            with concurrent.futures.ThreadPoolExecutor(max_workers=len(todo)) as pool:
                drawn = list(pool.map(lambda n: (n, draw(n)), todo))
            for n, paths in drawn:
                if paths:
                    out[n] = paths
                    try:
                        store(n, paths)
                    except OSError as e:
                        logging.warning("Super icons: could not keep %r: %s", n, e)
                else:
                    failed.append(n)
        return {"icons": out, "pending": missing[ICON_NEW_PER_REQUEST:], "failed": failed}

    return router


def _super_draw_icon(name: str) -> Optional[List[str]]:
    try:
        return icon_paths(_super_judge(icon_prompt(name)) or {})
    except Exception as e:                               # noqa: BLE001 -- a failed drawing leaves the initials
        logging.warning("Super icons: drawing %r failed: %s", name, e)
        return None


app.include_router(super_icons_build_router(
    draw=_super_draw_icon,
    rate_limit=lambda request: check_rate_limit(get_client_ip(request), bucket="sp-icons"),
    # the judge is an outside model: not for a visitor who said no to outside providers
    allowed=lambda request: not declined(request, "ext")))


# ---------------------------------------------------------------------------
# Intern: Assist Diagnosis, on the web (owner, 2026-10-14: "write the whole assist diagnosis intern app on the web app
# itself"). Patients and their files never reach this server: they stay in the doctor's browser. What lives here is
# what needs two people: doctors' profiles (to be found), their messages, and the signals that set up a call between
# two browsers (the call itself goes browser to browser). A case sent for a differential is stripped of what could
# identify the patient, here as well as in the page, and goes to the Super AI panel only with the doctor's consent.
# ---------------------------------------------------------------------------
INTERN_TEXT_MAX = 2000
INTERN_SIGNAL_MAX = 20000
INTERN_CASE_MAX = 6000
INTERN_ONLINE_SECONDS = 60
INTERN_SIGNAL_TTL = 120
_INTERN_SIGNAL_KINDS = ("offer", "answer", "ice", "hangup", "decline")

_DEID_RULES = [
    (re.compile(r"[\w.+-]+@[\w-]+(\.[\w-]+)+"), "[email]"),
    (re.compile(r"https?://\S+|www\.\S+", re.I), "[link]"),
    (re.compile(r"\b\d{1,4}[-/.]\d{1,2}[-/.]\d{1,4}\b"), "[date]"),
    (re.compile(r"(?<![\w.])\+?\d[\d\s().-]{6,}\d"), "[number]"),
    (re.compile(r"\b[A-Z]{1,3}\d{5,}\b|\b\d{5,}\b"), "[id]"),
]


def intern_deidentify(text: str) -> str:
    """A case as it may leave the site: addresses, links, dates, phone and record numbers taken out."""
    out = str(text or "")[:INTERN_CASE_MAX]
    for rx, sub in _DEID_RULES:
        out = rx.sub(sub, out)
    return out.strip()


def intern_diagnosis_question(case: str) -> str:
    return ("A doctor asks for help with a case. Give a short differential diagnosis: the most likely diagnoses in "
            "order, each with the one finding that supports it, then the next tests or questions that would tell "
            "them apart, and any red flag that needs urgent care. This supports a doctor's judgement and is not a "
            "diagnosis.\n\nCASE:\n" + case)


def _intern_db(path: str):
    c = sqlite3.connect(path, timeout=10)
    c.execute("CREATE TABLE IF NOT EXISTS doctors (key TEXT PRIMARY KEY, name TEXT NOT NULL, specialty TEXT, place TEXT,"
              " bio TEXT, listed INTEGER NOT NULL DEFAULT 1, seen REAL NOT NULL DEFAULT 0)")
    c.execute("CREATE TABLE IF NOT EXISTS messages (id INTEGER PRIMARY KEY AUTOINCREMENT, frm TEXT NOT NULL,"
              " to_ TEXT NOT NULL, text TEXT NOT NULL, at REAL NOT NULL)")
    c.execute("CREATE INDEX IF NOT EXISTS messages_pair ON messages (frm, to_, id)")
    c.execute("CREATE TABLE IF NOT EXISTS signals (id INTEGER PRIMARY KEY AUTOINCREMENT, frm TEXT NOT NULL,"
              " to_ TEXT NOT NULL, kind TEXT NOT NULL, data TEXT NOT NULL, at REAL NOT NULL)")
    return c


def _clean(v, n: int) -> str:
    return "".join(ch for ch in str(v or "") if ch.isprintable() or ch == "\n")[:n].strip()


def intern_build_router(db_path: str, who: Callable[[Request], str], rate_limit: Callable[[Request], None],
                        panel: Callable[[str], Dict], allowed: Callable[[Request], bool] = lambda r: True,
                        now: Callable[[], float] = time.time) -> APIRouter:
    """`who(request)` is the signed-in doctor's key (or raises); `panel(question)` asks the Super AI panel."""
    router = APIRouter(prefix="/api/intern", tags=["intern"])

    def db():
        return _intern_db(db_path)

    def doctor_row(r) -> Dict:
        return {"key": r[0], "name": r[1], "specialty": r[2] or "", "place": r[3] or "", "bio": r[4] or "",
                "listed": bool(r[5]), "online": now() - (r[6] or 0) < INTERN_ONLINE_SECONDS}

    def me_row(c, key: str):
        return c.execute("SELECT key, name, specialty, place, bio, listed, seen FROM doctors WHERE key = ?", (key,)).fetchone()

    def seen(c, key: str) -> None:
        c.execute("UPDATE doctors SET seen = ? WHERE key = ?", (now(), key))

    @router.get("/me")
    def me(request: Request):
        key = who(request)
        with db() as c:
            r = me_row(c, key)
            if r:
                seen(c, key)
        return {"key": key, "doctor": doctor_row(r) if r else None}

    @router.put("/me")
    def save_me(body: Dict[str, Any], request: Request):
        key = who(request)
        name = _clean(body.get("name"), 80)
        if len(name) < 2:
            raise HTTPException(status_code=400, detail="Write your name: colleagues find you by it.")
        vals = (name, _clean(body.get("specialty"), 80), _clean(body.get("place"), 80), _clean(body.get("bio"), 500),
                1 if body.get("listed", True) else 0, now(), key)
        with db() as c:
            if me_row(c, key):
                c.execute("UPDATE doctors SET name=?, specialty=?, place=?, bio=?, listed=?, seen=? WHERE key=?", vals)
            else:
                c.execute("INSERT INTO doctors (name, specialty, place, bio, listed, seen, key) VALUES (?,?,?,?,?,?,?)", vals)
            return {"doctor": doctor_row(me_row(c, key))}

    @router.delete("/me")
    def delete_me(request: Request):
        key = who(request)
        with db() as c:
            c.execute("DELETE FROM doctors WHERE key = ?", (key,))
            c.execute("DELETE FROM messages WHERE frm = ? OR to_ = ?", (key, key))
            c.execute("DELETE FROM signals WHERE frm = ? OR to_ = ?", (key, key))
        return {"deleted": True}

    def need_doctor(c, key: str) -> None:
        if not me_row(c, key):
            raise HTTPException(status_code=403, detail="Make your doctor's profile first.")

    @router.get("/doctors")
    def doctors(request: Request, q: str = ""):
        key = who(request)
        words = [w for w in (q or "").lower().split() if w][:5]
        with db() as c:
            rows = c.execute("SELECT key, name, specialty, place, bio, listed, seen FROM doctors WHERE listed = 1 AND key != ?"
                             " ORDER BY seen DESC LIMIT 500", (key,)).fetchall()
        out = [doctor_row(r) for r in rows]
        if words:
            out = [d for d in out if all(w in (d["name"] + " " + d["specialty"] + " " + d["place"]).lower() for w in words)]
        return {"doctors": out[:100]}

    @router.get("/conversations")
    def conversations(request: Request):
        key = who(request)
        with db() as c:
            rows = c.execute(
                "SELECT CASE WHEN frm = ? THEN to_ ELSE frm END AS peer, MAX(id) FROM messages WHERE frm = ? OR to_ = ?"
                " GROUP BY peer ORDER BY MAX(id) DESC LIMIT 100", (key, key, key)).fetchall()
            out = []
            for peer, last in rows:
                m = c.execute("SELECT frm, text, at FROM messages WHERE id = ?", (last,)).fetchone()
                d = me_row(c, peer)
                out.append({"key": peer, "name": d[1] if d else "A doctor who left", "online": bool(d) and now() - (d[6] or 0) < INTERN_ONLINE_SECONDS,
                            "last": m[1][:140], "mine": m[0] == key, "at": m[2], "id": last})
        return {"conversations": out}

    @router.get("/messages")
    def messages(request: Request, peer: str = "", after: int = 0):
        key = who(request)
        with db() as c:
            seen(c, key)
            rows = c.execute("SELECT id, frm, text, at FROM messages WHERE ((frm = ? AND to_ = ?) OR (frm = ? AND to_ = ?)) AND id > ?"
                             " ORDER BY id DESC LIMIT 200", (key, peer, peer, key, max(0, int(after)))).fetchall()
        return {"messages": [{"id": r[0], "mine": r[1] == key, "text": r[2], "at": r[3]} for r in reversed(rows)]}

    @router.post("/messages")
    def send(body: Dict[str, Any], request: Request):
        key = who(request)
        rate_limit(request)
        text = _clean(body.get("text"), INTERN_TEXT_MAX)
        to = str(body.get("to") or "")
        if not text:
            raise HTTPException(status_code=400, detail="Write a message first.")
        with db() as c:
            need_doctor(c, key)
            if not me_row(c, to) or to == key:
                raise HTTPException(status_code=404, detail="No such doctor.")
            cur = c.execute("INSERT INTO messages (frm, to_, text, at) VALUES (?,?,?,?)", (key, to, text, now()))
            seen(c, key)
            return {"id": cur.lastrowid}

    @router.post("/signal")
    def signal(body: Dict[str, Any], request: Request):
        key = who(request)
        kind = str(body.get("kind") or "")
        to = str(body.get("to") or "")
        data = str(body.get("data") or "")[:INTERN_SIGNAL_MAX]
        if kind not in _INTERN_SIGNAL_KINDS:
            raise HTTPException(status_code=400, detail="Unknown signal.")
        with db() as c:
            need_doctor(c, key)
            if not me_row(c, to) or to == key:
                raise HTTPException(status_code=404, detail="No such doctor.")
            c.execute("DELETE FROM signals WHERE at < ?", (now() - INTERN_SIGNAL_TTL,))
            cur = c.execute("INSERT INTO signals (frm, to_, kind, data, at) VALUES (?,?,?,?,?)", (key, to, kind, data, now()))
            return {"id": cur.lastrowid}

    @router.get("/signals")
    def signals(request: Request, after: int = 0):
        key = who(request)
        with db() as c:
            seen(c, key)
            # the newest id first, then only what is at or below it: a signal written between the two reads is
            # then picked up by the next poll instead of being skipped over
            top = c.execute("SELECT COALESCE(MAX(id), 0) FROM signals").fetchone()[0]
            rows = c.execute("SELECT s.id, s.frm, s.kind, s.data, d.name FROM signals s LEFT JOIN doctors d ON d.key = s.frm"
                             " WHERE s.to_ = ? AND s.id > ? AND s.id <= ? AND s.at > ? ORDER BY s.id LIMIT 100",
                             (key, max(0, int(after)), top, now() - INTERN_SIGNAL_TTL)).fetchall()
            last = rows[-1][0] if len(rows) == 100 else top
        return {"signals": [{"id": r[0], "from": r[1], "kind": r[2], "data": r[3], "name": r[4] or ""} for r in rows],
                "last": last}

    @router.post("/diagnose")
    def diagnose(body: Dict[str, Any], request: Request):
        if not body.get("consent"):
            raise HTTPException(status_code=400, detail="Tick that the case may go to outside AI models first.")
        if not allowed(request):
            raise HTTPException(status_code=403, detail=WHY["ext"])
        case = intern_deidentify(body.get("case"))
        if len(case) < 20:
            raise HTTPException(status_code=400, detail="Describe the case first: the presentation, history and findings.")
        rate_limit(request)
        res = panel(intern_diagnosis_question(case))
        return {"sent": case, "text": panel_text(res), **res}

    return router


def _intern_who(request: Request) -> str:
    ident = require_identity(request)
    return _profile_key(ident.get("wallet", ""), ident.get("orcid", ""))


app.include_router(intern_build_router(
    db_path=os.path.join(BASE_DIR, "intern.db"),
    who=_intern_who,
    rate_limit=lambda request: check_rate_limit(get_client_ip(request), bucket="intern"),
    panel=lambda q: run_panel(q, "", _super_jurors(), _super_ask_juror, _super_judge),
    allowed=lambda request: not declined(request, "ext")))


# ---------------------------------------------------------------------------
# 9. Serve the frontend (single-page static app)
# ---------------------------------------------------------------------------
_FRONTEND_DIR = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "front")

def rust_loader(intern: bool = False, facemace: bool = False) -> str:
    """The document every page address gets: the front end is Rust (back/rust/ui, built to front/app/ui.wasm).

    A browser has to be handed a document before it will run anything, so this is the least one can be: a
    character set, a viewport and the script that starts the WebAssembly. Every view, word and style is drawn by
    the Rust code. The version is the content of the two files, so a new build is fetched at once and an
    unchanged one comes from the cache.
    """
    h = hashlib.sha256()
    for name in ("host.js", "ui.wasm"):
        with open(os.path.join(_FRONTEND_DIR, "app", name), "rb") as fh:
            h.update(fh.read())
    if intern:
        # Intern as an app of its own (owner, 2026-10-15: "a new page ... like an iPhone app or Android app"): the
        # same program, which sees /intern/ and shows only Intern; installable from the browser's menu ("Add to Home
        # Screen"), full screen, and it opens without a network (the service worker keeps its files)
        return ('<!doctype html><html lang="en"><meta charset="utf-8">'
                '<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no,viewport-fit=cover">'
                '<title>Intern</title><meta name="theme-color" content="#2f40e8">'
                '<meta name="apple-mobile-web-app-capable" content="yes"><meta name="mobile-web-app-capable" content="yes">'
                '<meta name="apple-mobile-web-app-status-bar-style" content="default"><meta name="apple-mobile-web-app-title" content="Intern">'
                '<link rel="icon" href="/intern/icon-192.png"><link rel="apple-touch-icon" href="/intern/apple-touch-icon.png">'
                '<link rel="manifest" href="/intern/manifest.webmanifest">'
                f'<script type="module" src="/app/host.js?v={h.hexdigest()[:12]}"></script>'
                '<script>if("serviceWorker" in navigator)navigator.serviceWorker.register("/intern/sw.js",{scope:"/intern/"}).catch(function(){});</script></html>')
    if facemace:
        # Face Mace alone: the same page the desktop program (back/rust/facemace-desktop) serves; where the server
        # offers a photo folder (/photos), Face Mace can open it as "Your photos on this server"
        lib = ' data-library="/api/photos/list"' if photos_root() and photos_password() else ""
        return (f'<!doctype html><html lang="en"{lib}><meta charset="utf-8">'
                '<meta name="viewport" content="width=device-width,initial-scale=1"><title>Face Mace</title>'
                '<link rel="icon" href="/icon.svg">'
                f'<script type="module" src="/app/host.js?v={h.hexdigest()[:12]}"></script></html>')
    return ('<!doctype html><html lang="en"><meta charset="utf-8">'
            '<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no"><title>Piii Lab</title>'
            '<meta name="theme-color" content="#f7f5ef"><link rel="icon" href="/icon.svg">'
            '<link rel="manifest" href="/manifest.webmanifest">'
            f'<script type="module" src="/app/host.js?v={h.hexdigest()[:12]}"></script></html>')


if os.path.isdir(_FRONTEND_DIR):
    @app.get("/", include_in_schema=False)
    @app.get("/index.html", include_in_schema=False)
    @app.get("/app", include_in_schema=False)
    @app.get("/app/", include_in_schema=False)
    @app.get("/confirm", include_in_schema=False)
    @app.get("/confirm/", include_in_schema=False)
    def _serve_index(request: Request):
        """The site (owner, 2026-10-14: "remove all html and rewrite everything in rust only").

        /confirm/?t=… is the permission link sent by email: the Rust app reads the token from the address.
        """
        try:
            doc = rust_loader()
        except OSError:
            raise HTTPException(status_code=404, detail="The front end is not built.")
        headers = {"Cache-Control": "no-cache"}
        if IS_EXPERIMENTAL:
            headers["X-Robots-Tag"] = "noindex, nofollow"
        return HTMLResponse(doc, headers=headers)

    @app.get("/facemace", include_in_schema=False)
    @app.get("/facemace/", include_in_schema=False)
    def _serve_facemace(request: Request):
        """Face Mace alone, as in its desktop program."""
        try:
            doc = rust_loader(facemace=True)
        except OSError:
            raise HTTPException(status_code=404, detail="The front end is not built.")
        return HTMLResponse(doc, headers={"Cache-Control": "no-cache"})

    @app.get("/intern", include_in_schema=False)
    @app.get("/intern/", include_in_schema=False)
    def _serve_intern(request: Request):
        """Intern, the app: installable on a phone's home screen."""
        try:
            doc = rust_loader(intern=True)
        except OSError:
            raise HTTPException(status_code=404, detail="The front end is not built.")
        return HTMLResponse(doc, headers={"Cache-Control": "no-cache"})

    # python:3.11-slim has no /etc/mime.types to fall back on, so the types the site serves are registered
    # explicitly rather than left to whatever the container happens to know (WebAssembly must be
    # application/wasm).
    import mimetypes
    mimetypes.add_type("text/javascript", ".mjs")
    mimetypes.add_type("application/wasm", ".wasm")
    mimetypes.add_type("font/woff2", ".woff2")
    mimetypes.add_type("application/manifest+json", ".webmanifest")   # the self-hosted Geist typeface
    mimetypes.add_type("application/x-xpinstall", ".xpi")   # the Zotero plugin (frontend/zotero/scholarpi.xpi)

    # Mounted after the routes above, which answer the page addresses.
    app.mount("/", StaticFiles(directory=_FRONTEND_DIR, html=True), name="frontend")


if __name__ == "__main__":
    # one command line for what were separate scripts
    _cmd = sys.argv[1] if len(sys.argv) > 1 else ""
    if _cmd in ("cron", "--cron"):
        sys.argv = [sys.argv[0], "--cron"]
        _main_cron()
    elif _cmd == "reset-state":
        sys.argv = [sys.argv[0]] + sys.argv[2:]
        _main_reset_state()
    elif _cmd == "check-providers":
        sys.argv = [sys.argv[0]] + sys.argv[2:]
        _main_check_providers()
    else:
        import uvicorn
        uvicorn.run("api:app", host="127.0.0.1", port=8000, reload=True)
